/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090313-3","meetingId":"h21-c-budget","date":"2009年3月13日","dateIso":"2009-03-13","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を152件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"山内委員","kind":"質問","question":"環境問題の中で、地球温暖化について、基礎自治体としての役割をまずはどう考えているのかということを一つお伺いいたしたい。そういうことが必要なのかなと今後のことを考えますと思うんですけれども、それについての二つ、見解をお尋ねいたします。","respondent":"工藤環境課長","answer":"やはり今、温暖化問題というのは環境問題の中の最も深刻な問題だというふうに私どもは認識しております。自然エネルギーの導入に関してどういった形で考えているかですけれども、ＣＯ２を削減するために、事業をやっていかなければいけないと考えています。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"２点目のほうなんですが、あまり具体的な、まだそういうのはないのかなというところが説明がないですが、いかがなんか尋ねました。","respondent":"工藤環境課長","answer":"自然エネルギーの活用に関しましては、今さまざまな手法があるというふうに思っております。風力、私どももそういう認識の中で、今後そういった部分も含めて検討していかなければいけないというふうに思っているところです。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"キャリアを積んでふらふらしているものですから、あれっと思いまして、じっと見ていたんですね。昨年７月から対策が施行されましたけれども、７月１日から過料５万円を、何件あったのかを説明するよう求めました。","respondent":"島袋品川区清掃事務所長","answer":"現実に過料の５万円ですけれども、今のところはまだかけておりません。この場合には過料をかけられませんので、そういう状態になっています。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"保健指導費の２６３ページ、かかりつけ医のことでちょっとお伺いしたいんですが、こういう時期だからこそ私は大事なのかなと思うんです。例えば、大体区内の把握しているところで結構なんですけれども、やられているクリニックとか病院の数というのはおわかりになるのか尋ねました。","respondent":"山岡健康課長","answer":"今委員がおっしゃったように在宅医療をお求めになる方、当然その方も含めて医師会のほうで紹介をしております。ここの診療所がそれに対応できますよというような紹介を含めてやっているところです。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"このサービスというのは例えば見守りというんですか、こうやって普通に例えば１週間に１度とか行ってくださっていると、最後に答弁をお願いします。","respondent":"山岡健康課長","answer":"今おっしゃったような、そういう方にとってもかかりつけ医を持つ、ご自身のかかりつけ医を持つということが重要なことかと思います。ですから、ぜひ紹介窓口で紹介していただいて、在宅医療を含めた診療ができるような状況にしていただければというふうに思います。","id":"exchange-005"},{"speaker":"山元委員","kind":"質問・要望","question":"それから２８７ページのプレミアム付区内共通商品券発行経費助成という、この二つのことでお伺いをさせてほしいと求めました。今回、平成２０年度ですが、今現在でどのぐらいの方が受診なさっているか、おわかりになれば教えていただきたいんですけれども。","respondent":"山岡健康課長","answer":"今年度は２月末現在で４,６４７名の方が受診されています。ここまでで８,０００人の方が受診されております。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"平成１９年度で例えば子宮がんは８,２００人ということで考えますと、すごい受診率だなと、意識がすごく高くなっているのを感じております。昨年私が質問させていただいた中で、受付というんですか、教えていただけますか。","respondent":"山岡健康課長","answer":"一定期間を設けてその間に申し込んでいただく。その中で定員をオーバーした場合には抽せんする、こういうことを新年度からは考えておるところです。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"そういうふうになりましたら、なかなかつながらないとか、つながってもなかなか順番が来ないということが少しは緩和されるのかなと思います。前にも質問させていただいたんですが、そういう意味では広がる手だてといいますか、何かお考えはありますか尋ねました。","respondent":"山岡健康課長","answer":"今、そのうち二つの医療機関につきましては既に話が成立しておりまして、二つ合わせて年間にしますと１,５００人ぐらい対応できる予定です。これでもし足りない場合は、検診車の回数も増やしてまいりたいと、そのように考えているところです。","id":"exchange-008"},{"speaker":"山元委員","kind":"質問","question":"どんどん夢が広がってうれしいです。日曜日だったら行けるという方も中にはいらっしゃるかなと思いますが、土日にさせていただけるようなところというのはお考えか尋ねました。","respondent":"山岡健康課長","answer":"それから検診車も、土曜の配車が新年度は可能になりそうですので、検診車についても土曜検診ができる状況をつくりたいと思っています。今交渉しておりますが、ほぼ土曜日検診は何回かできそうですので、ご利用いただければというふうに思っております。","id":"exchange-009"},{"speaker":"山元委員","kind":"質問","question":"ここで乳がんのチェックといいますか、資料を見せながら質問をしたいと思いますが、委員長の許可をお願いしたいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"そうすると、自分の胸のこの辺をさわって何か感じるものがあれば、おかしいのかなということができます。案内を送るときに、できればぜひ皆さんに配ってこれを使ってほしいと求めましたが、いかがか尋ねました。","respondent":"山岡健康課長","answer":"現在の自己診断といいますか、自己触診につきましては毎年１回、３０歳になられた方に啓発のご案内を、チラシをお送りしています。これから何らか工夫ができればというふうに考えておりますけれども、チラシ、パンフレット等の啓発にとどまっているものです。","id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"では、時間がなくなってしまいましたので、２８７ページのプレミアム付区内共通商品券発行経費助成についてお伺いさせてほしいと求めました。定額給付金が決まりまして、この２,５４３万５,０００円の助成というのは、内訳はどういうことなのか教えていただけますか尋ねました。","respondent":"金子産業振興課長","answer":"まず１０％のプレミアムがつきますので、その分が、２億円発行いたしますので２,０００万円分になります。その他管理運営費等々、ＰＲも含めて、そういったものに助成する考えです。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"このプレミアム付商品券はどちらで売るようになるんか尋ねました。","respondent":"金子産業振興課長","answer":"この共通商品券ですけれども、区内満遍なくということで、区内の郵便局４３箇所、また中小企業センターにあります商店街連合会の事務局で販売する予定としております。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"いろいろな経済誌を見ましても、こうした中で品川区の経済はどうなっていくのかというところをまずお聞きします。今の状況の中で、昨年暮れから大変な状況にありますけれども、１０月ごろからの廃業件数あるいは倒産件数、この辺を教えてほしいと求めました。","respondent":"金子産業振興課長","answer":"工業を初めとしたそういった産業の活性化とイコールになるものだというふうに考えておりまして、さまざまな支援策をこれまで講じてまいりました。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"２３区との比較でいえばこの構成比というのはかなり長期にわたって２０位前後という産業経済費だったんです。実際に２３区で工業関係、少なくとも構成比についてもう一度見直していくべき時期ではないかというふうに思いますけれども、この辺はどうか尋ねました。","respondent":"金子産業振興課長","answer":"先ほど企画財政課長からご説明申し上げたとおり、予算面についても区の中小企業に対する姿勢をはっきりあらわしているのではないかなと考えています。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"ですから、この辺の構成比についてはしっかりともう一度見直すべきではないかというふうに思います。もう一つお聞きしたいんですけれども、この辺を区内の中で放棄をする、こういうことは私は許されるべきではないと思います。","respondent":"金子産業振興課長","answer":"ご案内のとおり、今の質問を中心に考えますと、東京商工会議所の品川支部あるいは工場協会の加盟の問題かと思います。こういったことは必要だと思いますので、私どもも産業団体とともに、そういった取り組みというのはしていきたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"中小企業に努力を求めるのであれば、区がそれを上回る、そういう努力をして区内の産業や経済を守っていく、こういう立場に立つべきだと思います。年間１００億円の売り上げが目標だということですけれども、この辺の影響調査についてどう考えておられるのか、その辺も説明を求めました。","respondent":"金子産業振興課長","answer":"現在考えられているところでは、区内の商店街に対する影響というのは、今のところさほど大きくはないのではないかというふうに考えられております。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"車で郊外から来るだけではなくて、区民の皆さんも大勢あそこに買い物に来られるわけですから、その中で商店街に影響は当然出ているはずですよね。この新しいセンターが、大株主が東京都と２３区ですから、その辺の認識をちょっと説明するよう求めました。","respondent":"金子産業振興課長","answer":"今のご指摘ですけれども、私どものほうにまだ計画の具体的な部分というのは詳細が出ておりませんので……。","id":"exchange-018"},{"speaker":"石田（慎）委員","kind":"質問","question":"私は２５５ページの新型インフルエンザ対策経費についてお伺いします。平成２０年度は約２６０万円の対策費だったので１０倍以上になって、この対策経費の内容、少し予算内容を簡単で構いませんので示すよう求めました。","respondent":"吉田品川区保健所保健サービス課長","answer":"新型インフルエンザについてのご質問ですが、新型インフルエンザ対策の経費につきましては、講演会の経費が約１５０万円、ほかはほとんどが物品、感染防護服であるとか、あるいはマスク等の物品の整備となっております。","id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問","question":"主に備蓄についてお伺いをしたいのですが、まず初めに先日の他会派の代表質問でも、リレンザの備蓄をしてはどうだというようなご意見もありました。例えばその辺の活用をしたりというのも僕は一つの案だと思うのですが、区のお考えを説明するよう求めました。","respondent":"吉田品川区保健所保健サービス課長","answer":"予防薬、つまり感染した方と接触があった方への対応としての備蓄はないので、そのような活用も同時に検討していくという形になろうかと思います。要援護者支援につきましてですが、品川区では新型インフルエンザ対策を、保健所だけではなく、全庁的な対応として考えてあります。","id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"次に、都との連携についてお伺いしたいのですが、どのような形で品川区にその備蓄品がおりてくるのかという流通の流れをお聞かせいただきたい。他区との連携、東京都と国の流通の連携と、近隣区においての連携というのはどのようなお考えがあるのか示すよう求めました。","respondent":"吉田品川区保健所保健サービス課長","answer":"近隣区との連携につきましては、近隣区を含めまして、担当者は会議を既に２回ほど設けております。その場で医療の確保あるいは通信であるとか、そういう連絡体制についても検討をしていくということになっております。","id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"品川区独自で、やはり近隣区との連携がどうしても必要だと思うので、ぜひさまざまな形で近隣区との連携を進めてほしいと求めました。そんな中、そこを軸に企業等にも啓発ならびにさまざまな取り組みをしていただきたいのですが、区内業者との連携について説明を求めました。","respondent":"吉田品川区保健所保健サービス課長","answer":"まず区内の各事業所自体が事業継続計画をおつくりいただくということで、その支援のために感染症対策のマニュアルを昨年９月に策定しています。今後は区内企業の連携もさらに深めまして、総合的に対策を進めていきたいと考えています。","id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"平成２１年度の予算、さまざまな区で目玉の一つとして新型インフルエンザが取り上げられていました。ぜひ今後も啓発ならびにさまざまな整備を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"次が２８５ページ、３目中小企業対策費、中小企業ワークライフバランス支援事業についてお伺いをいたします。そのときに、新しいデザインへの切り換えというのはどのようなお考えをお持ちか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"鑑札のデザインですが、本年４月１日以降の登録をもちまして新しいデザインというふうに考えて計画しています。それから、今ちょっと具体的には検討している最中ですが、再交付という形で手続きをとらせていただければというふうに考えているところです。","id":"exchange-024"},{"speaker":"井桁委員","kind":"質問・要望","question":"せっかく新しいデザインにするのですから、広くこのあたりの告知をしていただけたらなと考えています。ぜひ獣医師会とかそういった関係団体のほうにもぜひとも働きかけていただきたいと思うんですが、その辺のお考えをお願いいたします。","respondent":"荒井品川区保健所衛生課長","answer":"委員ご指摘のとおり、ＰＲにつきましては獣医師会あるいは動物病院等を通じて徹底させていただきたいと考えています。","id":"exchange-025"},{"speaker":"井桁委員","kind":"質問・要望","question":"都のほうでやっているということなんですが、東京都のほうで平成１９年４月に東京都動物愛護管理推進計画というのが出されていると思います。動物のための備蓄であったり、その辺への現状といいますか、そういったものがわかれば教えていただきたいと考えています。","respondent":"平澤品川区保健センター衛生課長","answer":"品川区におきましては「災害時における動物救護活動に関する協定」というものを平成１８年４月１日に取り交わしました。被災した動物の保護および管理、それから情報提供、こういったことについて協定書を取り交わしています。","id":"exchange-026"},{"speaker":"井桁委員","kind":"質問・要望","question":"次に、この制度は都の制度になりますが、品川区では現在平成２０年度で５名います。より密にとれると思っておるのですが、このあたりの区の考え方、保健所の考え方というのを説明するよう求めました。","respondent":"平澤品川区保健センター衛生課長","answer":"推進員の方につきましては、例えばですが、各種の講習会のときに出ていただきまして、私どもと一緒に動物の飼い方、ルール、そういうことについて、区民の皆さんにお話しするときのお手伝い、または講師といった面でお願いしています。","id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"次に移りまして、２６１ページの食からの子育て支援事業、食育推進事業についてお伺いをいたしたいと思います。この５カ年計画の中で、実感・成果というのがありましたら、お伺いしたいと考えています。","respondent":"矢野品川区保健センター保健サービス課長","answer":"今後の生涯を通じた食育の連携につきましては、平成１７年から庁内で検討を始めまして、今関係各課と連携会議を毎年持っております。今後、それを膨らませて、生涯を通じた食を通じた健康づくりを進めていこうと考えております。","id":"exchange-028"},{"speaker":"井桁委員","kind":"質問・要望","question":"その事業概要の中でちょっと気になったところをご質問させていただきたいと思うんですけれども、依頼による講習会というのがありました。平成１８年度が２２回、そういったものを加えてやっていらっしゃるのかなと思いましてお伺いしたいと思います。","respondent":"矢野品川区保健センター保健サービス課長","answer":"依頼によるという部分は地域の団体等の依頼により行っておりますので、周知はしておりますが、その年によって変わってきます。児童センター等との連携は毎年定期的に行っているという状況です。","id":"exchange-029"},{"speaker":"井桁委員","kind":"質問・要望","question":"次に移りまして、２７５ページのリサイクル推進費の資源化センター管理運営費についてお伺いいたします。その中でお尋ねさせていただいた人数とのバランス、非常にこう、その辺についてはどのようになっているか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"粗大ごみの持ち込みにつきましては、もう２年目になるんですけれども、かなり浸透しています。それによって対応するです。","id":"exchange-030"},{"speaker":"井桁委員","kind":"質問","question":"その手引書というんでしょうか、効率のいいマニュアルというのを今後また考えていく必要があるかと思うんですけれども、今後の対応についてはいかがか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"その対応があるんですけれども、その辺につきましても、その辺のことについても我々清掃事務所の職員が指導してまいりたいと考えています。よろしくご理解のほどお願いいたします。","id":"exchange-031"},{"speaker":"井桁委員","kind":"質問・要望","question":"そしてその中で、やはり実際に来所していただく方に対して、もっとアピールというのが必要なのかなと。その辺の今後、資源化センターの見せ方も考えていっていただきたいなと思っておるんですが、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"見に来たお客様が、屋根の上ですので、なかなか直接は見られないものです。今後パネルの設置をしているですとか、見学ができるように、その辺ちょっとお声をかけていただければというふうに思っております。","id":"exchange-032"},{"speaker":"井桁委員","kind":"質問","question":"２８５ページの産業経済費の３目中小企業対策費の中小企業ワークライフバランス支援事業、このことについてお伺いいたします。３月２日の区民委員会でも議案に上がりましたが、実際の申込件数の想定ですか、もしこれについての問い合わせというのがありましたら説明を求めました。","respondent":"金子産業振興課長","answer":"私どもご案内のとおり平成１８年からワークライフバランスの支援事業を実施しておりまして、既にコンサルタントでも４社ほど入っております。現在のところは問い合わせはまだございません。","id":"exchange-033"},{"speaker":"井桁委員","kind":"質問","question":"この申し込みの要件の中に、策定のワークライフバランスの推進に取り組んでいる、また取り組む計画がある中小企業とあるのですが、そういった計画を立てる際に、指針といいましょうか、指導といいましょうか、そういったものもやられているんか尋ねました。","respondent":"金子産業振興課長","answer":"次世代育成支援の行動計画の策定とその中身が具体的にワークライフバランスに資するものというふうにしておりますけれども、どういった形で実際に企業の中でできていくのかということをモデル事業で実施しておりまして、今後はそういうような対応もしていきたいと考えています。","id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"昨年の定例会でも私も質問させていただきました。平成２１年度の案内は、平成２０年度と比べてどのような工夫がされるのかなということについて、まずお伺いしたいと思います。","respondent":"山岡健康課長","answer":"平成２１年度につきましては、それから７５歳以上の高齢者の方につきましては、その通知に同封する形でご案内を出す予定です。それとあと、４０歳以上のそれ以外の方につきましては、私どものほうから個別でご案内を郵送するものです。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"一つ、やはり国保に加入されていない方、こちらの案内というのは非常にある意味では抜けてしまう部分だということで指摘もさせていただきました。平成２０年度ですけれども、実際にこの国保に加入されていない方に送られた数についてお伺いいたします。","respondent":"山岡健康課長","answer":"合計で２,８１１人の方にお送りしております。","id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"そのように、これは要望しておきます。ある意味では脚光を浴びないなと思うわけですけれども、男性のがんとして話題になっていないということも含めまして、この件についてお伺いします。","respondent":"山岡健康課長","answer":"それで、１月現在で既にそれを人数的にオーバーしているということもありまして、この辺をちょっと考えていきたいというふうに思っております。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"平成２０年度は８,０００件の予算で、やはりこのがんは年間３０万人亡くなる方がおられるということで、これに努めてほしいと求めました。予算も増加しておりますけれども、この組み替えというのはどういう考えに基づいて変更されたのか、平成２１年度の予算についてお伺いします。","respondent":"吉田品川区保健所保健サービス課長","answer":"その内訳を見ますと、２０代それから４０代をピークとするような働き盛りの方にかなり多いということがわかっております。しかも専門医による相談をできるような体制を強化するといったことが背景にあります。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"これはちょっと気になったところなんですけれども、精神保健福祉法に基づきまして、都に３カ所の総合保健福祉センターがあるかと思います。連携して何かをするような体制なのか、それとも全く関係なくて独立したものなのか、お伺いいたします。","respondent":"吉田品川区保健所保健サービス課長","answer":"品川区では中部精神保健福祉センターと連携をしておりまして、例えばケースカンファレンスであるとか、あるいは各種相談等、専門的な事項に関する相談等は随時させていただいているような状況です。","id":"exchange-039"},{"speaker":"浅野委員","kind":"提案","question":"昨年の第３回定例会で会派からも質問させていただきました沖縄県の総合精神福祉健康センター、このデイケアへの導入を提案をさせていただいたわけですが、お願いいたしますとの意見を述べました。","respondent":"吉田品川区保健所保健サービス課長","answer":"実際にうつ病の対策といたしましてＣＢＰが有効だということは十分承知しておりますが、区の中ではまだ検討を進めていないということです。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問・要望","question":"本区としてもこの助成制度の継続を要望しまして、国や都との制度との連携を図りながら、この件について質問します。平成２１年度予算だけで結構ですので、それとここ３年間の、年度ごとで新規で助成された台数についてお伺いいたします。","respondent":"工藤環境課長","answer":"装置装着助成が１０台、買い替え利子補給が２３台、合計３３台というふうになっております。そういった中で新年度の予算の額ですけれども、受付分が装置装着助成が１２台、購入の助成が１４台というふうな予算になっているところです。","id":"exchange-041"},{"speaker":"浅野委員","kind":"質問","question":"例えば電気自動車の購入で自動車税また取得税を５年間全額免除ということになったならば、これは大変な勢いで進んでくる。区のこれからのお考え、エコカーに対する考えについてお伺いいたします。","respondent":"工藤環境課長","answer":"来年度も引き続きそのような施策を実行いたします。都や国、いろいろな助成の動きを見まして区の支援も検討していきたいというふうに考えておりますので、よろしくご理解をいただきたいと思っています。","id":"exchange-042"},{"speaker":"渡部委員","kind":"質問","question":"衛生費の中で環境対策費と清掃事業費になるんでしょうか、ちょっと中長期的なことも踏まえて伺っていきたいと思います。時間があれば産業振興のほうに行きたいんですが、２点先に伺います。","respondent":"工藤環境課長","answer":"確かに白熱灯から蛍光灯、そして次世代の明かりが今ＬＥＤと言われまして、いろいろとメーカーもいろいろな型を今出し始めたところです。ＣＯ２の排出に関しても十分な削減効果が見込まれるということで、私どもも環境にやさしい製品だというふうに十分認識しています。","id":"exchange-043"},{"speaker":"渡部委員","kind":"質問・要望","question":"考えを伺わせていただきました。ぜひ導入をといいますか、実験をというんですか、最初の段階で進めていっていただきたいなと思って、この件は終わりにします。","respondent":"秋山資源循環推進課長","answer":"区民の皆様への告知ですけれども、平成２０年度になりまして、９月と１月と２回、広報の記事をお出しをして告知を進めているところです。そこなんですけれども、区民の皆様はそういう袋をお買い求めいただいて使えることができるというふうに考えてあります。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"ここで２３区の推奨のごみ袋がなくなったということは、２３区ではないんですけれども、実際にどうなんでしょう。２３区、長期的に見たごみの有料化等についてどのような考えをお持ちなのか、もしお答えできれば教えていただけますか尋ねました。","respondent":"秋山資源循環推進課長","answer":"袋を使うのか、それから一番大きなのは区民の理解をどのように得るかというような検討すべき課題が数多くあるという答申をいただいております。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"２３区全体で、現に東京都内におきましても市部では始まっておりまして、大半の自治体がそのようなことに動いていると思います。今高まっている時代ですから、住民の方々にも理解を得つつ進めていかなければいけないのかなと思いまして、今日質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"温暖化対策事業の中と、それから里山再生事業、早川町、蝶の道プロジェクト経費等についてお伺いします。この件につきまして、その内容、取り組み方等々について、もう少し詳しく教えていただきたいというふうに思います。","respondent":"工藤環境課長","answer":"グリーン電力活用事業につきましてのお尋ねですけれども、主な要因であります二酸化炭素の削減努力を続けてきたところです。今回、新たな削減手法といたしまして、グリーン電力証書システムを活用しまして、イベント時に使用する電力についてグリーン電力を購入するものです。","id":"exchange-047"},{"speaker":"本間委員","kind":"質問","question":"もう少し私たち区民として何ができるのか、事業者に対してはどのような啓発を行っていくかという形の中でとらえていたものですから。特にこの環境問題については大変大きなテーマではありますけれども、その観点からひとつお答え願います。","respondent":"工藤環境課長","answer":"このイベントは自然エネルギーを購入したイベントですよという形で、買った価値の部分を証書にして掲げましてイベントを実施したいと考えています。","id":"exchange-048"},{"speaker":"本間委員","kind":"意見","question":"さらにこの場面で環境対策費として１００万円そこそこの新たな予算がついている。この兼ね合いと、その環境対策費の観点からの部分は何をねらいとしてどのようなことをやるのか、説明を求めました。","respondent":"工藤環境課長","answer":"市町村交流事業で実施している早川町の里山を私ども環境の観点からちょっと見つめ直しまして、この新規事業を立ち上げたところです。内容としましては、早川町里山再生活動に習熟したメンバーを基本構成員としまして、また新たに区民の皆さんを募りまして実施するものです。","id":"exchange-049"},{"speaker":"本間委員","kind":"質問","question":"これも１５０万円そこそこついておりますけれども、去年、幼保一体施設の二葉すこやか園での件がテレビで放映されておりました。その部分で、この蝶の道プロジェクト経費は、どなたがどのようなところでどんなようなことを進めていくのかという観点からお聞きしたいと思います。","respondent":"工藤環境課長","answer":"蝶の道プロジェクト経費の内訳ですけれども、蝶の生息環境づくりを行い、蝶を増やす活動により、都会の自然を再生するものです。これが３４万円、そちらのほうが１２５万円、合計１５９万円計上しているものです。","id":"exchange-050"},{"speaker":"本間委員","kind":"質問・要望","question":"特に勝島運河のほうでも黒いアゲハチョウというんですか、そのような食草園の育成を見たことがあります。私たちがもしできるとするならば、どんな取り組みがあるのか、わかる範囲内で教えてほしいと求めました。","respondent":"工藤環境課長","answer":"本年度、平成２０年度は食草園が６カ所増えまして合計３１カ所ということで、このプロジェクトも少しずつ広がりを見せているところです。","id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"私は、２５３ページ、休日診療費、２８１ページ、観光アクションプラン、２８３ページ、中小企業支援費、この３点で伺わせていただきます。大みそか、あるいは元旦、２日と激痛に襲われた中で、そういった意味も持って当事者意識を持ちながらちょっと伺いたいと思いました。","respondent":"山岡健康課長","answer":"それから、これは今休日診療ということでお答えしました。は夜間あるいは土曜日の小児診療なども対応しています。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"強いて言えばという課題を伺えればと思いました。","respondent":"山岡健康課長","answer":"例えば夜間診療、これは平成２０年度から昭和医大の病院の中で設けていただいてやっているところです。かなり数が、こういう場合には平日でよろしいのではないかといったような周知をしてほしいといったようなご意見もいただいているところです。","id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"中小企業支援ということで伺いたいと思います。実際にこの融資に限定して伺いますと、想定に対してここまでの最新の相談等、申し込み状況を伺えればと思います。","respondent":"金子産業振興課長","answer":"そのうち相談されていかれましたのが４,０８５件、それからいわゆる５号認定、そちらの認定証を発行したのが２,１８５件。それから１月２０日から新たに始めました経営支援資金、これが４９８件、以上のような状況です。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"提案","question":"それとは別に、あえてちょっと視点を変えた形で提案的な質問をさせてほしいと求めました。求められるサービスも違ってくると思うんですが、この辺の考え方を大まかで構いませんのでまず１点目に伺いたいと思いますとの意見を述べました。","respondent":"金子産業振興課長","answer":"そういう意味では、私どもとしましては、どうしても返済できない方にも何らかの方策を考えていかなければならない。対応していかなければならないというのが、今持っている大きな課題かなというふうに考えてあります。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"２６９ページ、地球温暖化対策地域推進計画策定費について伺いたいと思います。計画の内容についてお伺いしたいんですが、うち３名を区民公募するということで、３月末までそうした委員を募集しているということです。","respondent":"工藤環境課長","answer":"一応２０名予定しておりまして、私どもが考えておりますのが、その他の事業者を予定しています。数は２０名でもう少し、そういった中で、この２０名というのが適切な数字ではないかというふうに思っておるところです。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"基準年ですから、削減目標の基準年は１９９０年度ということですべきだと私は思うんですが、いかがでしょうか。審議内容項目の中で、品川区内の地球温暖化の現状分析と課題の抽出というところがありますけれども、それはどのように行うのか尋ねました。","respondent":"工藤環境課長","answer":"その中で、さまざまな手法を用いて削減に向けてアプローチしていきたいというふうに考えているところです。今後、区の地域事情を十分に考えまして、今後検討していきたいというふうに思ってあります。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"全世界が１９９０年度比に照らして、そこはぜひ１９９０年度で考えていくような方向で区としてもぜひイニシアチブをとってほしいと求めました。は太陽熱温水器設置工事もあわせてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"広げていくべきだと思いますけれども、これはやはり削減していくということを区として計画を立てるわけですから、その上で。実績がどうかということと、あと、これを抜本的に引き上げるべきではないかというところに関して、環境課の考えはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"地域推進計画を策定するに当たって、所管課の環境課といたしまして、区内の住宅に自然エネルギーをどれぐらい増やすかという数値目標というのも盛り込むべきだと思うんですけれども、お考えはいかがか尋ねました。","respondent":"工藤環境課長","answer":"先ほど申し上げましたように地域推進協議会ということを立ち上げて検討するわけですけれども、同時に区役所内、同時並行的に検討していく予定です。そういった中で、先ほどご質問にありました環境共生住宅との関係という部分も充実、検討するということになろうかと思います。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"あるいは小型風力発電機などの設置などは進めていくべきだと思いますが、義務づけを行うべきだと思いますが、いかがでしょうか。区として推進しているわけですから義務づけを行うべきだと思うんですけれども、こちらの考えはいかがか尋ねました。","respondent":"工藤環境課長","answer":"その考えには変わりはございません。都条例、環境確保条例のほうでもさまざまな今規制がかかるところですので、その中でなされるものだというふうに考えております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今のところでもう１回お伺いしたいんですけれども、可能な努力というのではちょっと足りないと思うんですね。その数値目標をきちっと今度策定する計画の中、実行計画の中でも明確に目標として掲げるべきだと思うんですけれども、いかがか尋ねました。","respondent":"工藤環境課長","answer":"先ほどご答弁しましたように、繰り返しますけれども、方向性としては私どもは新築、改築の機会をとらえて太陽光発電等を設置しています。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"ですから、このサーマルリサイクルでどれだけＣＯ２が排出されるのかということは、区としてきちんと測定していくべきだと思います。今後の計画の中で、地域推進計画の中で、区としてきちんと測定するというようなことでよろしいのか尋ねました。","respondent":"秋山資源循環推進課長","answer":"サーマルリサイクルによるＣＯ２の効果ですけれども、委員がおっしゃられたような清掃一部事務組合からのデータによるプラスチックの温室効果ガスの増加というようなことや、メタンガスの削減というようなことで、影響ということは出ております。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が部門別にしっかりと区内の排出の現状を把握した上で対策を立てるという方向性ですから、燃やすごみが１３.１％増加したと。増加がどれぐらいなのかということは測定すべきだと思うんですけれども、これはぜひ実施していただきたいんですけれども答弁をお願いします。","respondent":"秋山資源循環推進課長","answer":"清掃一部事務組合は２３区共同設置の組織ですので、当然調査のほうは責任をもってやっているというふうに考えております。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"区自身できちんと区内のプラスチックごみを燃焼したことによるＣＯ２増加量をはかっていただきたい。強く申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"藤原委員","kind":"質問","question":"それと中小企業の融資なんですけれども、産業経済費が８１％増ということで、一般の区民の方にとってどういうメリットがあるのか教えてください。３月に定額給付金という形ですが、もう商品券を出す日付は決まっていると思いますが、日付を説明するよう求めました。","respondent":"山岡健康課長、金子産業振興課長","answer":"健康づくり宣言認証制度についてご説明いたします。区民の皆さんがそれぞれ今後も引き続いて健康づくりに取り組んでいただける、そういうことを期待して、この事業を実施するものです。私どもの実施しております融資あっ旋制度を拡充しているわけですが、それの一般の区民のメリットについてというお尋ねです。","id":"exchange-066"},{"speaker":"藤原委員","kind":"質問","question":"そのときの区の負担というのはどういうふうになっているのでしょうか。４月２０日ということですけれども、私も一般質問をさせていただいて、年度中にもう一回やってほしいというお願いをさせていただきました。","respondent":"山岡健康課長、金子産業振興課長","answer":"それから、飲食店につきましても、なかなか飲食店の場合は小さい店舗ですと、禁煙というのは難しいということがあります。そういうふうな側面で、できるだけ喫煙対策というんですか… 制度上そうなっております。それから、プレミアム付商品券ですけれども、これにつきましては、やはり今後の経済情勢を鑑みながら、また検討してまいりたいと考えています。","id":"exchange-067"},{"speaker":"藤原委員","kind":"意見","question":"すごく、２億のというのは。もうちょっと何か検討の中でもどういうふうに、という形で出てきてもいいと思うんですけれども、との意見を述べました。","respondent":"金子産業振興課長","answer":"商品券のほうからお答え申し上げますが、先ほど申し上げたとおり４月２０日の予定で準備を進めております。そういった判断は適切に行われているのかなというふうに考えているところです。","id":"exchange-068"},{"speaker":"武内委員","kind":"提案","question":"私は平成１８年、一緒にマタニティマークバッジなんかをつくってお渡ししたらどうだという提案をさせていただきました。平成１９年４月から母子健康手帳の修正の中に、これが今どうなっているかという確認と、この辺の状況を教えてほしいと求めました。","respondent":"山岡健康課長、工藤環境課長、金子産業振興課長","answer":"新年度からはそれを使ってマタニティマークをさらに普及させたいというふうに考えております。実は平成２０年度１月末現在では３８組ですが… 平成２２年度で、それぞれ２万世帯に助成するということを聞いておりまして、予算規模としては９０億円。東京都の制度としましては… ご指摘のとおり山王銀座商店街は道路を隔てて品川区と大田区になっております。","id":"exchange-069"},{"speaker":"武内委員","kind":"質問・要望","question":"トータルの人数を教えてもらいたいということと、まだ１年余りなので、それについての現況をお知らせいただきたい。それは大田区について、この件について何か呼びかけて、一緒にやりませんかというようなことはされたのかどうか説明を求めました。","respondent":"山岡健康課長、金子産業振興課長、工藤環境課長","answer":"それから平成２０年度から妊娠に至ったかどうかということを、この医療費助成のところで申請のときにお聞きをしております。… 先ほどちょっと説明が悪かったかもしれませんけれども、あくまでも品川区の商店街に属している限りは可能であるという意味合いです。… は区のほうが１０分の１ということで、３０％の助成ということでわかりやすく紹介……。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"もう１個については、太陽エネルギー見本市等についての「等」についてちょっとお伺いをいたします。自然エネルギーを導入し、そこのところを午前中のご答弁を踏まえまして、もう一回この必要性を伺いたいと思います。","respondent":"工藤環境課長","answer":"温暖化対策の意義ですけれども、午前中の答弁とも重なりますけれども、やはり世界的に今、温室効果ガスの削減というのが大きな課題となっています。そういった中で、区としてもできる最大限のことをやるということで、今回この推進計画を立てたものです。","id":"exchange-071"},{"speaker":"大沢委員","kind":"提案","question":"それと高遮熱のガラスですか、それを積極的に取り入れるような提案を環境課としてやっていく必要性があると思うんですけれども、そこのところは今後どのように連携をとりながら進めていかれるのかご答弁くださいとの意見を述べました。","respondent":"工藤環境課長","answer":"その取り組みの中で、温室効果ガス排出抑制のための検討としまして、私ども検討課題を挙げております。そういった観点から今後進めてまいりたいというふうに考えております。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"この区有施設におきましても、低エネルギー化に向けた取り組みを区は率先してやっていただきたい、そういうふうな思いがあります。そのような取り組みというのは可能であるのか、もし可能であるならどのような流れの中で行われるのか教えてほしいと求めました。","respondent":"工藤環境課長","answer":"白熱灯から蛍光灯への取り組みというのは、今さまざまな形で広がっているというのが現状です。いろいろと施策を打っているところでございまして、当然区のほうもそれを受けまして、そのような考えで進めていきたいというふうに考えております。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"この省エネ家電について、都の事業も踏まえて、区では省エネ家電購入についての何か支援促進の策というのはあるのでしょうか。教えてほしいと求めました。","respondent":"工藤環境課長","answer":"そういった中で、区が今後どのような形で支援するかということになろうかと思います。購入に際して補助、助成等導入を促進できるもの、そういった部分があるのかどうかという部分を考えていきたいというふうに思っております。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"では、次の太陽エネルギー見本市等という、こちらのほうの質問に移らせていただきます。確認をさせてほしいと求めました。","respondent":"工藤環境課長","answer":"対象イベントに関しましては、私ども、エコフェスティバル、防災フェア、まちづくり事業展、この三つを来年度は考えているところです。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"この中でグリーン電力という部分で三つ例が挙げてあります。このグリーン電力証書によるこの三つのイベントによる使用電力をグリーン化することができるのかどうかを教えていただきたいです。","respondent":"工藤環境課長","answer":"それと同等な部分をいわゆる販売によって購入するということになります。その購入によって、このイベント等が自然エネルギーを使ってされたというふうにみなされるです。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"購入という言葉とみなされるという言葉を今いただきましたので、ではみなされる部分で、この購入した電力量はどのくらいを見積もりを立てていらっしゃるのか、数字が出ていらっしゃるのであれば教えてほしいと求めました。","respondent":"工藤環境課長","answer":"防災フェアに関しましては５００kW分、まちづくり事業展に関しても同様に５００kW分というふうに考えております。全部で２,０００kW分を購入するです。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"この証書で購入する、これはわかりやすい制度でありますので、基本的なところをお伺いしたいと思います。この証書で購入する自然エネルギーの種類、１０種類ぐらいあると思いますけれども、これは何かちょっと教えてほしいと求めました。","respondent":"工藤環境課長","answer":"今、市場に出回っているというものであれば、風力発電が市場に出回っているものが一番多いです。そのほかに水力、バイオマスという部分も市場に出回っているというふうに聞いております。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは疑問なので伺わせていただきたいんですけれども、私は浅いながらも自分自身の考えの中で結論が出たんですけれども、そこのところはどういうふうにお考えになりますか尋ねました。","respondent":"工藤環境課長","answer":"いわゆるカーボンオフセットというバイオマスで発電した部分に関してはＣＯ２の排出ゼロだという概念で用いられているものです。なかなか精製が難しいということで、市場に出回っている部分としては少ないというふうに聞いているところです。","id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"近隣の自治体との関係について伺わします。このグリーン電力証書によって、この取り組みについて、品川区としてではなくて課長のご感想でいいのでお答えほしいと求めました。","respondent":"工藤環境課長","answer":"今、委員のご質問のほうも、どちらかの地方自治体で利用しているということだと思います。私どもとしましても、そういった形で活用しているという例もとらえておるところでございまして、今後、その動きを注目しています。","id":"exchange-080"},{"speaker":"稲川委員","kind":"質問","question":"２６９ページ、温暖化対策事業、２７１ページ、マイバッグ運動推進事業、２７５ページ、資源持ち去り防止対策費についてお伺いをいたします。温暖化対策の中の、先ほどもさまざまな委員の皆様から質問がございましたが、太陽エネルギー見本市についてお伺いをいたします。","respondent":"工藤環境課長","answer":"そういった部分がございまして、私どもとしましても、家庭部門のＣＯ２の削減対策の必要な柱として位置づける必要がある。そういったところからこの事業を計画したところです。","id":"exchange-081"},{"speaker":"稲川委員","kind":"質問","question":"このプレスには書いてあるんですが、太陽エネルギーの効果が大きい夏季で土日を含めた連続５日間と限定されているんですが、なぜ夏季だけなのか。例えば５月に行われるエコフェスティバルですか、やはりこういうものは区民の目に触れさせるべきだと思うんですが、お伺いします。","respondent":"工藤環境課長","answer":"私ども、夏の連続５日間ということで予定しています。ロビーだけではなくて、例えば公園とかロビー等、場所を工夫しまして大々的にやっていきたいというふうに考えております。","id":"exchange-082"},{"speaker":"稲川委員","kind":"質問","question":"ただ、設置をした人たちというのはもう１０年以上それをつけておくわけですから、こういうものが太陽光ですよということをやってください。もう１点、これは表に出すべきことではないと思うんですが、これから建てようという人を対象としているのかを１点お伺いいたします。","respondent":"工藤環境課長","answer":"個人だけではなくて、当然メーカー等もそこの部分に来ますので、対象は広げて区民の皆さんすべてというふうに考えているところです。そういった中でアンケートをとりましたり、我々の環境に関してのイベント等もその中で紹介をしていきたいというふうに考えております。","id":"exchange-083"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ、進めていってほしいと求めました。店箸というんですか、ご努力に対してのインセンティブというか、そういうものがあるかどうか説明を求めました。","respondent":"工藤環境課長","answer":"私ども、昨年「地球にやさしいお店」発見ということで、ホームページ上にさまざまな環境に際して推進している取り組みを紹介しております。そういった中で、このマイ箸運動と絡めてＰＲをしていきたいというふうに思っております。","id":"exchange-084"},{"speaker":"稲川委員","kind":"質問・要望","question":"次に、２７５ページの資源持ち去り防止対策についてですが、もう時間がございませんので、先ほどもこの件について、区の回収が増えたです。遠くにトラックが見えるというケースもありますので、ぜひこの事業に関しては、これからも継続をしていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"市川委員","kind":"質問","question":"２００９年度が１億８,０００万と年々分担金が増加しているんですけれども、この辺が増えている理由について教えてください。それからもう１点は、昨年の４７５万２,０００円から増額となっているんですけれども、この増額の理由についてもお聞きします。","respondent":"秋山資源循環推進課長","answer":"２３区がごみ割、分担金をそれぞれ負担をしておりまして、その内訳というのは特にはありません。プラスチックの中間処理経費、平成２０年１０月から開始をしたものですので、これは通年化によって増になっているです。","id":"exchange-086"},{"speaker":"市川委員","kind":"確認","question":"私たちも京浜島のエコセンターのほうに見学に行きまして、その状態のよいのは確認することができてとてもうれしく思っています。もう１点、品川区の分別収集計画の平成２１年度の２,００７ｔというのは、そこのところもお聞きしたいと思います。","respondent":"秋山資源循環推進課長","answer":"このＰＲについては引き続き継続的にいろいろな場面でいろいろな冊子等を使いながら実行していきたいというふうに考えております。排出量がおよそ２万５,０００ｔ、２万６,０００ｔ弱でありますので、２,０００ｔですから７.７％という状況です。","id":"exchange-087"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほどの２,００７ｔが排出量に対して何％かというような質問なんですけれども、そこのところはまた後でお聞きしたいというふうに思います。間伐材の割り箸の利用も進めるようにしていただきたいと思うんですけれども、この辺はどのようにお考えになるのか、お聞かせほしいと求めました。","respondent":"工藤環境課長","answer":"その中で、もしどうしても欲しい場合にはお箸を１膳１０円で買ってください、そのときのお箸というのは国産の間伐材を利用したお箸でございました。そのような取り組みを今後も、今回のエコフェスティバル等を含めましてやっていきたいというふうに考えております。","id":"exchange-088"},{"speaker":"市川委員","kind":"質問","question":"それから、マイ箸運動でもう１点聞きたいんですが、個人の利益でないものにつなげるように考えていくことはできないでしょうか。街路樹とかサクラ並木のオーナー制とか、そういう大きな視点でのお考えというのはどうか尋ねました。","respondent":"工藤環境課長","answer":"ポイントがたまった際の交換する啓発用品に関しましては、今ご提案の趣旨を含めて広く考えていきたいと思います。いずれにしましても、この啓発用品が環境意識の向上を図れるような形で検討してまいります。","id":"exchange-089"},{"speaker":"市川委員","kind":"提案","question":"ごみ減量の啓発というところで提案をさせていただきたいんですけれども、容器を持っていけば中身だけ買える飲み物の自動販売機というのがあります。区の施設において啓発には役に立つと思いますので、品川区でもぜひ設置の検討を進めていただければなと思うんですけれども、いかがか尋ねました。","respondent":"工藤環境課長","answer":"考え方としましては、やはりマイボトルというのが先だと思ってあります。今後検討していきたいというふうに思ってあります。","id":"exchange-090"},{"speaker":"市川委員","kind":"質問・要望","question":"エコへの関心が高まって、環境にやさしいグッズが増えてきていますので、いろいろなところで十分研究をしてほしいと求めました。健康に留意する家族というのは当然だと思って、あえて家族を含めたという理由について、再度になってしまうかもしれませんけれどもお聞きします。","respondent":"山岡健康課長","answer":"どこがだめとかいうことではなくて、健康づくりにこの単位で取り組んでいるよというふうなところには、ぜひ宣言をしていただいて認証していきたい。家族が健康づくりに取り組めば、いろいろな事業所、会社、団体、すべてそこにつながっていくんだと思います。","id":"exchange-091"},{"speaker":"市川委員","kind":"質問","question":"先ほどの答弁でも、今のご答弁でも、一人ひとりが主体的に取り組みをする意識を高めていくんだという意図は十分理解しました。健康を害している方たちにも配慮した取り組みというところを進めていってほしいと思っていますので、この辺についてのご見解を伺いたいと思います。","respondent":"山岡健康課長","answer":"先ほど申し上げたように、健康づくりに取り組むというのは、これからそれぞれの方が生きていく基本です。これは皆さんの健康につながれば、その意味でも経費的には２００万円程度の予算ですが、大きく医療費の削減につながっていけばと考えてやるものです。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問","question":"プラマークつきの、廃プラのことについて関連でお伺いをしたいと思います。廃プラの排出量の総数を把握しているのかどうか、その辺と、資源化量と燃やしている部分との割合がわかったら説明を求めました。","respondent":"秋山資源循環推進課長","answer":"プラマークのついたものの総量は、この統計は私どもは持ってございませんので、数値としてはわかりかねます。１３％が重量として増えているですし、そこでの数値ですと、品川工場で約１５％という数字が出ております。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民にどのように資源化を進めていく、アピールをしていくおつもりなのか、その辺を教えていただきたいんです。明確な、区民がやる気になるような働きかけをしてほしいと思うんですが、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"プラマークの資源につきましては１０月より収集をしておりまして、日量増加をしております。そういう中でのＰＲですとか、戸別収集の中で、分別の悪いところには直接職員が指導をするという形でＰＲのほうを進めていきたいと考えています。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"清掃の部門でどれだけのごみを減らしたらその６％が達成できるのか、そういった方向もぜひ示していただきたいのですが、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"もちろんごみの発生抑制というのがまず第一に来るのが基本ということはもう言うまでもないことですので、それにあわせてプラスチック類の資源化を私どもはしておりますので、その資源化を進めていく取り組みを区民ともども一緒に進めていきたいというふうに考えております。","id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"それから、２６５ページの保健所のほうなんですが、医師等とありますが、具体的にどのような方々でしょうか。その方々は、３７１ページに給与明細書がありまして、医療職の（一）から（三）とあるんですが、そちらのどこに当たるのか尋ねました。","respondent":"山岡健康課長、平澤品川区保健センター衛生課長","answer":"品川健康センターのほうは平成２１年度の予算では指定管理を実施する関係で、光熱水費等も含めて、これが入ってあります。平成２１年度から実施するというのは… 初めに保健センター関係の光熱水費ですが、年間で４,０００万円ほどの光熱水費がかかってあります。それと医師等の賃金についてなんですけれども、こちらは受託健診と呼ばれています雇上げの医師の賃金に充てるものです。","id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成２２年度以降、平成２２年度以降もこのような形で続けていっていただきたいのですが、どのような状況かということ。それは平成２１年度の品川区の予算には反映されていないので、どのような形で平成２１年度に検討されているのか、お願いします。","respondent":"金子産業振興課長、日下部企画財政課長","answer":"そういったことも想定しながら、私どもは商店街等々ともいろいろ今後商店街の振興についての施策を検討してまいりたいと考えています。これはご案内のとおり今の緊急融資については平成２１年度末… ですから今の段階で、これは大体対象が平成２１年度から平成２３年度までということで、ちょっとものによっていろいろばらつきはあります。","id":"exchange-097"},{"speaker":"本多委員","kind":"提案","question":"提案者であります参議院議員が国会で提案をされまして、国会のあと、そういったプロジェクトが全体に動き出しているんだと思うんです。そういう妊婦さんの家族とかだけではなくて、昨日は民生費に、一般に向けてどうそれを発信していくのかというところを教えてほしいと求めました。","respondent":"山岡健康課長","answer":"窓口にその関係のチラシあるいはポスターを貼ってということで、それにとどまっております。何かもっと一般の方に訴えるようなことができれば工夫してまいりたいというふうに考えております。","id":"exchange-098"},{"speaker":"本多委員","kind":"質問","question":"次の２８９ページの海外進出推進事業について伺います。それと、その継続性のある平成２０年度までで実績とされたものもあわせて説明を求めました。","respondent":"金子産業振興課長","answer":"国際化対応相談員ですけれども、毎日ではありませんけれども、二人の方を非常勤という形で配置する予定にしています。４社で、それから東南アジアで実施しておりまして、額は１７８万円余です。","id":"exchange-099"},{"speaker":"本多委員","kind":"質問","question":"これを続けていく中で、参加する企業の、リピーターといいますか、そういったものも可能なのか、それとあと補助額などについて概要を説明するよう求めました。","respondent":"金子産業振興課長","answer":"補助額ですけれども、３分の２を限度としまして５０万円を助成しています。５０万円限度ということです。","id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"通訳を使う場合なんですけれども、相当専門職ですとか専門用語のできる方でないと、なかなか通用できないと思います。そういった専門職といいますか、堪能な人材ができるような、そういった仕組みづくりを要望しまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほど４月２０日というふうに予定をされているということですが、この期日も含まれて郵送されるのか、教えてほしいと求めました。丸々１週間、区のほうからどういう要請をしているのか、そういう観点でお話を伺いたいと思います。","respondent":"金子産業振興課長、山岡健康課長、工藤環境課長","answer":"それから、それを補完する意味で、中小企業センターの４階の商店街連合会事務局でも販売するというふうにしております。… 地区の中から健康づくりに取り組んでいる、先ほど申し上げたいろいろな家族なり団体なりをお知らせいただければというふうに思っております。各種団体… この５日間で太陽エネルギーの利用実践セミナーというものを土日各日１回ずつ、セミナー、講演を行う予定です。","id":"exchange-102"},{"speaker":"若林委員","kind":"提案","question":"私は従前から、地域での公園を使ったそういう健康づくり事業みたいなところも提案をしたりしておるわけですけれども、ここら辺の。それから、環境情報活動センター、ぜひしっかりと行っていただきたいというふうに思っておりますとの意見を述べました。","respondent":"山岡健康課長","answer":"中心がふれあい健康塾ということで、室内を使った健康体操中心で、雨でもできるということでやっているところです。外でやる部分については今後の検討課題とさせていただきたいと思います。","id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"一応確認しておきたいんですけれども、夏季の労務環境に対して何らかの対策はとっているのかということ。それを受けて何らかの対策の強化みたいなことはされているのかどうかということもあわせて教えてほしいと求めました。","respondent":"吉田品川区保健所保健サービス課長、太田品川区保健センター大井保健相談所長、島袋品川区清掃事務所長","answer":"Ｈｉｂワクチンにつきましてですが、現時点では４月１日からの接種開始というふうに考えております。そのほかにもご希望の医療機関が６５医療機関が… 幼稚園、ほとんどのお子さんが通っているという前提で、昨日はお答えしております。チャイルドステーション事業等もありますので… それでかなり夏場はどうするか、水分補給しろとか言っているんですけれども、これはもう一回チェックする、そういう体制をとっております。","id":"exchange-104"},{"speaker":"阿部委員","kind":"質問・要望","question":"これは要望です。スクリーニングがないのであれば、ここの部分をぜひ力を入れてほしいと求めましたが、おわかりのことがあればお答えをお願いします。","respondent":"太田品川区保健センター大井保健相談所長","answer":"４、５歳児で在宅にいらっしゃるお子さんということですが、数としては１３９名ということだそうです。もちろんこちらで対応しないということではございませんので、相談があった場合には対応してまいりたいと考えています。","id":"exchange-105"},{"speaker":"阿部委員","kind":"質問・要望","question":"１３９人、家庭の状況がどうであるのかというのは、ぜひ積極的なアプローチをかけてほしいと求めました。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"最近はＰＭ２.５というもの、こういうことになっているんですけれども、こういう問題についての区の認識をまず伺いたいと思います。相談件数等々紹介がありましたけれども、先ほどの話ではよくわからなかったので、改めて教えてほしいと求めました。","respondent":"工藤環境課長、金子産業振興課長","answer":"大気汚染に関するＰＭ２.５、いわゆる微小粒子と言われているものです。粒子状物質のうち、呼吸時に気管を通り抜けて気管支や肺まで達するため、健康影響の可能性が懸念されているということは私どもも認識しております。先ほど別の委員のところでもご説明しました１１月４日から１月末までに実施しました年末対策特別事業資金、不実行が４９件ありますが、このうち。","id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"改めてその点でどうなのかということをちょっと伺っておきたいと思いますし、諮問した結論を早く出すことが今求められていると思うんですね。この点についての国の基準の設定を早くしろと、こういうふうな要請も含めて品川区のこの問題についての見解を改めて伺いたいと思います。","respondent":"金子産業振興課長、工藤環境課長","answer":"さまざまな経営相談に私どもは対応していますので、ぜひおいでいただいて、何らかの対応を一緒に考えていきたいというふうに考えているところです。それから、どういう方法をとればできる限り支援ができるかということで… 今、いろいろと学識経験者により構成される検討会を設置しまして、昨年からいろいろと議論しているという部分は注目をしておるところです。","id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそういう方向で探っていただきたいと考えています。そして、ＷＨＯの環境基準に見合う方向で答えを出すように要請をするべきだと思っているんですけれども、その点についてはいかがか尋ねました。","respondent":"工藤環境課長","answer":"私どもとしましては、やはり国や都でオーソライズされたものに基づき、区も対応するというのがまず原則だと思います。２３区環境課長会等で、早くこちらの件につきましては解明されるように国等に要請を続けてまいりたいというふうに思っております。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よくよく聞いたら今リボンでも２７０円だ、もうだめならだめと言うべきだろうと思うんだけれども、そこら辺のところの考え方を教えていただきたい。それから、これも１３５台というふうに今予算には出ているんだけれども、こういう形をちょっと教えてほしいと求めました。","respondent":"秋山資源循環推進課長、工藤環境課長、藤田道路公園課長","answer":"品川区で戸別回収をしておりますので、カラスに対する被害というのは減っているというふうにこちらとしても認識をしております。… マイバッグ推進運動のお尋ねですけれども、現在、参加商店街数が４４、参加店舗数が６００というふうにとらえております。今年度につきましては現在６件で、８３ｍほどの生垣の助成を行っているところです。全体計画ですけれども… 乾燥型とバイオ型とありますけれども１３８件、平成１８年が１５５件、平成１９年度が１０５件です。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ではこの部分で、少しでもやはりマイバッグ運動をまた持ち上げていこうとしているのかどうかということは、そこはもう一度思いの部分を語ってほしい。そういう考えを教えていただきたい。","respondent":"福田企画部長","answer":"この総合実施計画ですが、全部ではありませんけれども、こういうことをお示ししようと思います。実施計画にこうあるから予算もこうなんだというものではなくて、そういうふうな態度で予算編成は臨むべきだろうというのが私どもの考えです。","id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"２点目は２６１ページ、区民の方から相談をいただいたんですが、パルスオキシメーターということについてお伺いをいたします。２点目のパルスオキシメーターですが、肺機能の低下で苦しんでいる呼吸器機能障害の方が、その機能と働きについて教えてほしいと求めました。","respondent":"金子産業振興課長、吉田品川区保健所保健サービス課長","answer":"私どもとしましては、保証協会１００％保証の制度をつくることによって、こういう趣旨で実施してきているところです。ですが、返済能力を… パルスオキシメーターについてのご説明です。ご家庭でも簡単に、どなたでもご利用できるもので、肺の機能であるとか、あるいは体の酸素の状態そういうものを見ていくことができる機械です。","id":"exchange-112"},{"speaker":"山路委員","kind":"質問・要望","question":"国際規格のＩＳＯ２２０００という、地方自治体あるいは国、このＩＳＯ２２０００という食の安全の国際基準について教えてほしいと求めました。この返済期間の５年という、これを柔軟的に考えられないかどうか、この辺についてお伺いいたします。","respondent":"平澤品川区保健センター衛生課長、金子産業振興課長、吉田品川区保健所保健サービス課長","answer":"おそらく食品衛生法第１３条に指定されております総合衛生管理製造過程認証制度のことではないかと考えております。… 私どもいわゆる今回の緊急資金の運転対応のもの、何かちょっと別の要素が加味されたのかなというふうにお話を伺って感じたところです。パルスオキシメーターの金額についてですが、数万円から十数万円といった範囲で、機種によってだいぶ値段に差があるようです。","id":"exchange-113"},{"speaker":"山路委員","kind":"質問・要望","question":"数が多いようでしたら、これから何らかの形で研究、また助成のほうも検討していただくことを要望しておきます。先ほどのＩＳＯ２２０００ですが、これも今後検討していったらどうかと思いますが、どのようにお考えか尋ねました。","respondent":"平澤品川区保健センター衛生課長","answer":"３年に１回の更新が必要で、９万６,９００円の更新手数料、区内におきましてもかなり大規模なところでしか認証できないです。東京都のホームページ等にもありますとおり、また食品衛生の講習会等で、これについては普及啓発をしていきたいと考えています。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"それから、そこから得られた事業という形で１,１００万円のお金をかけて何をしようとしているのかということを教えてください。それから、しながわの一番店、これは数年していると思うんですが、これは何かいい効果があらわれているのかについてお聞きします。","respondent":"工藤環境課長、金子産業振興課長","answer":"今年度の実績、これは平成１９年度の実績値になるわけなんですけれども、基準年度比、前年度で１.５２の削減がされたです。そういった部分と連携しながら… 商店街の中でこういった事業を実施するには、一番問題になるのはキーパーソンだろうというふうな指摘をアドバイザーのほうから受けてあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"ですからそこは、その後、どう生かしていくかというのはそれぞれの商店でやっていかなきゃいけないことだと思います。その役割分担の中で成果が上がったりというような事例があるのかどうか、それからお考えをお聞きしたいと思います。","respondent":"工藤環境課長、金子産業振興課長","answer":"いろいろと今後削減を進めていくに当たりまして、企業の排出権取引という部分も新たな形で都の考えに入っておりますので、そういった部分。そういった部分も技術動向等を見据えながら… 行政がどこまで支援できるかというところで私どもも考えまして、ＰＲの支援をしていこうということで、広報にも載せましたし。それ以上については、やはり個店の努力というものが大切だというふうに考えておるところです。","id":"exchange-116"},{"speaker":"川西委員","kind":"提案","question":"これはこれでもう何回もご答弁聞いておりますから内容を伺っているわけではなく、清掃と関連して提案的な発言になりますけれども。週１回が多ければいろんな業者がいると思うんですよね、ですからどういう、この見本市を機会にやっていただければとの意見を述べました。","respondent":"山岡健康課長、吉田品川区保健所保健サービス課長、矢野品川区保健センター保健サービス課長、工藤環境課長","answer":"それから土曜日のほうは医師会と昭和医大でやっているものでございまして４６６万７,０００円です。前年度につきましては平日のほうが７３２万円… 続いて職員教育についてですが、一つは既に実施していますけれども、職員へ知識を啓発するといったこと。それからもう一つは… 保健所が１８回、保健センターが２４回、保険相談所が１２回ということで年間実施しております。保健相談所のほうは３名体制なんですが… 従来やっている部分を１回分私どものほうで環境の視点で対応するです。","id":"exchange-117"},{"speaker":"林委員","kind":"質問","question":"これやれ、非常におもしろいお話を聞いたんですけど、これからこの２,７００万円強のお金をどうするかというのを教えてください。もろもろ含めて、景気が悪くなってきているなというのは、どこでどの数字を見て判断するんでしょうかね。","respondent":"吉田品川区保健所保健サービス課長、伊勢危機管理室長、金子産業振興課長","answer":"それから区としてどういうふうに対応していくかですが、区民それから企業そして区自らといった三つの対象を対策の柱として考えております。… 新型インフルエンザに対する区としての取り組みですが、このほかに総務費の中で、危機管理室経費の中でも予算を計上しています。… 観光協会との関係なんですけども、これは私どもの認識とは違いまして、私どもは決してそういうつもりで観光課を設置したわけではございません。","id":"exchange-118"},{"speaker":"堺委員","kind":"提案","question":"この太陽熱を利用したエネルギー対策ということを提案してから、こういう視点に立ちまして積極的な設置推進をというふうに提案をしてまいりました。重ねて昨年第１回定例会でも、この太陽光発電システムの設置状況というんですか、お答え可能な範囲の中でお知らせほしいと求めました。","respondent":"工藤環境課長","answer":"今の状況で記憶しますところ、日本全国で２０万、３０万というふうに聞いております。いわゆる九州地方で２％ぐらい普及されている県があるというふうに聞いておりますけれど、都心部に関しては１％を切っているような状況です。","id":"exchange-119"},{"speaker":"堺委員","kind":"質問","question":"この場ではなかなか、環境課長のほうからは難しいのかもしれません。それがどういうふうな形で活用、利用されているのかということをお尋ねしたわけですが、それは大丈夫か尋ねました。","respondent":"工藤環境課長","answer":"区有施設での設置状況ですけれど、私ども把握しておりますのがいろいろとございまして、例えば防災センターの３階のロビーに照明をやっていましたり、戸越台の複合施設、品川区保健センター、しながわ中央公園の管理棟、あと学校等、このような形で私ども把握しています。","id":"exchange-120"},{"speaker":"堺委員","kind":"提案","question":"今年の１月３０日の衆議院の本会議で、このような提案を国会の場ではございましたが、させていただいたわけです。今、学校等も含めた更なる公共施設の設置推進ということなんですが、その辺についてのお考えはどうでございましょうかとの意見を述べました。","respondent":"工藤環境課長","answer":"私どもも、この設置に関しましては、建て替え、新築時に応じて積極的に推進しています。第一日野小学校、第三日野小学校ということで取りつけを行っている、設備の設置に当たりまして計画に入っているところです。","id":"exchange-121"},{"speaker":"堺委員","kind":"提案","question":"我が党は昭和６０年の予算特別委員会のときに、夏も冬も緑の創造に寄与するように努めていただきたいと、このような提案をさせていただきました。さらに積極的に推進をしていっていただきたい、こういうことをお願いをしたいわけですが、区のご見解をお知らせほしいと求めました。","respondent":"藤田道路公園課長","answer":"強度的な問題ですとかいろいろありますので、建て替え、そういったときに合わせて緑化をしていこうということでこれまで進めてまいりました。これから進めていく上では、この調査委託の中で、こちらの中で可能な施設について緑化を進めていくということで計上したものです。","id":"exchange-122"},{"speaker":"堺委員","kind":"質問・要望","question":"それから、３点目のＡＥＤの件です。ぜひ浴場組合等とも協議しながら、そういうところにもＡＥＤを設置してほしいと求めましたが、区のご見解をお聞かせほしいと求めました。","respondent":"山岡健康課長","answer":"組合とお話し合いをできればというふうに考えております。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"商店数も減少傾向にあるというお話でしたが、この数は、廃業や倒産してから廃業届等を提出した企業だけの数ですか。ではその運転資金はどうしているんですかとお聞きしますと、年金を使ったりして企業を存続させているという実態を聞いております。","respondent":"金子産業振興課長","answer":"産業振興について、主に２点のお尋ねかと思います。折に触れ、こういったところとの意見交換を進んでするようにしておりまして、こういったところで現況というのは把握するように努めてあります。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"区内の大半の企業を守れるんですか、存続させられるんですか、それをお聞きしたい。ですが、主な予算は区外に本店のあるゼネコンにほとんど流れていくというのはしょうがない、建てられないのですから実態はそうなっております。","respondent":"金子産業振興課長","answer":"私どもが現在実施しているのが、それも思い切った期間、思い切った額で実施しているというふうに考えてあります。今後とも区内中小企業に対して取り得る施策というのは、研究しながら状況を見て検討していきたいというふうに考えてあります。","id":"exchange-125"},{"speaker":"須貝委員","kind":"意見","question":"私はその１０倍の２０億円、例えば３０億円ぐらいの効果があるならば、地方自治体ができる唯一の方法だと考えております。最後に一言ありましたらとの意見を述べました。","respondent":"宮地区民生活事業部長","answer":"もう当然承知しておりますが、何にしても早く動くことと考えております。そういう中で一歩でも素早く動くというようなことを今後とも進めていきたいと考えております。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"５日前にテレビ朝日で戸越銀座商店街が映っていて、商店の経済動向どうだというのでアナウンスをしていましたけども、見た人いますか。２９１ページ、勤労者共済会運営補助、これはどのくらいの数の人たちが入って、どんなことをやっているか説明を求めました。","respondent":"金子産業振興課長","answer":"勤労者共済会のお尋ねです。共済会、現在会員につきましては、事業所数で申し上げますと２,２７９、会員数で申し上げますと６,６２７の会員で運営されているものです。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"会費がどの程度で、どんなことをされているのか、どういう恩恵があるのか、そのあたりがわかったら説明を求めました。","respondent":"金子産業振興課長","answer":"さまざま、例えば慶弔に関しての給付事業を行う。例えば年間６回ほどだったと思いますがバス旅行、区内の中小企業の勤労者の方の福利厚生を実施している、こういった内容です。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"これは内容的には先ほど本多委員のほうで質問しましたので、この事業と、品川区にあります国際友好協会等々の関連はなされているのかどうか。４月から組織改正で協働・国際担当というのができてくるんだけれども、説明を求めました。","respondent":"宮地区民生活事業部長","answer":"ここの部分を具体的に実践していくために、実際には、にぎわい部門を集中化した地域振興事業部というところでやっていくような形になっております。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"うーんと思っちゃうのが幾つかあるんだけれども、まず担当課長、健康というのはどういうふうに考えていらっしゃるんでしょうか。健康とは何か尋ねました。","respondent":"山岡健康課長","answer":"これはまさに、体も心も十分に生き生きと生かせるような状況、これを健康というふうに考えているものです。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"区長なら区長が顕彰する、何かやるんだろうと思うんだけれども、品川区の職員の健康状態はどうですか。そのあたりというのは、どういうふうに考えているんか尋ねました。","respondent":"山岡健康課長","answer":"要するに区役所も対象にしてまいりたい。そういうふうに考えているところです。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"そういった成長過程のところと、うちの健康課のほうと、どういう連携をとっているんですか。区民の健康ということをお考えになるなら、その教育委員会との連携はどういうふうになさっていますか。","respondent":"山岡健康課長","answer":"先ほどの認証制度のところで申し上げますと、それぞれのところで学校も含めて取り組んでいるところもあれば、当然認証の対象にしてまいりたい。そういう形で手を組んでやっていきたいというふうに考えているところです。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問・要望","question":"こっち右だ左だみたいな軽々なあれではなくて、考えていただいて、健康問題に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"まかり間違ったら、きちんとそこら辺をうたいながら進めていただきたいなと思うんですが、いかがでしょうかということです。ではダイオキシン対策でさまざまやっていくときにはどうなっていくんだろうかなというところをちょっとお伺いをしたい。","respondent":"工藤環境課長、秋山資源循環推進課長、金子産業振興課長","answer":"バーチャルエコ住宅に関しましては、今年度ぎりぎりになりますけれども、３月末までにホームページ上にオープンする予定になっております。… その他のプラスチックはどうかですけれども、その他のプラスチックにつきましては、燃やすごみという形で清掃工場で焼却処理をしておりますです。それから… ものづくり関係のご質問です。","id":"exchange-134"},{"speaker":"土井委員","kind":"質問・要望","question":"２３区の清掃一部事務組合の後ですが、東京都がそこまではやりますよというような話だったと思うので、そこら辺はどうなんでしょうかという意味です。それからものづくりですが、ぜひその辺。","respondent":"秋山資源循環推進課長","answer":"平成１２年度以降に発行したものもありますので、それも含めてということになるのではなかろうかと考えております。","id":"exchange-135"},{"speaker":"宮崎委員","kind":"確認","question":"この手引きについて伺いたいんですけれども、改めて区は行政としてどういうふうに対応していくのかということをちょっと確認しておきたいと思います。ねらいといいますか、そこら辺のところはどういうことなのか、伺っておきたいと思います。","respondent":"荒井品川区保健所衛生課長","answer":"そういう経緯がありまして承諾書の添付を削除した、こういう経緯があったというふうに認識しております。平成１２年度に都が条例を改正いたしまして、それから申請者との間でトラブルを防止するために、事前周知制度を導入したというふうに認識しています。","id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問","question":"協議、それが例えば協議終了ということがいいのかなと思うんですけれども、どういう状況になったら終了ということになるのか。協定を結ぶということそのものについては、保健所というか、行政のほうはどういうふうな指導をするんか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"その保健所に行いました意見申し出書の中で、墓地申請予定者と住民の間で話し合いを持ちなさいというようなことになってあります。ここまで協議が進んだということをお互いに認識し合うという、そういうような確認が行われた場合は協議の終了ということに見ることができます。","id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問","question":"そのとり方といいますか、それで変わってくるということが一つ心配なんですけれども、そういう点ではどうなのかということをお聞きしたいと思います。それとも話し合いの中で出てきたものは、それはそれで協議の対象にしていくことになるのか、どうなんでしょう。","respondent":"荒井品川区保健所衛生課長","answer":"協定の基準につきましては、先ほど申し上げたものを中心に協議をしていくように、申請予定者のほうに保健所としては指導していくです。やはり住宅街の中に墓地をつくるということであれば、申請予定者のほうには、できるだけ協議に乗るようにという指導をしてまいるところです。","id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問・要望","question":"狭い土地に３０２基なのでかなりの人が出入りするようになるのかなというふうに思うんですけれども、そういう点で区はどういうふうに考えているのか。そういうようなところで地理的な条件等も何か考えているところはあるのか、そこのところはどうか、お聞かせほしいと求めました。","respondent":"荒井品川区保健所衛生課長","answer":"墓地ができると人が集まる、あるいは交通量が多くなるのではないかというご心配ではないかと思いますが、その件につきましては、申請予定者のほうに十分にそういった配慮をするように指導していく予定です。","id":"exchange-139"},{"speaker":"宮崎委員","kind":"意見","question":"都会の墓地にふさわしい、そういうことで協議をしてほしい、そういうことだと思うんです。このお墓が小さくなってきたというのは、行政側はどういうふうに受けとめておられますかとの意見を述べました。","respondent":"荒井品川区保健所衛生課長","answer":"お墓の大きさにつきましては、保健所が判断するところではございませんので、ご了解いただければと思います。","id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問","question":"そこで、いわゆるお墓事情ということをどういうふうに受けとめているかということを聞いているんですね。いままで要するに東京都の条例をつくったときには、そういう角度から聞いているんですけれども、どうか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"保健所といたしましては、あくまでも公衆衛生上の観点からお墓の構造について設備基準に基づいて判断していくということになってありますので、ご了解いただきたいと思います。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、そういう問題ですから、これは今の答弁というのは私はちょっと納得できない。今回の事態も私は新たな事態だと思うんですけれども、改めて伺いたいと思います。","respondent":"古川児童保健事業部長","answer":"墓地を設置しようとする方と、今まさにそれぞれの立場で指導の範囲でご協議をしていただく、こういう段階です。最終的には墓地の設置基準等を勘案しながら最終的な判断をしていく、現時点においては指導をしているということでご了解いただければと思います。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、このお墓の数の問題というのは、それとまさに連動している問題だというふうに思います。それから産業支援のほうはちょっと時間がなくなりましたので、これで終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"ですからそういうふうなことで、そういうような心が引かれるような、そういう展示にしていっていただきたいなと。こういうことにもなりかねないということですから、それで集めていっていただきたい、いかがか尋ねました。","respondent":"工藤環境課長","answer":"私ども、委員ご提案の趣旨を踏まえまして、やはり大人だけでなく、子どもの方も来ていただくようなものにしたいと考えています。そういった部分で、そのような子どものコーナーも設けまして、いろいろと人が集まるような工夫をしてまいりたいというふうに思っております。","id":"exchange-144"},{"speaker":"三上委員","kind":"質問","question":"よろしくお願いしたいと思います。そういうことで、ハトのふん害での影響というものは人体的にあるのかないのか、どういうふうに今言われているか尋ねました。","respondent":"工藤環境課長","answer":"私ども、いろいろな苦情相談というのが寄せられております。東京都環境局のほうがいろいろとポスター等をつくっておりまして、そういった部分を貼っていただくとか、そういった形で対応しています。","id":"exchange-145"},{"speaker":"三上委員","kind":"質問","question":"ハトよけのいろいろなこともあると思いますけれども、こういったことについて、これから増えていくんじゃないかなという思いが私はしてなりません。ですから、そういった対策をやはり真剣に取り組んでいっていただくという、そういう窓口も必要ではないかと思いますが、いかがか尋ねました。","respondent":"荒井品川区保健所衛生課長","answer":"ハトの被害については個々に保健所でもお受けすることがあります。その場合につきましては、におい消しみたいな、そういったものをお渡ししたりして、当面は様子を見ていただくというような形で対応しています。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問","question":"続いてリサイクルのほうのレアメタルについてちょっとお伺いします。世界の埋藏量の約１６％に達するという、そういった点での今後の取り組みとして方向性をどういうふうにお考えなのか、ちょっとお伺いします。","respondent":"秋山資源循環推進課長","answer":"２カ月間で約２,０００台の携帯電話が回収された。小型電気製品につきましても、こういう東京都のリサイクルの内容も含めて、参考にしながら研究していきたいというふうに考えております。","id":"exchange-147"},{"speaker":"三上委員","kind":"意見","question":"時間がありませんので、また別な機会にいろいろなことを取り組みたいと思いますが、そういった点について民間への取り組みをどうするか。そういう現実を教えられてきましたが、そういった点についての取り組みについて、ちょっと時間内でお答えほしいと求めました。","respondent":"吉田品川区保健所保健サービス課長","answer":"先ほどもご答弁させていただきましたが、既に事業所に対しては、事業継続ができるようマニュアル等を区では作成しております。現在ご希望のあるところには啓発を行っていたところですが、事業所の皆様でご検討いただける場を区としても検討していくというふうに考えてあります。","id":"exchange-148"},{"speaker":"三上委員","kind":"質問・要望","question":"これが危機管理ということでしょうから、やはりこれは指揮をとる人がその決断というものをどう早く下すかということが大事だと言われてまいりました。各家庭にしてもそういうことですから、しっかりやはり訴えていくような仕組みというものを考えていっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、そういうところがどの程度進んでいるのか。この辺でまずどういうふうにやっていらっしゃるか、ちょっと教えてもらえたらと思います。","respondent":"工藤環境課長","answer":"家庭ＩＳＯの取り組みですけれども、こちらの家庭ＩＳＯは平成１５年度にまず開始されまして、ちょうど６年間を経過したところです。人数で言いますと２７８名でありましたが、平成２０年度は３７校全校、２,０８０の家庭で実施されているところです。","id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区の施設の中で、私も本会議の質問の中で、区の一事業者として平成１８年比１.５２％の温室効果ガスの削減をしたというお答えをいただきました。最初の初期投資はちょっとかかるかもしれませんけれども、その辺、何か施設の状況がわかることがありますか尋ねました。","respondent":"宍戸施設担当課長","answer":"しかもメンテナンスフリーということで、法の縛りがありますけれども補助的に設けるというふうなことでは可能かなというふうに思っております。都南病院跡地の高齢者施設でも、補助的な部分ですけれども採用したところです。","id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これが二つの部署が、まちづくり事業部が二つになることによって、事務方と現場的なものがどういうふうにうまく連携していけるのか。","respondent":"久保田環境清掃事業部長","answer":"ただ基本は、理念というものがしっかりあって、それに基づいたやはり啓発なり施策なりを展開してきたというのが一つであろうと思います。","id":"exchange-152"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":119685,"voices":373}},{"id":"h21-20090316-3","meetingId":"h21-c-budget","date":"2009年3月16日","dateIso":"2009-03-16","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"５項建築費、１目建築行政費の中の耐震シェルター等設置助成について、お伺いしたいと考えています。その中で、このエコライフ支援事業に至った経緯と、そして、現在の申請数を教えていただきたいと考えています。","respondent":"諸石交通安全担当課長","answer":"あわせて、免許を返納して自動車の利用を自粛することで、ＣＯ２の削減にもつなげていきたいと考えていたものであります。かなり厳しい目標だと感じていたんですが、実際は、既に３００名を超えているという状況にあります。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"この中で、特典が五つあって、その中で一番好評なものがあればお答えいただきたい。こういったチラシをどういったところで告知をしているのか、。","respondent":"諸石交通安全担当課長","answer":"それから、それに次いでタクシー券が２割弱ということで、その二つがご希望の大半ということです。鮫洲の試験場、区内の各警察署にチラシを配布しましてお知らせをしていただくという形で、やらせていただきました。","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"高齢者で持っていて、どうしようかなと思っている方であったり、この事業をさらに促進していっていただきたいと思うんです。その中で、住基カードを希望される方の割合というのがわかりましたら、お願いいたします。","respondent":"諸石交通安全担当課長","answer":"住基カードをご希望される方の割合ですけれども、希望者が７３.３％ということで、大半の方は希望するという状況です。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問・要望","question":"３２１ページの耐震シェルター等設置助成について、お伺いをしたいと思います。そのあたり、もう一度、耐震シェルターについての考え方をお伺いしたいと考えています。","respondent":"片田建築課長","answer":"耐震化促進計画の中では、建物の耐震化９０％という目標を立てて、基本的には建物の構造を高めるということを考えております。なかなかすぐにはできないといったような方もいらっしゃいますので、何とか命を守るということで、促進計画にも位置づけてきているものです。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"毎年２件ずつ実施しているということは伺っているんですけれども、何カ所ぐらいの計画というんでしょうか、実施する予定があるのかということ。いまだに、白い壁が続いているんですけれども、旗の台周辺の計画があれば、教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"今後の計画の予定ですけれども、まず平成２１年度は旗の台第２架道橋、これは大井町線にあります、それが１カ所。もう一つは百反架道橋といいましてＪＲ横須賀線、そこの２カ所を実施していく予定となっております。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"今は主流になっているかと思いますけれども、こういう流れは、今までどおりなのかということ。それから、地域の住民や商店街の方々の意向、またこういうものを描くことになったとか、そういう告知はされているのかどうか、お伺いします。","respondent":"松代管理工事課長","answer":"４年生、５年生ぐらいの子どもたちに絵を描いていただいて、実施をしたいと考えています。周辺の方々には、実際に施工するに当たってはお知らせをして、そういった効果をさらに高めていただきたいということで進めているものです。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"これからも美化に努めてほしいと求めましたので、この点もよろしくお願いします。こちらの緑道と公園の復旧ですけれども、簡単で結構ですので、こちらの水防の効果のほうからお伺いします。","respondent":"家壽田下水道河川課長","answer":"第二立会川幹線の整備効果ですが、この事業がすべて完成いたしますと、１時間に５０mmまでの降雨に対応できる、浸水が起こらなくなるです。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"工事期間が平成２２年１月２７日という日づけがありまして、公園前の緑道の復旧計画と、完成時期についてお伺いします。それから、住民の方々の意向、公園を今まで使っていた方もいらっしゃると思いますので、どのような形で反映していくのか、お伺いします。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"平成２１年度に設計に入りますので、または町会等々に今後の復旧内容等につきまして、話をしていきたいと考えております。完成時期は、平成２２年度に工事に入りまして、平成２２年度中に完成したいと考えています。 第二立会川幹線について、若干補足します。今現在、これが平成２３年度末に暫定開業しますが、完全に使えるようになるのは平成２３年度末以降です。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"長年、工事に協力されてきた住民の方々の意向をぜひとも反映した公園、また緑道にしていってほしいと求めました。これは２段階でやられるのか、そういうことも含めて、その観点でお伺いします。","respondent":"松代管理工事課長","answer":"下水道工事がすべて終わりましたら、公園部分の上部分の工事に関しましては、区が復旧費を下水道局からいただきまして、それで公園、緑道の改めての整備という形で展開しております。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"こちらについてお伺いしたいんですけれども、立会川緑道の両側ですけれども、こちらの勾配を解消されると聞いております。どうしてこのままで済んでいたのか、ほかにこのような検討しなければいけない箇所があるのかどうか、お伺いします。","respondent":"松代管理工事課長","answer":"これを何とかもう一度検討をして、緩やかな横断勾配にしたいということで、いろいろと調査・検討をしたいという内容です。ただ、歩道が狭い分、縦断勾配が狭くなっておりますので、そういう改良は、順次、別な路面改良でやっているところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"区民の皆様からの大きな要望だったかと思います。この調査というんでしょうか、設計のほうはかなり難儀かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"提案","question":"３１７ページの武蔵小山駅周辺地域整備事業、家屋被害の調査と補償について、お伺いしたいと思います。協議会のメンバーを公募してほしい、いろいろ提案をいたしましたけれども、どのように進んでいるのか教えてほしいと求めました。","respondent":"吉川住環境整備担当課長","answer":"平成１９年度に行いました地域のアンケート調査の結果につきましては、平成２１年度に、地域の方にお返しする予定です。その後の説明会、あるいは意見交換の方法についても、整備方針を定めるに当たっての住民の方の意見をいかに聴取するかについても、今後の検討です。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民の皆さんも、いろいろ地域の中で感じている中で、１年も経っているのに返していかないという宙ぶらりん状態でいいのでしょうか。どんな組織がつくられているのか、どんな方たちが構成メンバーになっているのか、その辺も説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"アンケート調査後、こういう方向でまちづくりを考えていますと、そういったことをまとめることを含めて説明していきたいという考え方からです。整備基本方針の案を、検討中ですが、地域の方に投げかけていくという予定でございまして。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助２６号線沿いの高層化が必要であるといった問題とか、行政の意思決定が必要です」と、かなりイメージが膨らんでいます。区は、このドリームプランにどうかかわっているのか、説明を求めました。","respondent":"青木都市開発課長、吉川住環境整備担当課長","answer":"武蔵小山駅周辺５６haの検討につきましては、地域生活拠点と位置づけていることから、そのまちづくりがどうあるべきかの検討を進めているものです。いろいろな地元で動いている考え方をどう評価して、アンケート結果も踏まえて… 整備基本方針の説明をさせていただいてきておりますが、先ほど、整備基本方針案の検討というのは全く別のものです。整備基本方針によって再開発が決まるというものではないということは、ご理解いただきたいと思います。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間、全区的に行われた家屋調査の件数と、未解決の部分がどのぐらいあるのか知らせてほしい。２００４年２月に小山五丁目近辺で、地下水が１カ月にわたって漏れてしまった、説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"そのうちの沿道について、１,４００件ほど説明会を行いました。これにつきましては、できれば、３月いっぱいということで考えているところです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこが開示されていないということでは、科学的に比較できないので、ぜひこの辺のご指導をしていただきたい。もう１点は、事業自体は４事業者ですけれども、その辺を説明するよう求めました。","respondent":"浜脇街路事業担当課長","answer":"最初の、地下水と家屋調査の関係ですけれども、それについては、私どもが持っている資料につきましては、開示しながら説明をしています。それから、財源ですが、４者の中の共同体の中で出資している全体の事業費の中で賄っているものです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"全体の事業費は、工事ミスや何かも公平に分担するんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"地下水につきましては、工事的なものですので、当然、工事業者からの負担も含まれてまいります。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"３１７ページの都市防災まちづくり事業費の中にある密集住宅市街地整備促進事業、３２３ページの環境共生住宅助成について、お伺いいたします。用地取得、先ほど旗台小学校ということをおっしゃっていたんですが、どういう用地を取得するのか、その件がわかっていたら説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"事業内容は建替助成でございまして、４地区実施をしておりまして、合計で１８棟の建替助成を予算案で計上しています。広場用地を１件、それから道路用地を４カ所計上しておりまして、６３５m2を想定しております。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"ちょっと質問は次に移りますが、実際に、街づくり特別委員会の中でも議論にはなっているんですが、荏原地区の中にいろいろ指定されたエリアがあるんですが、改めてお伺いいたしますが、何をもとにこの地区を指定したのか、説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"東京都の地域危険度測定調査で危険度が高い地域を、実際に現況調査をして指定して、事業を実施しております。これに対して、広域避難場所に至る避難道路を強化するために行う事業ということで、その事業目的に合わせて地域を指定しているです。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"地域危険度測定調査をもとにということだったんですが、都市防災不燃化促進事業と防災生活圏促進事業は、データがあるのか。何かをもとにして参考なりにして地域を指定しているのかどうか、説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"事業開始に当たりましては、例えば都市防災不燃化促進事業では、何棟建て替えることが必要かという事業計画を立てまして実施しています。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"今、ちょっと話の中で不燃化率とか、不燃領域率という話が出たんですが、不燃領域率と不燃化率とは、どういう意味だか教えていただけますか、簡単で構いませんので。","respondent":"吉川住環境整備担当課長","answer":"実は、かなり難しい数式があるんですが、簡単に言いますと、不燃化率というのは、建築物の不燃化率。不燃領域率になりますと、建築物の不燃化率以外に、例えば道路とか、広場とか、オープンスペースの領域も計算に入れて算出するものです。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"では、この不燃領域率の中で、高ければ高いほどいいんですか。ちょっとそれを説明するよう求めました。","respondent":"吉川住環境整備担当課長","answer":"不燃領域率の目標ですが、国のほうの考え方として、不燃領域率が７０％に到達すると、燃え広がらない安全なまちになるとしております。都区でつくった計画がございまして、平成２７年度に不燃領域率を５５％、平成３７年に７０％に到達させることを目標に実施しています。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"例えば密集住宅市街地整備促進事業の中で、戸越１・２丁目地区は終了地区としています、荏原北地区もあります。終了しているにもかかわらず４１％とかというのは、今後上がっていくのかどうか、説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"戸越１・２丁目地区について、お答えいたします。平成５年から密集住宅市街地整備促進事業を実施し、委員がおっしゃられたように４０％台と、地区計画を策定しております。","id":"exchange-023"},{"speaker":"稲川委員","kind":"質問・要望","question":"では、３２３ページの環境共生住宅助成。私は一般質問をさせていただいて、地域の建設組合などとの連携があるのかどうか、説明を求めました。","respondent":"齋藤住宅課長","answer":"これを使いますと、家一式２５０万円かかりますけれども、夏の間に２度、３度下がる。建設組合の方にいろいろ技術のこともご相談申し上げながら、品川区から、新しい遮熱性塗装を広げていきたいと考えております。","id":"exchange-024"},{"speaker":"稲川委員","kind":"意見","question":"今回、新規ということで、また、この助成制度ができたということも、区民の方に周知するためにさまざま区報、ホームページなどなどを利用して、とにかく周知されなければ、助成対象にした意味がなくなってしまうので、今後もぜひ、周知に努めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"時間が残るようであれば、もう少し広く伺っていきたいと思います。併用してより一層の効果が出てくるようなことがないのか、その辺をお聞きできればと思います。","respondent":"家壽田下水道河川課長","answer":"今後、来年度行います目黒川の浄化実験の成果を踏まえて、都と区と、整備についてしっかり検討していきたいと考えています。その浄化の効果なんかもあわせて、目黒川に何が一番ふさわしい浄化なのかということを、引き続き検討してまいりたいと思います。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"平成２４年、平成２５年、五反田から大崎に抜けるところでキャッツシアターも閉まってしまうというような状況があると聞いているものですから。お願いいたします。","respondent":"家壽田下水道河川課長、青木都市開発課長","answer":"そうではありませんで、この６０％のエリアで雨水の流出抑制をやっていただきますと、回数とか量を減らすことができます。直接その川の浄化に関しても、世田谷区にもちゃんとテーブルについていただいていますので… 戦略の４番目として、目黒川を環境資源として活用するというテーマを掲げまして、これまでにもいろいろな検討を進めてまいりました。","id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"ですから、一般質問でもさせていただいたんですけれども、人の動きという流れがいろいろな形で変わってこようかと思うんです。ですから、その辺のところで、人数的な問題ですとか、そこの辺をどういうふうにとらえておられるか。","respondent":"青木都市開発課長、藤田道路公園課長","answer":"ご案内のとおり、業務施設の整備と同時に、住宅の建設も進めておりますので、ご指摘のとおり、昼夜間ともに人が増えることが見込まれてあります。ご期待ください、お願いいたします。 今回、平成２１年度の予算に水辺の実態調査というものを取り込もうということで考えております。この辺を、まず実態を把握する中で、次のステップにつなげていくためのものにしていきたいと考えています。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、３１１ページ、都市計画総務費の中のやさしいまちづくり推進費の中の、駅エレベーター設置助成について、お伺いしたいと思います。それから、もう一つは、３１５ページの公園新設改良費の中の鮫洲運動公園改修基本・実施設計について、こちらも伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"私から、やさしいまちづくりの駅エレベーター設置について、ご説明申し上げます。平成２１年度に予定しておりますのは、青物横丁の部分の２基ということでして、そういうことではございません。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"今年は青物横丁に設置されるですけれども、具体的にどの辺に設置されるのか。工事はいつごろから始まるのか、もちろん４月以降でしょうけれども、予定ではいつごろから工事が開始されるのか、もう決まっていますか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"工事の時期については、申しわけございません、まだ私どもは把握してございません。改札口を入りますと、その途中のところに、エレベーターを上り下り各１基ずつ設置するというような話は聞いております。","id":"exchange-030"},{"speaker":"山元委員","kind":"意見","question":"エスカレーターが怖くて、上がるのがとても怖いということで、そういう意味では鮫洲の駅の方たちは大変喜んでいるんです。今のお話ですと、青物横丁は、改札までは階段、もしくはエスカレーターで行かないとエレベーターには乗れないことになりますかとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"あくまでも予定の話だと聞いておりますけれども、私の把握しているのは、そういうことになるかと思います。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひ、その辺を考えてほしいと求めました。まだ先かと思いますが、どのように予定されていらっしゃるのか、教えていただけますか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"新馬場につきましては、ご指摘のようにエスカレーターということで、エレベーターがついておりませんけれども、平成２２年度、エレベーターの設置事業を目指しているという話を聞いております。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"では、次の３１５ページの鮫洲運動公園改修基本・実施設計について、お伺いさせてほしいと求めました。実際に今、改修工事が行われておりますけれども、進捗状況といいますか、どのような状況になっているのか、教えてほしいと求めました。","respondent":"藤田道路公園課長","answer":"具体的にどうするかという検討を進めるわけですけれども、今回、行っているものです。今週には工事を終わりまして、２０日からは使えるような形で、今、進めているところです。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"あまり見たことがなかったものですから、もしかして壊れているのかなと思いましたけれども、すみません。自転車の問題なんですけれども、一応自転車の設置場所はありますけれども、あそこの場所以外にもっと増やす予定はあるのか尋ねました。","respondent":"藤田道路公園課長","answer":"土日が、やはり少年野球の皆様方がきて、大会をやったりしておりますので、自転車が結構多くなります。現状では、あの中で、皆様でうまく使っていただければと考えております。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１点、質問させていただきたいのは、鮫洲に関してもそうですが、品川区内にある屋外スポーツ場にＡＥＤは設置されているのかどうか、教えていただけますか尋ねました。","respondent":"藤田道路公園課長","answer":"管理をしている皆様には講習を受けてもらい、何かあれば対応するようにしています。私どもも、何とかいい形にならないかということで検討はしておりますが、設置には至っていないです。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"いろいろ大変かと思います。そういうものを活用して、できれば設置してほしいと求めましたので、どうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"高橋委員","kind":"質問","question":"あれはちょっと大きいんですが、バンプというのでしょうか、それを裏道の交差点等に設置することはお願いできないでしょうか。あるいは、旧東海道周辺の公園等のガードレールに、木製ガードレールを採用できないか尋ねました。","respondent":"諸石交通安全担当課長、梶都市計画課長、松代管理工事課長","answer":"原則としては、この道路上の違法看板、あるいは自転車の撤去については東京都第二建設事務所のほうで対応していただくのが原則と考えております。… 昨年７月の段階に、安心に通行できるよう、早期に混雑緩和対策を検討されるよう要望しています。私どものほうとしては… 現地をもう一度検証しまして、そういった交通安全対策としてどういった対応ができるのか、検討してみたいと考えています。","id":"exchange-037"},{"speaker":"高橋委員","kind":"質問・要望","question":"地域の人たちの増設してほしいという声があって、増設等、詳細をお願いいたします。この公園の方向性、地域の人たちの声をどう聞いていくかとか、その辺の協働の仕組みを生かしながら利用できる公園づくりの方向性をお尋ねします。","respondent":"諸石交通安全担当課長、藤田道路公園課長、松代管理工事課長","answer":"増設枠が２０４台、既存のものとあわせますと、トータルで２９５台収容できる駐輪場になる予定です。なぜ… どういうアプローチをすればいいのか、その辺については検討しておりますので、その中で十分にまた検討していきたいと考えています。… それからまた周辺の方々に、ある意味では、その公園づくりを十分に議論しながらつくっていただくといった意味での協働があろうかと考えています。","id":"exchange-038"},{"speaker":"高橋委員","kind":"質問・要望","question":"大森駅水神口の駐輪場のほうは、バイクの置き場が、今回は計画されていないので、今後、増設を検討してほしいと求めました。ぜひ、地域の方々をワークショップ等、その後の管理などにも参加できるような形で進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"私からは、３２１ページの住宅・建築物耐震化支援事業について、幾つか伺いたいと思います。区内の木造住宅の全戸訪問調査をしたと伺っていますけれども、そこから読み取れる９割目標に向けた課題をどう分析しているのか、そこのお考えも。","respondent":"片田建築課長","answer":"促進計画の中でも、おおむね１,１００棟の耐震化木造住宅を年ごとに進めなければいけないという課題があるということを認識したところです。１月から３月までに８町丁ほど行い、それを分析しまして、議会のほうにもご報告をしていきたいと考えています。","id":"exchange-040"},{"speaker":"中塚委員","kind":"提案","question":"幾つかに絞って具体的に提案したいんですけれども、入り口を広げるといいますか、こうした改善が必要かなと思っています。ハードルを下げることで、住宅耐震化につながっていくのではないかと思うんですけれども、そこはいかがか尋ねました。","respondent":"片田建築課長","answer":"共助ということで考えてありますけれども、一般診断についても１２万円ということで行ってありますので、そういうお話をしながら行ってきています。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"地元で顔も知っていて、相談もしやすいし、仕事の確保にもつながっていくといった話も伺います。この点については、どんなふうにお考えなのか、地元の仕事確保の点については、どうお考えなのか教えてほしいと求めました。","respondent":"片田建築課長","answer":"具体的には、そういう地域の中に直接出て行って説明するとか、そういうことを含めてＰＲしていきたいと考えています。そういう意味で、今後、それを拡大していきたいと考えております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"例えばそれだけではなくて、いわゆる筋交いの簡易補強とか、こういう簡易な方法の支援も別途考えていく必要があるのではないかと思っています。いろいろ工夫をすれば、地元の大工でもできるような技術も考えられるのではないかなと思うんですけれども、その点はいかがか尋ねました。","respondent":"片田建築課長","answer":"１８社ほどの企業が、防災センターの３階にいろいろな工法を展示していただいたという中で、区民のお一方が利用していただいたケースもあります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"水周りのこと、バリアフリーのこと、この際いろいろ家主との相談につなげていきたいというお話も伺っているんです。防災に強いまちづくりと、いわゆる地元の仕事づくりと上手につなげることは可能ではないのかなと思うんですけれども、いかがか尋ねました。","respondent":"片田建築課長","answer":"昨年、個別訪問を行う際には、私ども、耐震化の支援メニューだけではなくて、転倒防止のチラシも含めて地域を回ったという経過があります。別な事業課のほうが進めているところですけれども、連携して、ＰＲを含めた対応を行っていきたいと考えております。","id":"exchange-044"},{"speaker":"山内委員","kind":"質問・要望","question":"３１７ページ、３１５ページの子ども達による基本構想策定記念公園づくりについて、お伺いいたします。ちょっと教えていただきたいんですけれども、国、東京都の按分率をまず説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"用地取得費の国と東京都の補助率ですけれども、密集住宅市街地整備促進事業のほうが、国が２分の１、東京都が４分の１です。防災生活圏促進事業の補助率ですけれども、国が３分の１、東京都が同じく３分の１です。","id":"exchange-045"},{"speaker":"山内委員","kind":"質問・要望","question":"いろいろお伺いをさせていただきましたが、どうしてもやはり広場用地を取得していかなくてはならないというか、話をいただいております。例えば荏原北地区は平成２１年度に終了するといった中で、広場が欲しいといった要望に対して、品川区の考え。","respondent":"松代管理工事課長","answer":"そういったものは常に検討しておりますし、今後も検討してまいりたいと思いますが、我々としては一番大きな問題だと考えています。道路等々、取得に向けて検討したいというのが、我々の基本的な考えです。","id":"exchange-046"},{"speaker":"山内委員","kind":"質問","question":"それが区民サービスの一つではないかなと考えるんです。いかがなものかなと思うんですけれども、その辺の考え方を、もう一度説明を求めました。","respondent":"松代管理工事課長","answer":"１点目、我々区レベルの２,５００m2ぐらいまで何とかおとしてほしいということを、また国のほうに要望しております。十分にその辺のところも含めて、引き続き検討しながら、用地確保の是非を検討していきたいと思っているところです。","id":"exchange-047"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、子ども達による基本構想策定記念公園づくりについて、ちょっとお伺いさせていただきたいんです。この公園づくりのねらいと、それからこの公園は、一体どこにできるんか尋ねました。","respondent":"松代管理工事課長","answer":"基本的には、新設の公園として設置をしたいという思いで、今いろいろと検討しています。平成２１年度中に、おおむね実施設計等を進めたいと考えていますので、二面で検討しながら設置したいと考えているところです。","id":"exchange-048"},{"speaker":"山内委員","kind":"質問","question":"一番最後に、今、課長から話がありましたけれども、平成２１年度に設計作業に入る予定ですと、もう既に平成２１年度は近いわけですよね。それで、公園を設計するのに場所が決まっていなくて、設計はできるものなんか尋ねました。","respondent":"松代管理工事課長","answer":"その中につくるということでの実施設計ですので、当然、場所を選定した上でその中に図面を書いていくということになります。平成２１年度まで、その中で鋭意、新設できるような場所を検討したいと考えているところです。","id":"exchange-049"},{"speaker":"山内委員","kind":"質問・要望","question":"あべこべ家族というんですか、大人が子どもになり、子どもが大人になって、そこからいろいろな公園のアイデアを引き出す。コンサルタントみたいな方がいて、そういう人からのアイデアによってこういうものを区でも取り入れようというお考えでやられたのか尋ねました。","respondent":"松代管理工事課長","answer":"５社ほど、いろいろと提案をしていただいた中に、このあべこべ家族という提案があったものです。そういった意味での、いい形の提案をしていただいたということで、成果に結びついたと考えています。","id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"ワークショップに参加した三木小学校５年生の男子は、日野学園３年生男子は、夢が膨らみました」と書いてあります。その辺の後のフォローとか、そういうことは考えているんですか、ちょっと説明を求めました。","respondent":"松代管理工事課長","answer":"４回ほど、朝９時半ぐらいから４時ぐらいまで集中して会議をしましたけれども、ほんとうに大きな課題だと考えています。ただ、そうはいっても、まだまだ夢のような話ですので、これをなるべく実現したいというところです。","id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"どこにできるのか、まだ教えていただけませんけれども、早く説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問","question":"大森駅水神口ということで伺いまして、戸越公園と下神明については１階建てなんでしょうか、上を考えているのかどうかということ。一つ列を増やして、横の幅は変わらないということでいいんでしょうか、説明を求めました。","respondent":"諸石交通安全担当課長","answer":"戸越公園、それから下神明駅の駐輪場ですけれども、これは平置きと申しますか、２層、３層の部分は考えておりません。それから、大森駅水神口ですが、横に広げるのではなく、今、委員がおっしゃったように、１台分、公園側のほうへ出すような形で増設をするものです。","id":"exchange-053"},{"speaker":"武内委員","kind":"質問・要望","question":"混乱がないように、なるべく早い段階で周知をしていただきたいということで、その考え方。近隣の方の要望を聞くと、そういうことは検討されたかどうか、説明を求めました。","respondent":"諸石交通安全担当課長","answer":"これは９月１日供用開始の予定にしておりますので、それまでには、さまざまな方法で区民の皆様にお知らせをしていきたいと考えております。公園用地に駐輪場を設置をしている関係で、３層という形での駐輪場は、今回のような形で増設をするということになっております。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問・要望","question":"いずれにしても、大森駅水神口も含めて変わってきますので、混乱のないように、事前に周知をしっかりお願いしたいと、これは要望します。何で平成２１年度は出てこないのか、やらないのかどうか、この辺の説明を求めました。","respondent":"片田建築課長","answer":"昨年からこのような支援メニューを考えて、個別訪問も含めて、周知を進めてきたところです。地域の中に、区が進めている事業について、詳しく丁寧に説明していきたいと考えております。","id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"どういう形かわかりませんけれども、引き続きやっていただきたいということを、これは要望します。何回か要望させていただいて、残念ながら、今のところ実績は１件ということで伺っております。","respondent":"片田建築課長","answer":"８割から９割ぐらいの助成になるわけですけれども、地元業界とも連携をしまして、いろいろ提案していきたいと考えております。そういう中で、地域に根ざした地元工務店を含めた連携の中で広げていきたいという中で、ほかの例とは違うかなと考えています。","id":"exchange-056"},{"speaker":"武内委員","kind":"提案","question":"これまで簡易改修ということで何回かご提案させていただいたんですが、平成１８年度は１５件改修があって、そのうち６件が簡易改修。平成２０年度は２１件中１８件が簡易改修ということで、評点１.０にいく場合だけ、感想をお聞きしたいと思いますとの意見を述べました。","respondent":"片田建築課長","answer":"評点が０.７という１を下回る数字であったとしても、これを評価していこうといったような考え方できていると、私ども認識しています。","id":"exchange-057"},{"speaker":"武内委員","kind":"質問・要望","question":"こうした簡易改修なんかも、区のほうでこれから積極的に検討していく時期にきているのかなと思いますので、これは要望させてほしいと求めました。これについて、簡単で結構なので、説明を求めました。","respondent":"齋藤住宅課長","answer":"その資金を利用して、要介護度の高い方が有料老人ホームに入れるという例が、品川区で５例ぐらいあります。こうした例をもっと広げられないかということを検討してまいります。","id":"exchange-058"},{"speaker":"武内委員","kind":"質問","question":"時間がないのであれですけれども、そうすると、家主に買ってもらうということなんですけれども、かなりお金がかかるわけですよね。これについて、何か助成を考えているということなんか尋ねました。","respondent":"齋藤住宅課長","answer":"今後、検討してまいります。","id":"exchange-059"},{"speaker":"本間委員","kind":"質問","question":"３１０ページ、そして３１３ページ、公園整備事業費の中から幾つか質問したいと思います。この件について、どのような目的で、どのようなことをされるのか、そのねらいとするものについて、簡単で結構ですから、説明を求めました。","respondent":"諸石交通安全担当課長","answer":"自転車が車道上を走れば、逆に今度は自転車が車道上を走ると、他の車両との接触事故が増えるのではないかというところが危惧されたところです。自転車以外の車両が走る場所、それから自転車が走る場所を明確に道路上に示したいというのが目的の整備です。","id":"exchange-060"},{"speaker":"本間委員","kind":"質問","question":"かなりすっきりとした両者にとって便利になった部分を覚えておりますので、そんなことかなと思ったものですから、承知いたしました。公共施設３カ所とありますが、この公共施設３カ所の部分はどのようなところなのか、説明を求めました。","respondent":"家壽田下水道河川課長","answer":"今現在、新年度の予定というものは決まっておりません。規模については、その場所に応じて、屋根が違うと雨水量が変わってきますので、それで若干変わってくるです。","id":"exchange-061"},{"speaker":"本間委員","kind":"質問","question":"あの場面では、夏場の暑い時期に打ち水等々に使うようにしておりましたが、そのようなことなのか。それとも、もっとほかに考えるところがあるのかどうか、説明を求めました。","respondent":"家壽田下水道河川課長","answer":"エコにもなりますし、ヒートアイランド対策になるというということで、大変効果のある事業だと考えています。そういった多面の意味がある、意図のある事業として、区民の皆様にどんどん設置していただきたいと考えております。","id":"exchange-062"},{"speaker":"本間委員","kind":"意見","question":"しながわ区民公園北側ゾーン改修基本設計に約１,５００万円ついておりますけれども、どういうふうな形で改修するようになったのか。そのねらいとするものについて、簡単に説明を求めました。","respondent":"松代管理工事課長","answer":"冒頭言いましたように、１２haありますので、一応これを三つのゾーンに分けたいと考えています。は、ほんとうにそのまま続けていくのかという転換等の検討といったものも入れながら、多目的に広く使えるような工夫を検討したいと考えています。","id":"exchange-063"},{"speaker":"本間委員","kind":"質問","question":"１２haに及ぶすべてに目配りをしながら、平日の昼間の利用状況はどのようになっているのか、大変関心を持っています。その件について、わかる範囲で説明を求めました。","respondent":"松代管理工事課長","answer":"多いときで６割ぐらい、低いときで３割ぐらいにとどまっております。今、全体的に進めています人工芝等を配置しまして、利用枠の拡大といった検討も進めていきたいと考えています。","id":"exchange-064"},{"speaker":"本間委員","kind":"質問・要望","question":"多目的な部分とか、そういう形で工夫されて、利用状況を高めるようにしてほしいと求めました。ご参考に、新たな試みを進めてほしいと求めましたが、いかがしょうか。","respondent":"藤田道路公園課長","answer":"これもアラザシ館をアラザシに固定した考えではなく、さまざまな面で、私どもも、水族館ともども工夫しながら、今、やっております。今後とも、水族館、いい展開ができるように頑張っていきたいと考えています。","id":"exchange-065"},{"speaker":"本間委員","kind":"意見","question":"建物のことがありましたけれども、やはり市民を巻き込む部分で、もうちょっと館の外に目をつけていただいてもよろしいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"藤原委員","kind":"質問","question":"３２３ページの借上型区民住宅管理費について、お伺いしますが、まず借上型区民住宅の入居率と、空き室の数と、特に空き室が多かった住宅の、それぞれの３年ぐらいの空き室数と、区の負担について、まず説明を求めました。","respondent":"齋藤住宅課長","answer":"最後にブラウネスハイム倉田は１１戸の住宅ですが、空き室が、平成１８年度は４室、平成１９年度４室、平成２０年度が５室。空き家補償の金額が、平成１８年度から８９３万円、平成１９年度も８９３万円、平成２０年度は１,０５０万円ぐらいになります。","id":"exchange-067"},{"speaker":"藤原委員","kind":"質問","question":"今年度で６,０００万円近く、質問していくに当たって、しようがないのか。それとも、区として努力して、少しでも空き室を減らしていくのか、二つに分かれると思うんですけれども、どっちをとっていくのか、説明を求めました。","respondent":"齋藤住宅課長","answer":"８億５,０００万円から９億円、これは減価償却ということを考えておりませんので、これぐらいの利益があります。イニシャルコストまで賄えるところは、品川区と中央区ぐらいしかございませんので、この健全財政を守っていくということが大事だと理解しております。","id":"exchange-068"},{"speaker":"藤原委員","kind":"質問","question":"それとも健全に努力しているのか、していくのかということについて、教えていただけますか。","respondent":"齋藤住宅課長","answer":"るる説明したという部分もあるかもしれませんけれども、やはり制度があったとしても、空き室を埋めるための努力はしなければいけない。５％傾斜型で上がっていくものを、３％に下げるとか、引き続き埋めるための最大限の努力をしてまいります。","id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"この三つに対しても、オーナーといろいろお話をしていると思うんですけれども、現時点で、空き室の数は減っていないではないですか。もしわかればというか、交渉しているのであれば、その三つのオーナーの、現時点でのお考えを教えていただけますか。","respondent":"齋藤住宅課長","answer":"この３年間間断なく引き下げ交渉をしてまいりました。区の負担で行うべきだというお考えでありまして、オーナーの事情もあるということを、ぜひご理解お願いしたいと思います。","id":"exchange-070"},{"speaker":"藤原委員","kind":"質問・要望","question":"うちの区だけではないと思うので、２３区の中でも、やっぱりどうしたらいいかというお考えがあると思うんです。２３区の中で連携をして、国とかに何か要望、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"空いている部屋だけ下げてはいけないとか、事業認可の変更手続についてはいろいろ言われまして、なかなかうまくいかない。区のファミーユ西品川という住宅が平成５年なので、今度１５年経ちまして、検討しています。","id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で、正確な情報を求める方もいらっしゃいますし、もちろん、私ども議会の立場でも提供していかなければならないという点から伺います。同時に、周辺電線類地中化の調査をしていくということで、対象はどれぐらいなのか、その辺の基本のところを尋ねました。","respondent":"松代管理工事課長","answer":"平成２１年度は、まずは基本計画、平成２２年度が実施設計という形で段階的に進めていければと考えています。補助２６号線から、国文学研究資料館跡地の周辺４道路の計画を先に進めたいということで、検討していくものです。","id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"これからする整備のルール、経緯とか方向性、この辺は十分に周知すべきと思います。方向性だけは出されたほうがいいのかなと思って、この２点、尋ねました。","respondent":"松代管理工事課長","answer":"広く、区民の皆様にきちんとお知らせをして、そういう中での今後の公園のあり方というものを発信していきたいと考えています。５月１６日、１７日の「ＥＢＡＲＡ夢フェスタ２００９」、少し皆様にわかりやすいような表現等をやっていきたいと考えています。","id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問","question":"用地管理費のところで、用地管理という中身のところで、簡単に、いろいろ管理されている土地が無数にあるかと思います。まず数で伺いたいのと、二つありましたら、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"こちらは売却予定ということで、こちらにつきましては、用途は決まっていないです。いろいろと跡地活用等を検討しておりますけれども、用途は定めて、現在でも有効に使わせていただいているといったところです。","id":"exchange-074"},{"speaker":"渡辺委員","kind":"質問","question":"基本的なところを伺いたかったので。あるいは、借りたりするといった交渉事等はどのような形であるのか、説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"密集事業を開始するときに当たりまして、まちづくりニュースという形で、地域の皆さんに発行しております。そういったさまざまな形で用地取得に取り組んでいるところです。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問・要望","question":"いろいろな働きかけをしていただけたらありがたいなと思いますので、これは質問ではなく、要望にします。その際の道路幅や、何か規定のような目安を伺えればと思います。","respondent":"諸石交通安全担当課長、松代管理工事課長","answer":"自転車利用者が我が物顔に走っている、マナーが悪い、そうしたものに対する認識、それから対策についてです。相当に悪質なものについてはこういう対応をしますけれども、そうでないものについては… ３ｍが標準ですけれども、なかなかそうはいかない場合は２.５ｍ、合計４.５ｍの幅員が必要とされています。","id":"exchange-076"},{"speaker":"菊地委員","kind":"意見","question":"私のほうからは、３２０ページの中高層建築物の開発指導、この辺についてお尋ねをしてまいりたいと思います。事業者に対する指導というのは、どういうふうにされているのか、この辺をまず具体的にちょっと説明を求めました。","respondent":"齋藤住宅課長","answer":"第一原則として、１００ｍを超えて総合設計をするようなものは、風洞実験を必ずして、１年間定期報告をする。したがいまして、区として、風環境について何か求めるものがあるかというと、ないです。","id":"exchange-077"},{"speaker":"菊地委員","kind":"意見","question":"その地域に４０年、５０年とお住まいになっている皆さんは、生涯のうちでも経験したことのないような風が吹いているという感想を持たれるわけです。シミュレーションが正しいのか、それとも、住民の実感が正しいのか、この辺の分析も、ちょっとお聞かせ願えればと思いますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"具体的な例がございませんので、一般論でご説明いたしますけれども、建物は３階もあれば、高さ９０ｍのものもあって、多様です。説明を求めましたところ、風環境はよかったと、風害と言われるようなものはなかったという判定結果もありました。","id":"exchange-078"},{"speaker":"菊地委員","kind":"質問","question":"お聞きしますと、１５軒ぐらいのお宅で、そういう何らかの被害を受けているということなんです。もう１点ですけれども、その整備コストを補って、こういう解釈の仕方でよろしいのか尋ねました。","respondent":"齋藤住宅課長","answer":"開発指導、建築紛争についても、東京都が対応する、これが原則です。ただ、解決に向けた支援としてお話し合いの場は提供しますし、十分に納得されるように説明しなさいということは申し上げることまではできます。","id":"exchange-079"},{"speaker":"菊地委員","kind":"質問・要望","question":"どうかという判断そのものを、やっぱり区内に建設をさせるわけですから、品川区自身がきちんととらえるべきではないかと思います。その辺、もうちょっと説明を求めました。","respondent":"片田建築課長","answer":"逆に、空地を評価して、それを建物として容積を評価していくといったような考え方なんです。そういう専門機関と建築審査会の同意を得て許可していきますので、そのような形での東京都への意見は、きちっと区としても伝えているような状況です。","id":"exchange-080"},{"speaker":"菊地委員","kind":"質問","question":"ですからやっぱり、住民の声を聞いていくというのであれば、そうしたことを進めるべきだと思います。その辺も、ちょっとお願いします。","respondent":"齋藤住宅課長","answer":"築４０年で、建築確認がなかった物件について、それを損害と言えるかどうかというのもまた改めて、ご自分で考えて、検証すべきだと思います。それは、区としてもなかなか難しい、言い難いです。","id":"exchange-081"},{"speaker":"菊地委員","kind":"質問","question":"最後にちょっと、課長の答弁も、昨年の段階で、きっちり指導していくんだと言っているわけですから…。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"若林委員","kind":"質問・要望","question":"これについては、まずこの予算書のどこに入ってくるのかということを確認すること。数は聞きませんので、割合を、ざっくりと教えてほしいと求めました。","respondent":"諸石交通安全担当課長、松代管理工事課長","answer":"ただ、まだこれは未確認情報で、私の耳にちょっと入ってきただけの話なんですが、今後、自治体のほうで設置することも可能になるかもしれません。その際に… そういった中で、例えば土木を除く造園関係の業者という形でいきますと、２０社ぐらいあろうと思います。設計本体の専門業者は少なくて、測量会社が… ただ、あそこは、施工前と施工後の騒音の調査をしていただきました。","id":"exchange-083"},{"speaker":"若林委員","kind":"質問・要望","question":"では、エスコートゾーンのほう、これから自治体で可能かどうか、確認をしていただいた上で、また適切な拡大を図ってほしいと求めました。確認したいのと、どういう公園をつくろうとされているのか、考え方をお聞きしたいと思います。","respondent":"松代管理工事課長、阿部経理課長","answer":"幼児を対象とした児童公園なのか、防災広場的なものなのか、そういったもので内容が変わってまいります。それは、公園をつくる目的、種別、そういったものによって内容が違ってまいります。 管理工事課長が答えましたように、区内ということで、そんな大きなものではないものについては区内業者が設計をしていると認識しております。","id":"exchange-084"},{"speaker":"若林委員","kind":"質問・要望","question":"私が当選した直後の一般質問か何かで、自分が書いた原稿ですから、いまだに覚えております。まだまだたくさんありそうですので、今後の公園設計に取り組んでいただきたいと考えておりますけれども、ご答弁をお願いいたします。","respondent":"松代管理工事課長","answer":"委員おっしゃるように、公園をつくる際に、ある程度まとまった規模のときには、コンセプトとデザイン性が求められます。もちろん機能があってのデザイン性ですけれども、そういったものには、これからも十分に意を尽くして進めていきたいと考えております。","id":"exchange-085"},{"speaker":"井上委員","kind":"提案","question":"３０８ページ、３１０ページの都市計画費総務費の景観まちづくり推進事業と、やさしいまちづくり推進費について伺います。そして、事業年度が複数年度にまたがっていると思いますけれども、総額で、最終的に委託の費用は幾らと見積もっているのか、まず、お伺いいたしますとの意見を述べました。","respondent":"梶都市計画課長","answer":"当初、旧東海道のほうを中心といたしまして、実施をしていったものです。品川区景観計画を立てていくためには継続性、継続して、この業者で行っているです。","id":"exchange-086"},{"speaker":"井上委員","kind":"提案","question":"プロポーザルの選考の項目の中に、住民参加による街並み整備に関する多くの実績がある、品川区の重点地域の特性を十分に把握した提案になっている。どういう点で高かったのか、お伺いいたしますとの意見を述べました。","respondent":"梶都市計画課長","answer":"蔵の町ですとか、そういった歴史的景観にある取り組みをやっているんですが、そちらのほうで継続してずっと実施していたというところがあります。総合的に判断したものですので、どこがということではないんですけれども、全体でここに決まったという形で考えております。","id":"exchange-087"},{"speaker":"井上委員","kind":"質問","question":"今、伺った中で、天王洲とか、東品川とか、その辺は、ちょっと再開発という部分で、ここのところでどうなのかと、私は疑問があるんです。もう今までに周知をされていることで、承知をしておりますので、それ以外のことについてお伺いいたします。","respondent":"梶都市計画課長","answer":"そういった方々のご意見も聞きながら、昨年の夏には、説明会なりを開いているところです。説明会とか、説明会のお知らせ、把握していきたいと考えておるところです。","id":"exchange-088"},{"speaker":"井上委員","kind":"提案","question":"いろいろな方の声を聞いてという、ほかの部分でも提案がありましたので、そういったところを広く進めていただきたいと思っています。放置自転車対策だけではなくて、自転車利用を前提とした安全対策と、放置自転車対策に転換をしてほしいということはずっと提案してまいりましたとの意見を述べました。","respondent":"諸石交通安全担当課長、松代管理工事課長、日下部企画財政課長","answer":"私からは、放置自転車の予算について、ご説明を申し上げます。８,５１８万６,０００円ということになっておりますが、雇用対策ということで… それも、幅がせいぜい１ｍちょっとぐらいしかできない。検証する中で、今後の展開等も、当然それにあわせて考えていくという状況です。 自転車走行レーンですが、今のところ、補助制度はございません。ですから、基本的には一般財源で整備をするという形です。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"伺いますが、区が自転車安全利用講習会というものを、ぜひ積極的に行ってほしいと求めました。ぜひ方向転換をしてほしいと求めましたけれども、見解があれば、お願いいたします。","respondent":"諸石交通安全担当課長、松代管理工事課長","answer":"そこを何とかやろうということで、今、一生懸命検討している最中です。そういう区内の状況ですので、今、この現状で自転車の利用促進という方向へは、転換できないかなと考えているところです。 先ほど、質問がありました、自転車走行環境整備工事費の金額です。一応、２,８００万円余を計画しています。","id":"exchange-090"},{"speaker":"井上委員","kind":"質問・要望","question":"東京都第二建設事務所に確認をしましたら、自転車安全利用推進の方に、ぜひ行っていただきたいと思っています。質問を少しカットして伺いますけれども、昨年の決算特別委員会で、雨水浸透ますの助成の状況なんかを伺っておりまして。","respondent":"家壽田下水道河川課長","answer":"今いろいろなことをやっておりますので、引き続き、やってまいりたいと思います。今回の９００万円余りの予算の中でしっかり検討し、いろいろ総合的に、これからしっかり検討してまいりたいと思います。","id":"exchange-091"},{"speaker":"石田（慎）委員","kind":"質問","question":"３１１ページ、３１７ページ、お伺いします。例えば改修等に当たる際は、もちろん年数とかも基準になるのかと思うんですが、簡単でいいので、改修に対する基準があったら、説明を求めました。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"平成２０年度、区内にあります７０橋、これは歩道橋も含む橋すべてですが、これの点検等を実施いたしました。さらに７０年、１００年と延ばしていくような方策を… 今、私ども年に１回、専門家による点検を行ってあります。部分的なものについては、その部分だけ、ちょっと一部分だけ塗装をするといったような形で行っているものです。","id":"exchange-092"},{"speaker":"石田（慎）委員","kind":"質問","question":"以前、お伺いしたときには、その考えはないというようなご答弁だったんですが、もし変わっていましたら、区のお考えをお聞かせください。それから、期間であったり、委託先等の概要をまずお伺いしたい。","respondent":"松代管理工事課長、青木都市開発課長","answer":"歩道橋の今後の対応の考え方です。こういったものについては、今後、きちんと対応していきたいと考えているところです。大井町駅周辺のまちづくり構想および五反田にぎわいゾーンの整備方針策定というものは、平成２０年度と、平成２１年度で検討してまいるものです。","id":"exchange-093"},{"speaker":"石田（慎）委員","kind":"質問","question":"例えば、この３カ所の駅は、品川区内でも大きい駅周辺のまちづくりだと思うんです。地元の駅の部分だったり、地域にある会社、事業所の人たちを巻き込んでになるのか、そこだけ１点、お伺いします。","respondent":"青木都市開発課長","answer":"大学が多うありますから、あるいはアンケートになるのかわかりませんけれども、そういった方法論を考えていきたいと考えております。ただ１点、そういった点に気をつけつつ、真の声を受けとめるようなやり方を考えていきたいと思っているところです。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"最初に確認をさせていただきたいんですけれども、当初つくるときは少年野球を、ということでお話を伺いました。そこのところを、確認させてほしいと求めました。","respondent":"松代管理工事課長","answer":"少年野球場は２面ですけれども、いろいろな多目的に使えるようなものができないか、ということを考えようと考えています。そういった意味では、まずは年間を通して、つくり方というのが前提なのかなと思っているところです。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問","question":"最初の少年野球等という言葉にも、課長のいろいろなお考えがあらわれていて、「等」ということで、そうなると、野球が今まで２面できていたのが、やはり多目的化することによって１面になってしまう可能性もあるということか尋ねました。","respondent":"松代管理工事課長","answer":"大人が使うときには１面にして使っております。少年野球そのものは２面残しながら、かつ多機能に使えるものがないかということを、平成２１年度中に検討していきたいと考えているところです。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問・要望","question":"区民の共有の広場ですから、視野に入れながらつくっていただきたい、改修を進めてほしいと求めました。仮にされているのであれば、どのような情報の収集をされているのか、お聞かせほしいと求めました。","respondent":"梶都市計画課長","answer":"ただいまのところでは、まだ静観して、情報を得ているという状況です。今後、またいろいろな状況、タイミングをとらえまして、情報を把握しながら、皆様方にお話をしていきたいと考えているところです。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問・要望","question":"それから、鉄道におきましても、よく部長、課長がおっしゃっているように、７鉄道事業者があって、ＪＲ、東急、京急などの路線で、３７駅あります。自転車を利用しないで徒歩でできるまちづくりというのは、どんな取り組みをされることをおっしゃっているのか、教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"３０分かからずに、どこへでも行けるのが品川区です。これは区も汗をかいて用意しますと、利用者もご協力をお願いしますというのが、従来の区の考え方です。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"利用者の視点に立ったというところで、今、健康、歩くことが大事だとおっしゃっておられました。そこのところは、どういうふうにお考えになりますか、教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"こういう形で進んでまいりますので、乗り継ぎが非常に円滑にできるような方法が、一方で進んできている。区も鉄道事業者と協力して、今、進めているところです。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問","question":"１０件で３００万円ということですけれども、事業規模が小さくないでしょうか。それについては、どういうふうに思われますか。","respondent":"齋藤住宅課長","answer":"環境共生住宅については、太陽光パネルの設置工事ですとか、シックハウス対策の工事について助成を行います。２３区のうち７区で助成をしていますが、件数的には１番か２番目で、かなり効果はあると考えています。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問","question":"１０件で効果があるということなので、私は理解します。それに対して、本区の現状と、何か講じている対策があれば、お伺いしたいと思います。","respondent":"齋藤住宅課長","answer":"ただ、実績がなかなか上がらず、３件ぐらいしかお呼びがかかっておりません。そもそも集まって、話をして、議論をするということ自体がなかなかうまくいかないようですので、いろいろ働きかけをしてまいりたいと考えています。","id":"exchange-101"},{"speaker":"大沢委員","kind":"意見","question":"高齢化して、管理組合が機能しなくなると、まさに一つの最小単位のコミュニティの集合の意思がつながらなくなろうかと思うんです。ないし指導をしていただきながら、マンション管理組合の高齢化に対して、十分なご配慮をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"３１９ページの避難道路機能強化事業に入るんでしょうか、３０９ページの治水対策になるのか、関連して質問いたします。それがどういう形になっているのか、これは区内一律という形の基準になっているのか、お聞きしたいと思います。","respondent":"松代管理工事課長、吉川住環境整備担当課長、家壽田下水道河川課長","answer":"これまで、区では、公園設置の際には樹名板をつけてまいりました。２３０カ所ほどの公園ですので、そういった工夫を… 平成１９年度から地域の方で説明会等を実施してまいりまして、地区計画を定める都市計画法の手続きをとっているところです。… 大量排水については基準がございまして、これは、主に受け入れます下水道側の能力によって決まってまいります。","id":"exchange-103"},{"speaker":"西本委員","kind":"提案","question":"いろいろまちづくりについて提案をしつつ、進めていただきたいと考えていますので、それについてのお考えをお聞きしたいと思います。そういう地盤の形によって変わってくるということがありますので、もう少し細かい設定基準にできないのかと思いますが、考え方をお聞きしますとの意見を述べました。","respondent":"吉川住環境整備担当課長、家壽田下水道河川課長","answer":"滝王子通りの商店街の件ですが、既に、私ども、商店街の方たちともお話しておりまして、委員ご指摘のようなご心配の声というのは上がっております。これにつきましては、所管の産業振興課ともいろいろ相談しながら、今後… 下水道の排水の能力を超える、１時間に５０mmを超えるような雨で、低地部の本管が負けてしまったときに逆流して起こったということが考えられます。","id":"exchange-104"},{"speaker":"山路委員","kind":"質問","question":"３１１ページ、４点目は３２３ページ、お伺いいたします。今回の改善基本計画作成については、どのような計画を予定されているのか、お伺いいたします。","respondent":"松代管理工事課長","answer":"開発の動きへの対応、まず平成２０年度は、平成２１年度の具体的な検討に向けての素材として整理をしてきたものです。いろいろな課題を個別に解決に向けて方針等を定めて、平成２２年度以降順次、できるところから整備等にかかっていきたいと考えているところです。","id":"exchange-105"},{"speaker":"山路委員","kind":"質問・要望","question":"ハナミズキを植えてほしいという要望が強い地域、陥没と言ったら大きいですけれども、道路が多少でこぼこになっているんです。今まで、どのような認識を持っていらっしゃったか、お伺いいたします。","respondent":"松代管理工事課長","answer":"ほかへの移転等を、今働きかけて、向こうも真剣に考えていただいているという状況にあります。今後とも、移転等につきまして、協議を進めていきたいと考えているところです。","id":"exchange-106"},{"speaker":"山路委員","kind":"質問・要望","question":"我が党の山元委員のほうからの質問に対しても、青物横丁の改札口を入ったところにエレベーターが設置されるという答弁をお伺いいたしまして、また。まちづくりということから取り組んで国に働きかけて、京浜急行に働きかけてほしいと求めましたが、どのようにお考えか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"国道側の地上階からエレベーターを、コンコースを通しまして、そこのところまで上げるという計画もあります。これは車いす対応にしていくという中身ですが、先ほど、朝方には申し上げなかったです。","id":"exchange-107"},{"speaker":"山路委員","kind":"質問・要望","question":"もう１点ですけれども、歩道には人が信号を待っていたりして、全く自転車が立ちどまっているという状況があるわけです。この辺に、ポールか何かで自転車の方向を示すような検討もしてほしいと求めましたが、どのようにお考えか尋ねました。","respondent":"松代管理工事課長","answer":"今のお話で、大体状況はわかりましたけれども、現地をさらに検証しまして、そういった通行される方の安全対策、どういったものができるのか、検討したいと思います。","id":"exchange-108"},{"speaker":"山路委員","kind":"質問","question":"時間がなくなりましたので、住情報センターの件につきましては、また改めてお伺いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"安藤委員","kind":"質問","question":"増設で対応すべきだと思うんですけれども、いかがでしょうかということが１点。区内にかなりの数で、こうした住宅が増えるのではないかと思いますが、そこら辺のお考えを伺います。","respondent":"松代管理工事課長、阿部経理課長、齋藤住宅課長","answer":"平米あたり７０万円とすれば、７０億円という莫大な金がかかってまいります。１週間を通してフルに使えるといったものを、今、検討しているものです。その前、平成１７年度につきましては１５件、この中で５,０００m2以上を超えるものにつきましてはございません。… 建替えに合わせて太陽光パネルを設置される方は、既設の住宅、既存の住宅にも太陽光パネルが設置できるように進めていきたいと思います。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、基本的に意気込みを伺いたいと思って、３点挙げます。３１３ページ、３２１ページ、品川版も含めてお伺いしたいと思います。","respondent":"松代管理工事課長、藤田道路公園課長、片田建築課長","answer":"４８橋のうち、ほかはすべて、今は耐震等の対応をしているんですが、この１橋だけが課題として残っております。案件によっては… 効率的な維持管理に努めるということと、区も一緒になって魅力ある水族館の運営をどうやっていくべきかを考えていかなければいけないと考えています。… 私のほうから、シェルターの考え方について、ご説明します。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"補助１６２号線の話なんですが、水とみどりのみち整備事業となっているわけでありまして、ぜひ、水の部分も考えていただきたい。最後にそっちだけ説明するよう求めました。","respondent":"松代管理工事課長","answer":"持てるかどうかは、これからの問題ですけれども、そういった中で、周辺のまちづくりも含めてやるようなことを考えたい。景観にも非常に力を入れていますので、そういう視点からの取り組みといったところも入れながら、今後の計画等が出されればと思っているところです。","id":"exchange-112"},{"speaker":"阿部委員","kind":"質問・要望","question":"３１７ページ、そして同じ３１７ページの百反歩道橋について、お伺いしたいと思います。どういう理由があっても、ぜひ、今からでも書き足してほしいと思うんですけれども、説明を求めました。","respondent":"諸石交通安全担当課長、梶都市計画課長、青木都市開発課長","answer":"今年度中には、区内のすべてのスクールゾーンの規制が、７時半から８時半に変更になります。厳密にいつからここの工事ができますというところまで計画がで… それで、平成１９年１１月に再度要請をしたのですが、今までのところ、芳しい回答がございません。まだ私どものほうの要望にこたえられる状態にありません… 隣接しています百反隧道、トンネルの部分も含めまして、大崎駅の東西の連携を強化していこうということで検討を進めたものです。","id":"exchange-113"},{"speaker":"阿部委員","kind":"質問・要望","question":"やはりこれまで以上に、あそこを通りたいという、９時をのばしてほしいという区民の要望はさらに高まっていると感じております。特に自転車は弱いと思うんですけれども、何かお考えがあれば説明を求めました。","respondent":"梶都市計画課長、青木都市開発課長","answer":"営業の問題ですとか、乗降客が増えていないとか、そういった問題がきてあります。そういったものを含めまして、再度、強く要請していきたいと考えているところです。歩道と言ってはいけないんですけれども、歩道の空間をより確保して、自転車を引いて通っていただけるようにしたいということで検討しています。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと河川費の中で調べておいてほしいんですが、品川区内にある区道と私道上の下水道管の長さ、大まかで、もしわかれば教えてください。次々に延焼するように思うんですが、それについて、どのように考えているか説明を求めました。","respondent":"片田建築課長","answer":"基本的には５０cmという空きを設けているんですけれども、仮に５０cmに満たなくても、法的に適合性を有していると考えているものです。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"今、４５分以上の耐火が可能だということなんですが、壁の場合はいいんです、窓の場合はどうですか。もっと短時間で延焼しちゃうと思うんですが、その辺について、簡単にお願いします。","respondent":"片田建築課長","answer":"隣地から境界３ｍ、あるいは５ｍという範囲の中では、仮に熱で割れたとしても飛び散らないような構造を工夫してきていると。それから、開口部についても、外壁の考え方の中で準耐火という形であれば、そのようなことも十分に考慮されていると考えております。","id":"exchange-116"},{"speaker":"須貝委員","kind":"確認","question":"建築確認がおりれば、ここでちょっとお聞きしたいんですが、現在介入しているわけですよね。そうすると、建物というのは、公共性があると考えたほうがいいんか尋ねました。","respondent":"片田建築課長","answer":"基本的には最低限の考え方ということで、快適に暮らせるようにということで、規制してきている。全体制限をかけてきているですので、区民の財産をいかにも規制しているような考え方には、ちょっと及ばないのではないかと考えております。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、何かそういう不適格な建物等があったときには、行政も責任の一部を負うということになるんでしょうか。簡単にお願いします。","respondent":"片田建築課長","answer":"当然、不適格な建物があるとすれば、当然、法に基づいて建築主、あるいは業者を指導していくと考えております。その地域の安全上の観点とか、公益性の観点から、慎重に考えなければいけないと考えております。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"次に、品川区内の下水道についてお聞きしたいと思います。そして、企業や商店からの産業排水などが流れていくわけですが、こういう考え方でよろしいんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"今、委員おっしゃったとおり、下水道というのは公共用水域の水質保全ということで、汚水、雑排水を集めて処理するということと、雨から土地を守るという、まさにご指摘のとおりです。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、今現在、品川区の下水道は、戦後、整備してから大体５０年から６０年、経っております。というのは、最近ですが、下水道管が詰まったという事例もあったもので、それに対して何か対策は考えられているんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"東京都の区部におきましては、公共下水道の設置管理者は、東京都下水道局になっておりますので、そうした管渠の損傷ですとか、詰まりがあったときには、東京都のほうで速やかに対処しております。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"今、東京都という話ですが、品川区内の区道や私道に通っている下水道管の長さは大体どのぐらいありますかということと、実際に工事代金は、特に私道、区道もそうなんですが、どこで持つんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"ちなみに、私道に入ります下水道ですが、これは「私」の財産ですので、東京都並びに我々品川区でも、設置の延長等については管理しておりません。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"なぜ、品川区内の私道に設置してある下水道工事は、住民が持たなければいけないのか。私道はお金がかかかるというと、ちょっと矛盾しているのではないかなと思うんですが、その辺についてご見解を説明するよう求めました。","respondent":"家壽田下水道河川課長","answer":"まさに公権力で設置するというもので、税金でありますとか、料金をいただいてつくっております。「私」の中で適切に設置、管理していただくということが、下水道の中でも法に定められた原則です。","id":"exchange-122"},{"speaker":"須貝委員","kind":"意見","question":"そうすると、公と言うか、空から降ってきたものもそこに入っていく。その辺について、ちょっと、再度ご見解を説明するよう求めました。","respondent":"家壽田下水道河川課長","answer":"まさに公共下水道管理者は公共のところを守っておりますので、そこの部分の汚水、雨水を受け取っております。私の責任で公私境界のところまで適切に下水道管をつくっていただいて、つなげていただければ公共下水道管理者のほうでしっかりと処理しています。","id":"exchange-123"},{"speaker":"堺委員","kind":"質問・要望","question":"お尋ねをさせていただきたいと考えています未整備区間については、建物調査、埋設物移設調査委託等で１,７００万円強の費用が計上されておりました。平成２１年度は予算計上していないというふうに理解いたしますと、その調査結果はどうなっているのかということを、大変ありがたいんです。","respondent":"浜脇街路事業担当課長","answer":"ところが、平成１９年度につきましては、架道橋と庁舎等に関する耐震の影響の調査を行いました。それが昨年１２月に終わりましたので、私どもは、その事業評価マニュアルに基づいた新しい事業評価について、今、委託をしています。","id":"exchange-124"},{"speaker":"堺委員","kind":"質問","question":"費用対効果も含めて、昨年１２月にその見直しが終わって、新しい事業評価に基づいて始めるんだということなんですか。事業認可取得に向けて動き出すという理解でいいんでしょうか、ちょっともう１回、教えてくれませんか。","respondent":"浜脇街路事業担当課長","answer":"それには、やっぱり西口の影響、あるいは、補助２６号線の影響、補助１６３号線の影響といったものを勘案いたしまして、事業評価を出すものです。その辺の感触をつかむのが来年度だです。","id":"exchange-125"},{"speaker":"堺委員","kind":"質問","question":"そうすると、来年度とおっしゃったのは、予算書でいくと平成２１年度になるんですか。そうなりますと、平成２１年度の予算書の中には、それらしきものが計上されてないように思えるんですが、その辺はいかがか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"もしいい感触が得られた場合には、先ほど申しました測量であったり、詳細設計であったりといったことを改めて計上したいと思っています。今のところ、今回の補助１６３号線の中には、そういった調査費は含まれておりません。","id":"exchange-126"},{"speaker":"堺委員","kind":"意見","question":"この件について端的に、あそこには宮前小学校がありますので、要するにお尋ねしたいのは、この保水性舗装の事業期間と、その作業の時間帯。宮前小学校の正門がかかってまいりますから、その辺の絡みも含めまして、ちょっとこの事業についてご説明いただければありがたいんですとの意見を述べました。","respondent":"松代管理工事課長","answer":"通学路は、８時半、早朝の通学、また午後の帰宅といった時間等は、十分に安全対策を図りながら進めていく計画です。平成２１年度すぐにかかりまして、少しでも涼しく道路を通っていただく、お買い物をしていただくという計画です。","id":"exchange-127"},{"speaker":"堺委員","kind":"質問・要望","question":"その辺の学校の生徒の支障にならないように、ぜひひとつ、その辺も配慮して進めてほしいと求めました。時間がありませんので、下神明駅の現況についてだけ、お知らせいただけますか。","respondent":"梶都市計画課長","answer":"交通バリアフリー法、あるいはそれに基づく基本方針では、平成２２年までにエレベーター、エスカレーターなど段差の解消を目標としています。東急に再度確認していますけれども、平成２２年度中に終わるように、引き続き交渉していくという形で聞いております。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"土木費全般に出てくる設計というところで、よくわからないので、教えてもらいたいんです。基本設計、実施設計、調査設計、復旧設計、いろいろな設計という言葉があるんですけれども、どういうふうになっているのか説明を求めました。","respondent":"松代管理工事課長","answer":"基本計画、基本設計、それに実施設計という形の段階を踏んで、最終的には工事という形で進めてまいります。最後に実施設計といいますのは、金額をそれにはじき出して、総工事費は幾らなのかというような作業をするものです。","id":"exchange-129"},{"speaker":"須藤委員","kind":"意見","question":"そのあたりは何とかわかるんですけれども、調査設計とか、復旧設計とかというのがあるのと、実施設計とまた違うのか、同じなのか。それは実施設計のことで、同じということなら、それでいいんですけれどもとの意見を述べました。","respondent":"松代管理工事課長","answer":"基本的なものは、先ほど言いました基本計画、基本設計、実施設計が基本になってあります。例えば中身を検討する、もしくはそこの部分だけ取り出して詳細に検討して、そういったときに詳細というものを使うと思います。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そのあたりは、設計をしたものが、次に施工監理というのは、設計者に施工まで、監理を含めて委託しているという考え方でいいのか。監理というのは監督の監で、監理委託となっているんですけれども。","respondent":"松代管理工事課長","answer":"工事を請負業者が請け負います。それを、別な監理業者が、区の監督員の補助をする形で、実際の現場等の監理をするという委託の内容です。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"監理委託というのは、管理委託とはまた違うんですかね。","respondent":"松代管理工事課長","answer":"監理委託の監は監督の監です。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問","question":"３１３ページにしながわ水族館運営費で、設計とかいろいろなことの監理はどうなっているのかなと思ってお尋ねしたんですが、そこはいかがか尋ねました。","respondent":"藤田道路公園課長","answer":"申しわけございません。監督の監です。","id":"exchange-133"},{"speaker":"須藤委員","kind":"質問","question":"施工管理委託ということはありませんよと、施工監理の場合には監督の監を使うと理解していいんですか。それとも、施工管理という場合もあるのか、説明を求めました。","respondent":"藤田道路公園課長、岩田まちづくり事業部長","answer":"「管」を使う施工管理は、私どもが、通常、工事を管理する上では、工程を管理するとか、そういう流れの中で、こういう字を使うこともあります。ただ、私どもが監督業務の一部をお願いするという意味で行う場合については… 通常、現場を監督する、これは、区の職員が直に施工業者を現場で監督、指示をするということで、監督員という権限を与えておりました。","id":"exchange-134"},{"speaker":"須藤委員","kind":"質問","question":"それとも、３０３ページのほうは、ほかの部分で見るんですか。そのあたりはどうなんか尋ねました。","respondent":"松代管理工事課長","answer":"結論から申しますと、非常にちょっとわかりづらい表現だったということで、申しわけございません。ご説明しました、３０５ページの荏原町公園前緑道の部分につきましては、その直近の範囲で復旧をするための工事をするための設計委託というものです。","id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"同じ治水の工事でやっているんですけれども、そのあたりはどういうふうに考えているのか。改修とか、復旧とかというのは、そのあたりはどういうふうに考えたらいいか尋ねました。","respondent":"松代管理工事課長","answer":"地域の方に、工事でいろいろと利用でのご不便をおかけしましたけれども、いい形でこうなりましたという形にしたいと考えています。地域の声を聞いての実施設計、平成２１年度に工事をし、開園をしたいと考えているところです。","id":"exchange-136"},{"speaker":"須藤委員","kind":"質問","question":"３１３ページは復旧工事実施設計委託というような表現になっているんですけれども、きちんと分けてあるのか、どういうふうになっているのか。そのあたりがきちんとしていないから、何か読んでいてもわからないんですけれども、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"今後、きちんと改めて統一的な表現にいたします。申しわけございません。","id":"exchange-137"},{"speaker":"川西委員","kind":"質問・要望","question":"補助２８号線の計画道路についての現況、そして地元のいろいろなご意見がどう集約されているか、伺います。２人世帯、４人以上ですけれども、どういうふうにお考えになっているか聞きたいと思います。","respondent":"梶都市計画課長、藤田道路公園課長、片田建築課長、松代管理工事課長、齋藤住宅課長","answer":"ということは、いつから事業化されていくかは、まだ未定という形で、予定はないところです。いろいろ地元の方々と話し合いを行って進めていかれるよ… 排水場の関係の道路冠水等警報設備の設置工事につきましては、平成２０年に大雨の関係で、平成２０年にありました。… 私のほうからは、細街路の進捗状況等について、ご説明させていただきたいと思います。距離的には２.７kmほどを、今年度に整備してきております。","id":"exchange-138"},{"speaker":"川西委員","kind":"質問・要望","question":"補助２８号線のことですけれども、どういうふうな動きをしていいか悩んでいますが、あの歩道は反対側から来る人が通れないようなにぎわいです。今後、促進方について、その改善を要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は３１４ページの都市開発費に関連して、再開発での公益施設についての考え方を、伺いたいと思います。そもそも、ビルをとにかくつくろうということで、こういう基本的な住民要望、行政需要というところの把握がどうされているのか、聞きたいと思います。","respondent":"青木都市開発課長","answer":"事業者の責任において子育て支援機能を整備するということで、品川区としても、現在その再開発地区においての設置は検討していないという状況です。例えば武蔵小山の整備方針であるとか、公益施設のあり方というものも踏まえた上で検討を進めて、その検討の結果をもとに。","id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、検討しているんだということであれば、その検討の内容が全然実態に合っていないと思います。そこのところをお聞かせほしいと求めました。","respondent":"青木都市開発課長","answer":"ですので、例えば、住宅を新規に建設する場合に、何人ぐらいの人口増加が見込まれるか。そういったものは、私ども十分真摯に受けとめまして、必要があれば需要に見合うだけの施設配置をするように計画の修正をしてまいたいと考えています。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかったら教えていただきたいんですけれども、大体どのぐらい見込んでいるのか、お聞かせほしいと求めました。仮に入って、できないということになると、ますます再開発がおかしいということになってくるのではないかと思うんですけれどもどうか尋ねました。","respondent":"青木都市開発課長","answer":"それから、事業費については、まだ具体化しておりませんので、金額等は弾かれておりません。大体、総事業費の１１％ぐらい、平均しますとそのぐらいが再開発に対して補助金が当てられているとご理解いただきたいと思います。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"高まっていると思うんですけれども、例えばどこら辺まで義務化できるのか、そこら辺のところはどうなんでしょうか。区側が、先ほどお話ししましたけれども、お金は出すけれども、結局お願いする立場ということになるのか、そこのところはどうなんか尋ねました。","respondent":"青木都市開発課長","answer":"例えば保育園の設置等、あるいは公益施設の設置等について義務づけができるのかという点で申し上げますと、義務づけはございません。その地域にふさわしい施設が何であるかというものは検討の対象になっておりますので、今、事業者を指導しているというのが現実です。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"質問・要望","question":"事業者に義務化できないということは、ほんとうにこれだけの要望があるのが実現できるかということになってくるんです。ここのところが心配なんですけれども、どうなんか尋ねました。","respondent":"青木都市開発課長","answer":"つまり組合みずからが子育て支援施設を、設置しますということをみずから宣言して、それが都市計画で認められております。指導とともに組合員としての思いも伝えて、ご理解いただいて、組合の意思が固まってきているとご理解いただければと思います。","id":"exchange-144"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、北品川五丁目第１地区のところでも、行政側、区側は、いわゆる保育ニーズはちゃんとつかんでいるのか、どうなのか。どういう仕組みになるのか、お聞かせほしいと求めました。","respondent":"青木都市開発課長","answer":"北品川五丁目地区におきましては、あわせて子育て支援機能をもっと強化していきたいということをみずから提案していただいています。今回、提案されて、実現を目指しているものです。","id":"exchange-145"},{"speaker":"宮崎委員","kind":"意見","question":"４月でいっぱいになっていれば、保育ニーズにこたえるとなったら、それではだめだと思うんですよ。やっぱりそこのところの仕組みがおかしい、区のほうで設置したほうがいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問","question":"そこのところについて、どういう整備をするのか、お伺いしたいと思います。そしてまた耐震補強の計画といったところまで、この計画の中に入っているのか、お伺いしたいと思います。","respondent":"浜脇街路事業担当課長、松代管理工事課長、齋藤住宅課長","answer":"私どもも、こういった式典に関する部分については、役割分担を考えるようになります。今、おおむね考えておりますのは、式典におけるテントやいす… 西五反田五丁目から六丁目に向けまして約３００ｍの道路の改善を行ってまいります。非常に段差もあり、急勾配なところがありますので、そういったものを… 実施設計を踏まえまして、耐震補強だけではなくて、老朽化した住宅の長寿命化を図るという形で検討してまいります。","id":"exchange-147"},{"speaker":"三上委員","kind":"質問・要望","question":"やっぱり段差があるような公園だったものですから、経年で、そこらあたりきちっと整備をしていっていただきたい。建物が２棟あるわけですから、この件に関して、ちょっとお答えいただきたい。","respondent":"齋藤住宅課長","answer":"エレベーターの設置工事ですけれども、長年の懸案ですが、容積率との関係で、設置はなかなか難しゅうあります。今後ちょっと、エレベーター設置については容積率の関係でできないので、何とか違った形で工夫できないかについては検討してみたいと思います。","id":"exchange-148"},{"speaker":"本多委員","kind":"質問・要望","question":"そこで１点、お聞きしたいのが、車の場合ですと、駐車と停車が区別されております。それから、２９５ページの有料自転車駐車場、ずっと出ておりますけれども、この３駅なんですが、総工費と、品川区の歳出について、説明を求めました。","respondent":"諸石交通安全担当課長","answer":"撤去を予定している周辺を回りまして、戻ってきたときにまだあるものについては撤去するという形でやっております。したがいまして、現在の撤去のやり方を継続してまいりたいと考えるところです。","id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"そういったことを進めていただきたいのと、自転車については現状でいくということでいいのか、その辺を確認したい。それについての何か課題が、今現状であるかどうか、説明を求めました。","respondent":"諸石交通安全担当課長","answer":"１台につきまして１００円ということで、それから十分乗れるものも含めた形で、１台１００円ということで見込んでいるところです。この辺は何台駐輪台数があったので、それに見合う駐輪場をつくってもらいたいということで申し入れをして、ご理解をいただいているところです。","id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう必要性について、教えていただきたい。行政の土地所有権だと思うんですけれども、その辺のことについては、課題がないのか教えてほしいと求めました。","respondent":"諸石交通安全担当課長","answer":"お願いですけれども、先ほども申し上げましたとおり、いろいろなビルの建築の計画の時点で、区のほうへ意見照会がまいります。それの回答は、台数も含めたさまざまな意見をつけさせていただいて、回答させていただいているところです。","id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"２９７ページの道路冠水等警報設備設置工事、３カ所の説明があり、先ほども経緯について質問がありました。目黒川だと、危険水位だったり、警戒水位で音が若干違ったりしていますけれども、ああいう感じで鳴るのか、どういう形態なのか説明を求めました。","respondent":"藤田道路公園課長","answer":"今回、工事をどのようにやるかというのを具体的に、平成２１年度に検討していきたいと。その中で、どんな音を鳴らすか、あるいは視覚に訴えるようなパターンにするか、その辺についても検討していきたいと考えております。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問","question":"予算書で、警報設備ですとか、そういう文言があるんですけれども、防災気象情報等の提供についてということで、予算書全体として、防災気象という点では、トーンダウンしていないか、その点だけ１点、ちょっと説明を求めました。","respondent":"家壽田下水道河川課長","answer":"防災気象情報につきましては、これまでもさまざまな情報を提供しておったんですが、新年度の予算では、河川のリアルタイムの画像を区のホームページ上に提供するということもやりますので、防災性の向上については、日々努力して情報提供をレベルアップしているつもりです。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=920#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":124940,"voices":373}},{"id":"h21-20090323-3","meetingId":"h21-c-budget","date":"2009年3月23日","dateIso":"2009-03-23","committee":"予算特別委員会","time":"午前１０時０３分～午後６時０４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を144件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"私は３３５ページ、３目教育指導費の国際理解教育についてと、３４７ページの３目学校給食費の給食運営費についてお伺いをしたいと思います。これについての現状と今いろいろと言われていますリサイクルという中での今後の課題というのがあれば教えてほしいと求めました。","respondent":"富田学務課長","answer":"中学校８校、平成１９年度末のところであったところですけれども、そういったところで活用されているです。そういったことも踏まえ、生ごみの直接回収に順次切り替えをして、老朽しているところから切り替えているです。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問","question":"自分たちが出した残飯などをこういった形で活用ができているんだよというようなことを見せることも環境教育の一つだと思っているんですが、そういった多古町との交流というのは堆肥を買い取りに来ていただいている受け身の姿勢のような気がするんですが、その辺についてはいかがか尋ねました。","respondent":"富田学務課長","answer":"多古町では、品川に低農薬野菜を学校給食で使っていただき、そういうリサイクルをしていますよということをＰＲいただいているようです。十分に承知しておりませんので、今後そういったことも、いただいたご意見も学校に伝えていきたいと考えています。","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"次に、３３５ページの国際理解教育についてお伺いをしたいと思います。品川区独自でも、一貫性といいますか、連携というのがどのようにとられているかというのをお伺いしたいと思います。","respondent":"河野指導課長","answer":"教育委員会として国際交流の今後の考え方ですが、それぞれ中学校に約１カ月程度派遣をして、さまざまな交流活動をしています。今後の考え方ですけれども、子どもたち、異文化理解あるいは外国語に親しむということを中心に取り組んでいきたいというふうに考えているところです。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問","question":"さわる、見るというのは非常に大切なことになってくると思うんですけれども、いろいろ今区内でも行われているそういった国際のそういった事業との連携というのは現在とられているのかということをお伺いしたいと思います。","respondent":"河野指導課長","answer":"国際友好協会の事業に関する連携ですが、実際にホームステイで品川に訪れた際に、公式訪問ということで小学校あるいは中学校のほうで受け入れをさせていただいているです。","id":"exchange-004"},{"speaker":"井桁委員","kind":"質問・要望","question":"横とのつながりであったりとか、そういった友好協会との連携というのをますます強めていっていただきたいなと考えています。帰国児童・生徒など、適応指導員の増というのは具体的にどういったところで増額になったのかということをお願いいたします。","respondent":"河野指導課長","answer":"あるいは話すことはできるんだけれども読み書きがおぼつかないという子どもを対象に、日本語適応指導をＩＷＣ国際市民の会に委託して行っております。今回の予算の増額は、そのＩＷＣへの委託単価を増額したです。","id":"exchange-005"},{"speaker":"井桁委員","kind":"質問","question":"この委託単価の増というのは、直接教えていただいている方への報酬の増かとは思うんですけれども、その辺をお願いいたします。","respondent":"河野指導課長","answer":"現在ＩＷＣのほうには、いわゆる１レッスンといいますか、１回につき幾らという単価契約で行っております。その単価を今回来年度に向けてアップするというものです。","id":"exchange-006"},{"speaker":"井桁委員","kind":"質問","question":"やはり教えていただいている方も基本的にはボランティア精神といいましょうか、そのあたりでの密な連携というのが必要になってくると思うんですが、そのあたりをお伺いしたいと思います。","respondent":"河野指導課長","answer":"ＩＷＣのほうで子どもたちの日本語指導を行うに当たって、いわゆる子どもたちが勉強する場所ということで、山中小学校の教室のほうを提供しています。今後もＩＷＣとは密接な連携をとりながら、子どもたちの日本語適応指導に向けて取り組んでいきたいというふうに考えております。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"３３７ページ、３４０ページの学校管理費の中から、この３項目についてお伺いしたいと思います。見学・体験等で訪れる施設、それがどのようなものがあるのかということと、その考え方について教えてほしいと求めました。","respondent":"富田学務課長","answer":"日光江戸村、戦場ヶ原等々のそういった文化観光の施設でありますとか、自然の体験をするといったようなことが多いです。小学校は６年生で実施しており、中学１年で実施しておりますが、自然観察等々を行っているです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"これからも科学ということに目を向けて、この移動教室に環境科学国際センターですか、一つの候補として紹介をされてはどうかなというふうに思います。理科離れの件と、この環境への取り組み、そしてまた環境科学国際センターの件についてお伺いしたいと思います。","respondent":"河野指導課長","answer":"理科離れに関します教育委員会としての考え方ですが、現在東京都で予算をつけていただいております理科支援事業をはじめとして、子どもたちにとって。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"子どもからやはり力を入れていくことによって、大人のほうもいい影響を受けるのではないかなと思いますので、ぜひともよろしくお願いいたします。図書館のほうも随分ＩＴ化が進んできておりまして、どのくらいの利用があるのか、現状を簡単に教えてほしいと求めました。","respondent":"小川品川図書館長","answer":"インターネット上での予約等の処理件数につきましては、１日約１,２００件程度の件数があります。かなり増加傾向にございまして、年間のアクセス件数としましては、平成１９年度の実績としましては、全体で６０万件程度のアクセス件数があります。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"このようにＩＴ化が進めば、やはり利用される方も、見られる方も多いかと思います。このような計画も立ててはどうかなということも踏まえまして、今後の図書館の整備、ＩＴ化の方向づけにつきましてお伺いしたいと思います。","respondent":"小川品川図書館長","answer":"今のところ利用者からの特に要望もないのですぐに導入ということは考えておりませんが、図書館としても注目しています。ただ、今後も千代田区の状況やＷｅｂ図書館全体の動向や利用者等の要望等も把握し、動向を注視して研究してまいりたいと考えております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"最低４０インチ、そしてまたパソコン等とデータ授受ができるような入力端子等がついている環境を整備する必要があるというふうに伺っております。学校の授業、授業として利用するということに関しましての考え方と、交付金を活用したデジタルテレビの導入を含めた計画についてお伺いします。","respondent":"富田学務課長","answer":"地デジ対応ですが、同軸によるケーブルの整備とともに地デジ対応テレビ、またはチューナーつきのパソコン等々というものが必要になってまいります。ＩＣＴ化の進め方、それと国等の補助金の動向等々も含めてよく見据えた上で平成２１年度中に検討してまいりたいと考えております。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"平成２１年度に検討されるということですので、これは大いに期待をします。このようなケースが今まで学校関係の施設であったのかどうか、どのような対処をされたのか、この件だけお願いします。","respondent":"河野指導課長","answer":"電波障害の関係ですが、浅野委員がおっしゃっていた状況はありますが、今までの過去から見ますと、電波障害に対しての交付金なり補助金などの実績というのは、今のところございません。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"区としても取り組んでいっていただきたいと、そのように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、３３１ページのプラン２１推進事業に関連して、小中一貫校の運動会や卒業式、学校行事について幾つか伺いたいと思います。運動会でどういった意見が上がっているのか、どんなふうに考えているのか教えていただきたいのと、そんな意見も伺います。","respondent":"和氣小中一貫教育担当課長","answer":"平成２０年度におきましては、運動会は１年生から４年生中心の運動会を５年生から９年生が支援する形で行い、５年生から９年生の運動会には。保護者の皆さんとも十分に協議をし、例えば日野学園の運動会でも非常に満足、好評を得ているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"別の方は、踊り、表現活動というんですか、２学年共同、１年と２年、３年と４年、５年と６年と同じなので、２年続けて同じ踊り。伊藤学園でも例えば小中を別々にするのか、いろいろ検討すべきことがあるんじゃないかと思うんですけれども、ご見解を伺いたい。","respondent":"和氣小中一貫教育担当課長","answer":"毎年聞きながら、その中で改良を加えているというのは、先ほど申し述べたところです。ただ、そこら辺は十分説明をする必要もあるかと思いますが、５・６・７年生というまとまりで今考えておりますので。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ伊藤学園でお昼を家族で一緒に食べることができないのか、ちょっと説明していただきたい。運動会の昼食、お昼の時間、いろいろ改善すべきことが多いと思うんですけれども、いかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"親のいない子どもへの配慮ということで、多くの学校は給食で対応しております。一律にそういう思い出があるからというふうには考えられないというふうに思っております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"保護者の応援、場所とりもごたごたするという話も伺いました。今回小中一貫教育推進経費の中に課題の評価・分析とありますけれども、よく検証する必要があるんじゃないかと思うんですけども、いかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"もちろん運動会についても検証の結果は出てあります。それぞれ皆さん各学校が保護者の皆さんと十分協議しながら、そしてもちろん教育活動ですから、学校が主体的に運営しているものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"２に合わないせいなのか、６年生の卒業式が参加した保護者から卒業証書を渡すだけの形ばかりになっているんじゃないかと、そんな声も伺いました。私はしっかりやるべきだなと思うんですけど、いかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"しかし、例えば低学年が９年生に対してお別れの言葉を言っていく、これを見て、やはり感激をする、そういう声がたくさんあります。アンケートの結果をとっても、そのことで子どもたちの情操面が非常に豊かになっているんではないかというような声もたくさん出ているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"小中一貫校の６年生の卒業式とほかの学校の卒業式の位置づけが違うのかどうか、交流することは必要だと思います。保護者の方は、中学校でほかの学校に行く子もいるし、伊藤学園でも６年生の卒業式をちゃんとやってほしいと。","respondent":"和氣小中一貫教育担当課長","answer":"８年生が５年生の面倒を見ながら、リーダーとしてしっかりとしてその移動教室を終えていく。そういうことが十分醸成できておりますので、大変教育効果が高いというふうに考えてあります。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどもお話ししましたけど、交流するということと一緒にやるということはやっぱり意味合いが違うと思いますので、ぜひ改善してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それと３３３ページ、３３５ページ、国際理解教育についてお伺いをします。先ほどもほかの委員からの質問の中で、期間が１カ月だったりというのがあったんですが、これは全中学校でやられるんか尋ねました。","respondent":"富田学務課長、河野指導課長","answer":"給食、それと平成１８年度より教職員にパソコンを配備し行っております校務システム、この二つのシステムをあわせたものが学校ＩＴ化の推進経費です。プラン２１推進事業についてですが、毎年学校長のヒアリング等々を行いまして… 本区で実施をしている研修の主な内容というお尋ねですけれども、それから教育課題に対応する研修等、さまざまな研修を実施しています。","id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問","question":"教職員研修なんですが、先日の一般質問でも、そういった昔はなかったような問題等についての研修というのはされているのか尋ねました。","respondent":"富田学務課長、河野指導課長","answer":"学校により電子黒板等々を購入するところも出てきておりますので、そういった意味では活用が広がっているものと思われます。すべてが見れるというわけではないですけれども、他区に比べますと非常に規制は緩やかであろうと思います。次から次へと生じてくる新たな課題に対する研修・対応ですが、都のほうから、あるいは国のほうからさまざまな形でリーフレット等がまいります。","id":"exchange-023"},{"speaker":"石田（慎）委員","kind":"質問","question":"研修等も先ほど課長のほうから参加型といったようなお答えもいただきましたので、ぜひさらなる充実を図ってほしいと求めました。教員同士の交流、来ていただいた方との交流というのはどのような交流があるのか、もしわかっていたら説明を求めました。","respondent":"河野指導課長","answer":"ポートランドからお見えになった、滞在期間中、職員室で日本の教員と同じような勤務体系で勤務していただいております。そういう中で、さまざまな形での交流が行われているというふうに聞いているところです。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"確認","question":"どうも自分の周りだけだとは思わないんですが、あえての課題があれば、この英語科の点で伺えればと思います。一人ひとりの学習ペースに重点を置いて行っているものと同じなのかなと思ったので、このステップアップの確認を伺えればと思います。","respondent":"和氣小中一貫教育担当課長","answer":"ちょっと分量が、そういう意味で、３年間の実践を通じて見えてきました課題について改訂をしてまいりたいというふうに考えているところです。さらに充実をさせてまいりたいと考えていますし、これにプラスしまして、各学校では土曜日や夏休みを使ってさらに補習授業。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"確認","question":"次に、平成２０年３月発行の区立小中学校に関する区民アンケートという点から、まちの人々に学ぶ等に関係するかと思いまして伺います。このやはり３団体というか、学校がリードしてはどうかという話がありましたので、地域力のねらいとこの三つのあり方という点で伺えればと思います。","respondent":"河野指導課長","answer":"学校、家庭、地域の連携について、私のほうからお答えをさせていただこうと思います。日本全国蔓延していた状況の中で、そういう願いもあって、こういうような取り組みにいち早く取り組んできたというふうに私は理解しております。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"ぜひ取り入れてほしいと、そういった考え方の教育現場への効果をねらうやり方というんですか、考え方を最後に伺えればと思います。お願いします。","respondent":"河野指導課長","answer":"教員に関しては、そういうことが言えるのかもしれませんが、対子どもに対しては、決してそんなことはないと思います。家庭、地域の力で乗り越えさせていく、そのことがやはり将来を担う子どもたちにとって大切な学びではないかというふうに考えております。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"私は教育指導費の中の、３３３ページの市民科・各教科充実経費について、ちょっとお伺いをさせてほしいと求めました。それともほかに、それから、何年生を対象にこういう授業をなさっているかを教えてほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"情報についての認識を学びまして、有効活用の方法について、もしくは危険性について教えるです。ニフティと連携をしまして、インターネットをどう安全に使うかということを５年生、もしくは６年生を対象にして直接やっているところです。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"１年生から準備して、最高年齢のときにはきちっとした形になってくるということですけれども、実際これは先生が教えていらっしゃるんでしょうか、それとも、だれか特別な講師がいらっしゃって、各学年に教えていらっしゃるんでしょうか、その辺、教えていただけますか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"それでまた研修の中でどういうふうに情報モラルを教えるのかということについても教員は協議しておりますので、基本的には担任がやっているです。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"昨年、品川区で携帯電話に関する保護者アンケート調査ということを行ったということですが、これに関してのアンケートの内容、またその結果はどういうことであったのか、もしわかれば教えてほしいと求めました。","respondent":"河野指導課長","answer":"品川区の教育委員会のほうで携帯電話に関する保護者アンケートを実施したわけですが、あるいはあまり心配していないとか、そういう設問です。それから、実際には学校でもっと指導していただきたいというふうに思っている保護者の方が多かったというのが内容です。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"中学生は４人に１人、高校生は１０人に３人、また特別支援学級のお子さんに関しては５人に１人がネット被害に遭っているということなんですね。先生方が例えばそれに対しての研修会とか、何かそういうお勉強をするような研修等をなさっているんであれば教えてほしいと求めました。","respondent":"河野指導課長","answer":"教員を対象に実施している情報モラル研修の中身は、携帯電話を使うことによって。まさに子どもたちに対して、本区の教員とニフティのほうが連携をしながら、いわゆる内容について開発をしてきたという状況です。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"何か４月にインターネットに関する法律が施行されるというふうに聞きましたが、その辺は区のほうとしてはお聞きになっていらっしゃいますか。もしその内容がわかればちょっと教えてほしいと求めましたが、いかがか尋ねました。","respondent":"河野指導課長","answer":"今委員ご指摘いただきました４月に法改正というお話でございましたが、現在まだ私どもそのことについては把握しておりませんので、状況等わかり次第、また具体的に取り組んでいきたいと思います。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"ぜひよろしくお願いいたします。実際、現場的にご家庭がどのように取り組んでいるというんですか、状況的に教育委員会のほうで把握なさっているかどうか教えていただけますか。","respondent":"河野指導課長","answer":"その内容等についてまとめたものは、すべての小学校、中学校を通して全保護者に概要版という形で配布するという予定で現在進めているところです。家庭でルールを定めるべきであるという認識、呼んでいるものを、今現在学校と連携をしながら策定を進めているところです。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"昨年ですか、今課長が品川ルールとおっしゃいましたが、内容的にはこれと同じようなものなんか尋ねました。","respondent":"河野指導課長","answer":"指導したからそれで終わりということではなくて、常々その子どもたちの使用状況についてもきちんと保護者もチェックをする、そんなことを盛り込んでいきたいというふうに考えているところです。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひ活用してほしいと求めました。以上で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"高橋委員","kind":"質問・要望","question":"総務費のときにちょっとお話をしたんですが、伊藤学園、日野学園、それぞれのプールの維持費というんでしょうか、わかればお願いします。もし、プール自体が独立してわからない場合は、日野学園、伊藤学園の維持管理費というんでしょうか、その項目がわかればお願いしたいと思います。","respondent":"河野指導課長、富田学務課長","answer":"従来教育課程の中に小学校ではクラブ活動という時間が盛り込まれておりましたけれども、それが廃止をされたというのが主な変更点かと思います。それから、指導できる方にお願いをして… ビルといいますか、施設としての総合維持管理にかかわる予算として日野学園についてはおよそ小中あわせて４,０００万円、伊藤学園については５,７００万円です。","id":"exchange-036"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうではなくて、上乗せという言葉が悪いかどうかわかりませんが、そのようなことは仕組み上可能なんでしょうか。これは要望で総務費でもお話ししたんですが、公共施設の維持管理費、これからたくさんいろんなものもつくるし。","respondent":"河野指導課長","answer":"教員の部活動指導にかかわる支援というお尋ねですが、部活動指導援助費ということで、１,０００円を予算措置しています。したがって、あるいはけがをしたときに、今般本人が承諾をした場合には服務として校長は命ずることができるというふうにはっきり明記されたです。","id":"exchange-037"},{"speaker":"高橋委員","kind":"質問・要望","question":"どうも詳しい説明をありがとうございました。３３３ページ、両機能を追求しているというふうにお聞きしているんですが、その要望に関してどうお考えかということをお願いいたします。","respondent":"田村庶務課長","answer":"やっぱりプラン２１に放課後対策が位置づけられているというのが全国の先陣を切って始めた事業ですが、やはり特徴的なのかなと思います。土曜日については９時から５時という形で、やはりその辺を踏まえて現行のまま対応できると、そのように考えております。","id":"exchange-038"},{"speaker":"高橋委員","kind":"質問・要望","question":"ちょっと意味があれですか。独自採用の先生を派遣することで本来文部科学省のほうから２クラスという形で来るのを３クラスにするということはできるんか尋ねました。","respondent":"河野指導課長","answer":"ＮＰＯとの協議の結果、学習支援員に対する報償単価が１,４００円ということで、当初予算より１００円減額されるという見込みになりましたので。実際来年４月１日より配置を予定しております区費教員も中学校に３名、小学校に２名の予定でおります。","id":"exchange-039"},{"speaker":"高橋委員","kind":"質問・要望","question":"必要なものですから、求めるべきではないかと思ったりするんですが、いかがでしょうか。幼保一体でやっていこうということですから、幼稚園の教員を独自採用するというお考えについてはいかがか尋ねました。","respondent":"河野指導課長","answer":"私のほうもはっきりと認識しているわけではございませんが、東京都の場合には財政的にその対象にはなっていないというふうに聞いております。特別区人事委員会での採用ということで実施しておりまして、定数外でも時間講師等で対応していますので、現在のところ区費。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"３３３ページの市民科について伺いたいと思います。市民科導入に至った子どもたちの実態というんですかね、それについてどのように考えているか伺いたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"そして総合的な学習の時間でそれぞれ子どもたちが生きていくために必要な力というのを本当につけさせていかなければいけないというふうに考えたわけ…そういう危機感からまず始められる学校から始めていこう。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"あるいは戦争の問題でも、イラク戦争がありましたけども、これを子どもたちはよく見ているんじゃないかという点があるんじゃないかと思います。伺いたいんですけども、社会的マナーの低下、この原因というのは子どもの意識の低下による自己責任によるものだと考えているんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"そういう子どもたちをつくらないということが私たちの使命であろうというふうに考えております。何も知らない、何も聞いていない子どもたちが社会に出て、社会に出たことによって戸惑ってしまう、そんな子どもたちを私たちはつくりたくないです。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"２位のアイスランドも１０.３％ですから、実に３倍の方がこうした感情を持っているということなんです。もしかすると、逆効果になってしまうんじゃないかとちょっと懸念してしまうんですが、そこらに関してはいかがか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"結果的に、両方とも考えるという行為が市民科の中でメインであるということを示しております。というように、市民科は子どもたち自身が本当に社会で生きていくための力を本当に育みたいというために行っている教科です。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"私はどうしても押しつけ、どういう表情をつくるのか、本人の表現のあり方というのは全く本来ならば自由であるべきなんですよ。逆に私はその人の健全な精神的な発展を妨げるおそれもあるんじゃないかということを懸念しているんですけども、そこはいかがですかね。","respondent":"和氣小中一貫教育担当課長","answer":"そういう中で、子どもたち自身が自分で考えてきているんです。そのことが市民科の一番のねらいです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"どういうところまで細かく指導しているんですか。具体的にどう教えているか、会話の中で、どこまで教えているのかお伺いします。","respondent":"和氣小中一貫教育担当課長","answer":"口を下げてとか、そんなことを教えていません。それは子どもたちによってそれぞれ違いますので、そのことを事細かにああしろ、こうしろという教え方はしておりません。","id":"exchange-045"},{"speaker":"山内委員","kind":"質問・要望","question":"３２８ページの教育指導費全般でちょっとお尋ねをさせてほしいと求めました。将来性、それからこの答申をどういう形で役立てていくかというか、そういうところをまず説明を求めました。","respondent":"富田学務課長","answer":"今後の学校配置、学校の校舎の改築のあり方を含めた検討を進めていっていただきたいといったようなことを答申としていただいたところです。校舎改築の時期とちょうど重なってまいりますので、そういったところを含めて今後検討してまいりたいというふうに考えております。","id":"exchange-046"},{"speaker":"山内委員","kind":"質問・要望","question":"今度教育改革プラン２１についてなんですが、平成１１年からですよね、このプラン２１。その前と現在というか、あり方というのがどんな感じで変わったのかというのを少し教えていただきたいんですけど。","respondent":"河野指導課長","answer":"あるいはプラン２１を含めてそうですけれども、人数的にもかなり不登校の状況というのは改まってきているのではないかというふうに思います。９年生が３.７倍ということで、平成１９年度の比較を見ても、なめらかな曲線になっているということが統計的にうかがえるところです。","id":"exchange-047"},{"speaker":"山内委員","kind":"質問","question":"こういうところで、そういう問題に対して、やはり品川区の教育委員会というものはしっかりと取り組んでいっていただけることを切に希望いたします。これは平成１９年９月４日の資料なんですけれども、それから比べまして、今の現状というものはどんな形で推移しているのか説明を求めました。","respondent":"河野指導課長","answer":"小規模校における学習活動、本区に始まっただけではなくて、既に東京都内でも学校統廃合を検討する委員会の中で指摘をされているところです。","id":"exchange-048"},{"speaker":"藤原委員","kind":"質問","question":"３５７ページの荏原第六中学校についてお伺いしますが、これから設計と工事が進んでいきます。区として設計と工事に当たって最も大切と考えていることとか、重要と考えていることをまず説明を求めました。","respondent":"田村庶務課長","answer":"耐震補強そのものをできなくはありませんが、来年度から基本設計、実施設計を手がけるという形になっております。工事期間中の学習環境の確保、それとやはり改築工事に対する近隣の皆様の理解とご協力と、その点が最重要課題というふうに考えております。","id":"exchange-049"},{"speaker":"藤原委員","kind":"質問","question":"私も最重要課題は、やっぱりそこで学ぶ方たちといいますか、お子さんの環境だと思っていますが、そこを思いながら質問しますが、４月入学予定の新入生はどのぐらいの数になっているんか尋ねました。","respondent":"田村庶務課長","answer":"３月１６日現在で昨年度が５９人の入学ということでして、平成２１年度については３月１６日付で８２人の入学予定です。","id":"exchange-050"},{"speaker":"藤原委員","kind":"質問","question":"増えているという解釈でいいと思うんですけれども、実際今年度の新入生は８年生、９年生のときが工事期間に当たりますよね。いい環境、それでもこれだけの方が行きたいという希望を出した何か動機付けといいますか、がもしわかるんであれば教えていただけますか。","respondent":"田村庶務課長","answer":"説明会も対象をこれからの新入生と、それと在校生と、在校生を先行しまして、２回に分けて夜間の説明会を実施したです。その辺も説明会の中で校長から説明をし、そういう状況をすべて承知した上で荏原第六中学校を選択してもらったと、そのように理解しております。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問","question":"あの環境でという気持ちは正直言ってあると思います。小山小学校の子どもたちは実際工事をしていたときにどんな感覚を持っていたのかということを、もしわかれば教えていただけますか。","respondent":"田村庶務課長","answer":"今藤原委員のおっしゃった内容は、特にこれから新入学生として入る、新入学生の保護者の説明会でも質問がありました。仮設校舎という前提で説明していますので、あるいは第二延山小学校から荏原第六中学校のほうに希望していると、そのように理解しております。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"実際に工事が始まれば、やっぱり環境に関してはあまりよくないということはわかり切っていることです。今課長がいろいろ答弁をしてくれて、こういうふうにやっていきますということがあれば、もう一度お答えをほしいと求めました。","respondent":"田村庶務課長","answer":"最も大切なことは、近隣の状況を見ますと道路も狭いですので、やはり近隣の皆様の理解とご協力というのが不可欠だと考えております。引き続き教育委員会と学校と十分連携して、ご理解とご協力を得て無事に工事に着工したいと、そのように考えております。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"２点質問します。どのような教育現場に学習支援の方々が派遣されているのか、そういった実態についてお聞かせをほしいと求めました。","respondent":"和氣小中一貫教育担当課長、河野指導課長","answer":"そういう意味で、私どもは一つ大きな節目として１０歳を考えながら、系統的に学びをしていけるというのがメリットだというふうに思っています。９年制という考え方が非常に今の子どもたちにとって効果的ですし… それぞれの学校で障害のある子どもに対する個別指導計画に基づいて教員が行うべき支援、それから学習支援員がかかわるべき支援。","id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"今の６・３制と９年制なのか、４・３・２という言い方なのか、またそこら辺のことについてお話を伺いたいというふうに思います。これもメール配信システム、これが今現状どのようになっているかというのをちょっと確認をさせてほしいと求めました。","respondent":"和氣小中一貫教育担当課長、河野指導課長","answer":"先ほど委員も言われたように５・４制とか４・３・２ということで、今のアンケートでも半分ぐらいしかなかなかよくわからないとお答えになっています。… その場合、直接学校に見えた学習支援員あるいは介助員に作業内容の変更を学校が指示するということができません。の連絡でメールを使うということで整備を進めているところです。","id":"exchange-055"},{"speaker":"阿部委員","kind":"質問","question":"３５３ページの学校改築推進経費について関連してお伺いします。この２月に文部科学省のほうの特別支援教育の推進に関する調査研究協力者会議ですか、そこで中間まとめが出て、中でも就学相談についてなんですが。","respondent":"和氣小中一貫教育担当課長、河野指導課長、田村庶務課長","answer":"さらに本格実施になります平成２３年に１・６年生がやっぱり週１時間、平成２４年度に７・９年生が週１時間程度増えます。… それから、全国的に見た特別支援学級の設置率が数字の上からいうと６４％というご指摘ですが、かなり状況が異なっております。… 北品川の再開発事業とずれが生じないように十分調整した上で事業を進めていきたいと、そのように考えております。","id":"exchange-056"},{"speaker":"阿部委員","kind":"質問","question":"品川区の小中学校の中で、どういう形ですべての学校で支援できる体制をつくっていくのかというお考えを少し大きなところで伺えればと思います。ずれがないようにということは、高層ビルが建ち上がるまでには校舎ができると理解してよろしいのか尋ねました。","respondent":"河野指導課長、田村庶務課長","answer":"当然隣の村まで電車・バスで１時間、そこに在席している子どもの数が非常に少ないというのが実態であるというふうに認識をしております。すぐに特別支援学級の併設校を増やしていくという考えは持っておりませんが… 教育委員会サイドはやっぱり教育委員会サイドの思いがあると思いますので、今後十分に調整を図ってまいりたいと、そのように考えております。","id":"exchange-057"},{"speaker":"阿部委員","kind":"質問","question":"全体的な、どの学校でも特別な支援が受けられるという体制にはどういった形がいいのかということをぜひ今後もご検討ほしいと求めました。とりあえずそこのところをお願いします。","respondent":"市川教育次長","answer":"ハード事業の調整、特に財源の確保といった、そういった調整をしなければならないものもあります。その結果、平成２１年度の予算案には記載をされていないということでご理解をいただければと思います。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"午前中に石田慎吾委員のほうから少しありました。そういった事業を考えてはどうか、検討してはどうかと思うんですが、それはいかがか尋ねました。","respondent":"河野指導課長","answer":"海外に交流ということで派遣をすることによって、子どもたちの教育活動に派遣した場合と派遣しなかった場合、どういう影響があるのかというようなことも含めて今後検討させていただきたいと思います。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３３１ページ、移動教室、特に中学校についてお伺いをします。家庭訪問、全部やるといったら１００％だけど、それが今何パーンセトぐらいは家庭訪問をやっているのかという数字がわかれば教えてほしいと思います。","respondent":"富田学務課長、河野指導課長","answer":"それ以外の地域を希望する場合には、平成２１年度については磐梯に行く学校が若干減ってくる見込みです。年度当初の説明会につきましては、磐梯のほうに行く学校を集めまして、教育委員会で各学校を対象に行っております。移動に要する時間等を考えますと、そこで懇談をする、面談をするということのほうが効率がいいということで取り組んでいるケースが大部分です。","id":"exchange-060"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"子どもたちにとって、私はそこの部分のメニューづくりは教育委員会でするべきだろうと思っていまして、そこら辺の考え方を教えていただきたい。それは私はしっかりやるべきだと思うんだけど、そこら辺の考え方をもう一度教えていただきたい。","respondent":"富田学務課長、河野指導課長","answer":"移動教室の目的に沿った内容が実現できること、また安全性を重視するといった意味で引き続き努力してまいりたいと思っています。平成２１年度は磐梯高原が２校減りまして１１校ということで、ぜひ一緒に考えていきたいと思っています。ただ、昨今学校が家庭の中にどこまで入り込んでいけるのか、プライバシー等の問題もあって、直接拒否をする家庭も増えていることも事実です。","id":"exchange-061"},{"speaker":"石田（秀）委員","kind":"質問","question":"校長会が決めようが、どこがやろうが、みんな大変なんですよ。それを教育委員会がしっかりそういう部分を探す苦労を校長会でやるのが大変でしょうと言っているわけですから、それはよく考えていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"市川委員","kind":"意見","question":"それから３４５ページの学校給食費から、それから３２８ページの教育指導費になるのか、ちょっと教育に対する考え方というところでお尋ねします。","respondent":"富田学務課長","answer":"学校配当予算のことではないかと思うんですが、特色ある教育活動経費につきましては、これまでと同様に学校のヒアリングを行った上でそれに基づいた学校への予算配当というものを行ってまいりたいと思っています。","id":"exchange-063"},{"speaker":"市川委員","kind":"質問","question":"そうしますと、ここに計上されてある金額がすべて特色ある活動としてプラスされる予算ということなんか尋ねました。","respondent":"富田学務課長","answer":"この中では、学力テスト実施費と特別教材購入費等といった、ここの部分について各学校に配分してまいります。","id":"exchange-064"},{"speaker":"市川委員","kind":"質問","question":"どういうプロセスで決定されていくのか、どんなようなことをされて決まるまでの流れになっていくのかというあたりをお聞きしたいんですけれども、お願いします。","respondent":"和氣小中一貫教育担当課長","answer":"８月に教育長を中心にしてヒアリングをやりまして、さらにその内容を最終的にどういう形で各学校に渡していくかということを決めてまいります。","id":"exchange-065"},{"speaker":"市川委員","kind":"質問","question":"学校の特色を生み出す校長、または学校の裁量権というんですか、これをどういうふうに考えていらっしゃるのかちょっとお聞きしたいと思います。","respondent":"富田学務課長","answer":"従前、学校長の裁量予算というのを行ったこともありましたけれども、やはり公費ですので、一般需用費ですとか、あるいは備品購入費ですとか、そういった費目の定めがありますので、いただいた要望に対し査定をした上でそれぞれの金額を学校に対して執行できるようにしているです。","id":"exchange-066"},{"speaker":"市川委員","kind":"意見","question":"ここはぜひ埋めていかなければいけないことじゃないかなと思うんですけれども、このための策というのが必要かと思いますけれども、その辺をどのように考えていらっしゃるのかお願いしますとの意見を述べました。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"学校運営費等々、保健運営費等々を含めてかなりの金額を学校にそもそも学校長の学校単位で使えるものとして渡しております。例えば学校割で４００万円強でありますとか、中学校につきましても５００万円程度ということで… になってしまい、極端に言えば、そんなことが今までの学校の感覚だったというふうに私どもは考えております。","id":"exchange-067"},{"speaker":"市川委員","kind":"質問・要望","question":"命をはぐくむ食の体験を通して学ぶという取り組みが大変評価できるというふうに思います。まず質問の１点目は、たくさんの学校で体験学習の充実を進めてほしいと思いますけれども、２点お願いします。","respondent":"河野指導課長、和氣小中一貫教育担当課長","answer":"場所はそれぞれさまざまですが、取り組んでいるところです。なお、農作業のほかにも育児体験であるとか、私どももそういう学校の取り組みに対してはできる限り支援をしていくというふうに考えているところです。特にこれがという形ではありませんが、都立高専と組んで、その中で都立高専に進学する子どもが出現をしたりというふうな形でつながっております。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"私がお尋ねしたのは、特色ある教育活動で成果があったようなものを品川区として学校全体に広げて、品川区の特色として出されるという、こういう考え方はどうですかということをお尋ねしたので再度お願いします。","respondent":"和氣小中一貫教育担当課長","answer":"これらの特色ある教育活動でやったことにつきましては、研究発表会を各学校が行っております。もしくは自分のところにいいなというものはそれぞれ取り入れながら教育活動を進めておりまして、それぞれが共有しているという現状があります。","id":"exchange-069"},{"speaker":"市川委員","kind":"提案","question":"２００４年から生活者ネットワークは学校給食の食材購入、食材納入の目安として、食材規格書が必要ではないかという提案をしています。お尋ねしたいんですけれども、どんなチェックをして使われている食材を把握されているのか、その辺を説明するよう求めました。","respondent":"富田学務課長","answer":"食材の選定チェック等々といったことにつきましては、各学校担当の栄養士の職務ということで栄養士が行っているところです。","id":"exchange-070"},{"speaker":"市川委員","kind":"提案","question":"学校給食の食材に関する規格を策定している市や区は７区、こういう食材規格書を策定して、実際それに沿って食材の納入をしているということです。これらを盛り込んだ学校給食、食材に関する規格をつくることを提案しますけれども、この点はいかがか尋ねました。","respondent":"富田学務課長","answer":"品川区は従来より区としての基準、また学校給食衛生管理の基準というところで文部科学省が定めた基準、こういったものに基づいてやっておりましたし、今後とも基本的にはこういったものにのっとってということで進めてまいりたいと思っています。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"それから、最後ですけれども、自尊教育への考え方について伺いたいと思います。私は積極的に進めていただきたいというふうに思うんですけれども、品川区の考え方、今後に向けてというところで見解をお伺いできればと思います。","respondent":"河野指導課長","answer":"いわゆる市民科の中で教えるべき内容として、我と我々の世界という、我々の合い言葉のようなものがあります。そういう人間関係の構築が大事であるというふうに認識しておりますので、子どもの自尊感情を高めるということに努力してまいりたいと考えています。","id":"exchange-072"},{"speaker":"菊地委員","kind":"質問","question":"平成２０年度は小学生４人に１人ですか、中学校が３人に１人の方が就学援助を受けているということですけれども。何かいろんな資料を見ますと、ちょっとその辺の品川区の設定基準と考え方についてもお聞かせを願いたいと思います。","respondent":"富田学務課長","answer":"平成２０年度の就学援助の認定の状況ですが、申請に対し認定者がおり、認定されなかった方は約１,０００人程度です。それで、就学援助の基準ですが、主に所得が生活扶助の１.２５倍といったようなところを基準としております。","id":"exchange-073"},{"speaker":"菊地委員","kind":"質問","question":"５人の家族でお子さんが３人おられて、実際に学校を通じて申請を受け付けるということなんですけれども、その際にどういう説明がされているのか。区の資料ですと、この辺の説明はどういうふうになっているのかというのも教えていただけますか。","respondent":"富田学務課長","answer":"世帯の人数と目安の基準額というものを載せてありますけれども、一律これでというわけにはいかないということも書き添えているところです。高くても１.２倍であるとか、経緯も含めて１.２５倍という、経済的に大変な方への支援ということでこの基準で実施をしてきております。","id":"exchange-074"},{"speaker":"菊地委員","kind":"質問","question":"今、やっぱりこれをぐっと広げてもっと多くの子どもたちがこれを受けられるようなものにしていく必要性があるんではないかというふうに思うんです。平成２０年度、先ほどのお話だと１,０００人の方が認定外だったということですから、その辺はどうか尋ねました。","respondent":"富田学務課長","answer":"ぜひ品川は下げないでほしいというふうに言われたところであります。入院、倒産により著しく減少した場合、こういった方々についても特別認定ということで再判定ということで行っているものです。","id":"exchange-075"},{"speaker":"菊地委員","kind":"質問・要望","question":"基準を下げないでほしいと頼まれましたというんですけれども、課長もさっきお話ししたように。ですから、重ねての話になりますけれども、やっぱり今のこの１.２５倍という基準をぜひ今後拡大をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"山路委員","kind":"質問","question":"仙台で３０年ぶりに試験をやるということで、品川区としてはどのようにお考えでしょうか、今後の優秀な人材確保をしていくために。もう一点は、教育訓練給付制度についてどのように活用されているかお伺いいたします。","respondent":"河野指導課長","answer":"実際に採用選考に募集していただいたという経緯もありますので、来年度についても今のところは今年度と同じような形態で募集をかける予定です。現在のところ私どももそういうような項目で免許取得のための支援をしていますが、既に教員になっている者の中から今年度。","id":"exchange-077"},{"speaker":"山路委員","kind":"質問・要望","question":"このことを要望いたしておきます。２点目の保幼小連携教育推進費ですが、どこの学校で、どのような展開をしていくのか教えてほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"それと、品川では市民科という教科をやっております。これも含めてどういうふうに連続性を持って向かえていくか、そういうところをしっかり検討していきたい、そして実践していきたいです。","id":"exchange-078"},{"speaker":"山路委員","kind":"質問・要望","question":"次に進ませていただきます。中学校の道徳の時間に使用されているですが、４月から改訂されるですが、この改訂の内容について教えてほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"私どもはあくまでも市民科を中心にやっておりまして、「心のノート」は参考資料ということで、各学校に配付をしております。その市民科のやっていく上で必要な部分でもし使えるんであれば、「心のノート」の一部も使うということで配付しているものです。","id":"exchange-079"},{"speaker":"山路委員","kind":"質問","question":"教育基本法などの改正を受けた新学習指導要領を反映した内容で、若干変わるということが新聞報道でもされているわけですけど、道徳教育推進教師制度についてはどのように品川区は展開をしているのかお伺いいたします。","respondent":"和氣小中一貫教育担当課長","answer":"それから、道徳教育推進教師ですが、私どもは各学校に市民科の推進教員を置いております。この市民科の推進教員がそのままそれを担うといいますか、既に担っていると言ったほうがよろしいでしょうか、そういう考え方を持ってあります。","id":"exchange-080"},{"speaker":"山路委員","kind":"質問・要望","question":"その規範意識ですが、もう少し具体的にどういう教育を行われているか、お聞かせほしいと求めました。","respondent":"和氣小中一貫教育担当課長","answer":"そのことで社会的な関係を円滑に保っていける、もしくはみずからの生活自身もそのことによって支えられていくというようなことをしっかりと具体的な社会事象や、具体的な自分たちの活動の中から学んでいくというようなことを市民科でやってあります。","id":"exchange-081"},{"speaker":"山路委員","kind":"提案","question":"盗難といいますか、以前私も提案させていただきまして、年間にトータルしてどれくらいの不明図書があるのか。図書カードも不明があるのかお伺いいたしますとの意見を述べました。","respondent":"小川品川図書館長","answer":"ちなみに平成２０年度の不明資料なんですが、図書としましては４,９００件ほどの不明資料がございました。紛失になられたりというようなことはたまにありまして、そのときにはその都度窓口で再発行をするなりさせていただいているところです。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問","question":"４,９００件というのはかなりの数で、この辺の対応はどういうふうに考えていらっしゃるんでしょうか。広告代をいただいて、そういう費用対効果のことも今後検討したらどうかと思うんですが、どのようにお考えか尋ねました。","respondent":"小川品川図書館長","answer":"１点目の不明資料に対する対応ですが、現在１０館中ＢＤＳ機能、それから平成２０年度に大井にもつけさせていただきました。平成２１年度、来年度の予算で大崎図書館にもつける予定です。","id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"申しわけございません、時間がなくなってしまったんですが、品川地区の小中一貫校、環境配慮型の学校を非常に期待しているわけですが、簡単に建物と事業内容の両方の部分の環境配慮についてお聞かせほしいと求めました。","respondent":"田村庶務課長","answer":"委員ご指摘のように校庭の一定の広さあるいは裏の権現山公園の緑の連担ということで、やはり今回品川地区小中一貫校というのをエコスクールという形で、これからいろいろ具体的に検討してまいりますが、そういう形でＰＲしていきたいと、そのように考えております。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"３４５ページの入学支度金になるんでしょうか、３３３ページでファイナンス・パーク、確認も含めてお願いします。ですから、そのときにもこの助成金は必要ではないかなというふうに思いますが、その考え方をお聞きします。","respondent":"富田学務課長、堀越生涯学習課長、和氣小中一貫教育担当課長","answer":"小中一貫校の平成２１年度ですと新１年生の標準服費ということですが、ただいま調べておりますので、後ほどお答えしたいと思います。これは新入学の時期に合わせて商店街連合会の方、それから地域の方々に対して配布をすべく、今準備を進めてあります。… 副読本については基本的に各教科についてばらつきはありますけども、例えば市民科はもうすぐ第１版が売り切れてしまうほどになっております。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、５年生のときに一気に変えますよと。ですから、５年生のときにそういう学校でいろいろ決めたことではありますけれども、ぜひ支給を考えていただきたいというふうに思います。","respondent":"富田学務課長、和氣小中一貫教育担当課長、堀越生涯学習課長","answer":"小学校１年生以外の方につきましては、７年生になるときに就学援助の対象と一律にしておりますので、５年生からということは今のところ考えておりません。ズボンだけかえればいいとか、なるべく負担が少ないという形でやられているというところもありますので、そこはご理解いただきたいと思います。８３運動のステッカーの件ですが、幅広くいろいろな場面で検討していきたいというふうに考えております。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、中学校のときに出るというのがあるわけですから、そこはお金でどういう形になるかどうかわかりません、制度的に。ですから、補助金を出していただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"林委員","kind":"質問","question":"教育委員会が変わろうということですから、ここにいらっしゃる理事の皆さんは、３２７ページに教育委員会の額が出ている。ここに教育委員会のメンバーが１人、そして教育委員会事務局の全員がいるというふうに理解しているんですけれども、間違っていますか。","respondent":"田村庶務課長","answer":"ページで言いますと３２７ページ、教育委員会運営費の委員報酬につきましては、委員長分、職務代理分、委員２人分で教育長の分はその下の職員給与費、その中の７８人の中の１人として、教育長はそちらに含まれているという状況です。","id":"exchange-088"},{"speaker":"林委員","kind":"確認","question":"確認します。４人ですか、５人ですかと聞いているんだから。","respondent":"田村庶務課長","answer":"５人の教育委員の中の教育長は一人です。","id":"exchange-089"},{"speaker":"林委員","kind":"質問","question":"教育長ですよね。その５人の教育委員会というのがあって、図書館も入れてやっていく、そういう感覚でよろしいですかね。","respondent":"田村庶務課長","answer":"こちらのほうの記載は月額報酬という形で記載しているものと、常勤の事務局の長という形の教育長で、先ほど申し上げたように下段のほうの事務局職員の中に教育長が入っているという形です。","id":"exchange-090"},{"speaker":"林委員","kind":"質問","question":"その先生については１月ごろに何々中学校の校長に、何々の役職の人が来るよと、ああいう発表をされて、品川区の教育委員会は怒らないんですか。その先生たちについては、何年間品川の教員でいるという発表はされているんですか、教育委員会は。","respondent":"河野指導課長","answer":"それから平成２０年度、再任用の期間が１年を単位で更新ですので、現在のところ何年間という形での説明はしておりません。では、このまま更新する意思はありますかということを確認させていただいた上で、都教委のほうに申請をしているというのが実態です。","id":"exchange-091"},{"speaker":"林委員","kind":"確認","question":"その辺も十分に考えてあげて、外ではなかなかわからないことがたくさんあるわけですから、斟酌をしていただければありがたいなというふうに思います。もう一つ確認だけさせてもらいますけど、これは確認なんですけど、中学校の校庭に仮園舎がつくられるということはないですね。","respondent":"田村庶務課長","answer":"まだ具体的には検討しておりませんが、荏原東の小中一貫校、これから来年度基本設計に入るということで、地域の準備会を立ち上げました。今一つの案として、どういう位置関係になるかは決まっていませんが、一時的な仮施設に使ってはどうかという考え方が一つあるという状況です。","id":"exchange-092"},{"speaker":"林委員","kind":"質問","question":"校庭、校舎、敷地内に義務教育以外の建物を建てるというのは法律的に認められるんですか。どなたに聞けばいいかよくわからない、法的な問題です。","respondent":"田村庶務課長","answer":"学校の小中学校の設置者は、地方自治体の長の、区長になっています。それと、飛び地で今まで体育館として使っていたところに幼保の一体施設を設けるという形も具体的にあります。","id":"exchange-093"},{"speaker":"林委員","kind":"質問","question":"今までもいろんな形で自治体として責任を持っていろんな施策を打ってきた１８歳までの高校生、教育委員会はどういうふうに考え、あれ。１７歳、１８歳、教育委員会の考え方を説明するよう求めました。","respondent":"堀越生涯学習課長","answer":"スポーツの部分、事実上区長部局のほうで青少年育成課とも連携をしながら区長部局のほうで進めていくという形になります。その中で、教育委員会とも連携をとりながら、実際の業務は区長部局のほうで進めていくという形になります。","id":"exchange-094"},{"speaker":"林委員","kind":"意見","question":"せっかく教育委員会の改革が進んで、仕事をこういうふうにはっきりしたわけだから、その中をきちんとしておいてほしいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"小中一貫校ですが、６校目ですが、とりあえず６校目という考え方を持っているということでご理解いただきたいと思います。一体でいきますと二葉幼稚園、大間窪小学校、荏原第三中学校という形で連携をしっかり持ってやっているということは存じあげてあります。","id":"exchange-095"},{"speaker":"林委員","kind":"質問","question":"この先、まだ一体型にしたほうが小中一貫の教育がスムーズだという考えが教育委員会の中に起きてくるんですかと聞いているわけね、これから。学事制度審議会でも数の問題ですとかいろいろ出てきているわけですから、ぜひお願いをしておきます。","respondent":"和氣小中一貫教育担当課長","answer":"あくまでも今品川区は小中一貫教育要領を持っておりますので、これを基本にして、国が変えてきたことが参考になるものであれば参考にします。最低やらなきゃいけないという部分については、全国との関係がありますので、その部分は受け入れるという考え方を持ってあります。","id":"exchange-096"},{"speaker":"川西委員","kind":"質問・要望","question":"３番目が、どういうふうな実態になっているか、介助員等がその任につけるのかどうか伺います。前回、前々回の予算特別委員会、決算特別委員会でも、我が会派の本間委員が申し上げました卒業時における６年生の卒業旅行というんですかね、あれ。","respondent":"富田学務課長、田村庶務課長","answer":"この後、１月いっぱいで小学校の抽選校で待機になった方の繰り上げ期限、中学校が２月末ということで実施をしているものです。これは学校の教育活動全般、学校が検討していく中で、このように決定したものと受けとめております。 屋上防水をやったときには、塗料会社に聞いても、その上には遮熱性塗装ができないというふうに聞いています。やっぱり具体的に検討する中で、効果は当然見込まれますので、そのように考えております。","id":"exchange-097"},{"speaker":"川西委員","kind":"質問・要望","question":"要望で構いませんが、毎度私発言しておりますので、ぜひ建設、改築関係、いっぱいありますので、取り入れてほしいと求めました。それから、冬季スキー教室、これは今日のニュースで聞きましたけれども、あっ、終わりますから言いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"南委員","kind":"質問・要望","question":"そして、この３年間会社が変わっている状況があるのかどうか、まずそこを教えてほしいと求めました。それからもう一つは、すまいるスクールの中に学童保育クラブという位置づけというのはされているのかどうか、そこもお尋ねします。","respondent":"田村庶務課長","answer":"現在、委託している会社は５社ということになります。今日も冒頭申し上げましたように、すまいるスクールの活動というのは放課後対策と学童のあわせ持った機能を持っているという形で周知しています。","id":"exchange-099"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりそうでない家庭の子どもの保育というのはおのずから求められるものが違うので、不十分だというふうに思っているのは私の見解なんですけども。ですから、その辺についての確認と、その辺について伺いたいと思うんです。","respondent":"田村庶務課長","answer":"継続してほかの学校はやっていたけど、継続している業者が５社、６社が新年度に入ると。ただ、いわゆるどこか固定した場所じゃなく、どこかほかの場所を使うという形にならざるを得ないところも若干あるかなというふうに考えています。","id":"exchange-100"},{"speaker":"南委員","kind":"質問","question":"３年目、４年目で会社が変わるということは、その件についての見解を伺います。しかし、品川区の３８校の中にどの程度準備されているのかという具体的な数字がわからないので、もう一度ここを伺いたいと思います。","respondent":"田村庶務課長","answer":"プラン２１で品川区のすまいるスクールは全国的に最初に取りかかって、学校施設の中を活用して、学校と一体に取り組むというのが目玉です。","id":"exchange-101"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、そこをぜひ紹介して、何パーセント程度は設備されていますとかと、そういうふうなことでいいですから教えていただきたい。ですから、そういうことでいいのかどうかということをちょっと聞いているので、その辺の答弁も含めてお願いしたいと思います。","respondent":"田村庶務課長","answer":"ですから、そういう意味からすれば、やはりお子さんも新しい新１年生が入ってくる。それが逆に２年生、３年生にいけば、特に新１年生については三者連携して十分対応できるというふうに考えてありますので。","id":"exchange-102"},{"speaker":"南委員","kind":"意見","question":"そうすると、もっと今回は３年に１回変わるところもあると。そういうことを区ははぎとっていくと、そういうことになるので、根本的に学童保育クラブのあり方について考えるべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"大沢委員","kind":"質問・要望","question":"３３３ページ、３４８ページの学校施設建設費、３５５ページの防空壕処理工事の３点についてお伺いします。そこがあるやにちょっと伺っておりますけども、そこらのところを行政としてどのように感じていらっしゃいますか、教えてほしいと求めました。","respondent":"田村庶務課長","answer":"校舎改築等、特に小中一貫校、当然新しい建物は密閉性という意味では、やはり今までの既存の建物に比べては高くなるというのは事実です。","id":"exchange-104"},{"speaker":"大沢委員","kind":"質問","question":"その中でご答弁も伺いました。それをでは、先に尋ねました。","respondent":"河野指導課長","answer":"しかし、一方では、インターネットで検索機能を使えば、求めている情報がたちどころに入手できるという、そういう利便性もあわせてあるのも事実です。","id":"exchange-105"},{"speaker":"大沢委員","kind":"質問","question":"先ほど市民科の授業の中で、９年の一貫の中で平均５時間か６時間その時間に割いていらっしゃるということも話を伺いました。の授業に対して時間を割くべき必要があると思いますけれども、どのようにお考えになりますか、お願いします。","respondent":"河野指導課長","answer":"そして活用していく、それが情報リテラシー、メディア・リテラシーの一番大事な部分だというふうに思います。向上というようなことについて、もっと踏み込んだ取り組みをしていこうということで、時数の増の方向で検討する予定です。","id":"exchange-106"},{"speaker":"大沢委員","kind":"質問・要望","question":"第一日野小学校ですか、３５５ページの防空壕の処理ということで伺わせていただきますけれども、防空壕が見つかりました。ただ単に、あったから、これは処理をしてしまおうと、それだけの流れでこういうふうになったんでしょうか、教えていただきたい。","respondent":"田村庶務課長","answer":"今考えられている手法は、上から穴をあけて、要するにそのままにして既存を埋め込むという形を一つの手法として考えてあります。それが一番早く処理できる内容で経費もかからないということで今回予算計上したと、そのような内容です。","id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"処理の経過はいろいろと伺いましたけど、処理以外に例えばこの場合は進んでしまっているものですから、どうのこうのというお話はしません。子どもたちに見せて、こういうものに避難をしたんだよという、そこのところはどういうふうにお考えになるのか教えてほしいと求めました。","respondent":"田村庶務課長","answer":"５０年以上前のものなので、残す価値のあるものというふうな理解はしづらいかなと、そのように考えております。","id":"exchange-108"},{"speaker":"大沢委員","kind":"質問・要望","question":"最終的に結論で処理をするのは仕方がないんですが、一考を加えながら、こういうものの取扱いをしてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"須貝委員","kind":"質問","question":"なぜ、せっかく大切な学生生活の期間、平塚小学校というのはあと１年ちょっとすればあくわけですよね。そこをなぜ借りられないのか、なぜそこを借りられないのか、教育委員会の見解をまず説明を求めました。","respondent":"田村庶務課長","answer":"やはりそういう説明を午前中ご説明したように、成績ということで新しい新１年生も入学を希望していると、そのような環境だと思います。","id":"exchange-110"},{"speaker":"須貝委員","kind":"質問","question":"これについて再度お聞きしたいんですが、これを建てるに当たって、学校教育法の中ではまだ載っていませんでした。なぜ法律の後ろ楯がないのに建てられるのか、それについてご見解を説明するよう求めました。","respondent":"田村庶務課長","answer":"あくまで今の法律の中で、例えば小学校、大井地区でしたら原小学校と伊藤中学校を施設一体型の小中一貫校に建設していますし、お尋ねの指針というのは、例えば具体的な明記といっても、その中で法律に沿ってやっているです。","id":"exchange-111"},{"speaker":"須貝委員","kind":"質問","question":"でも、小中一貫校というのは明記がされていないのに、なぜできるんですかというのを私は非常に疑問に思っています。実際、また若月教育長は中央教育審議会の中の義務教育特別部会の臨時委員でもありますが、いつ法律が後からついていくんか尋ねました。","respondent":"市川教育次長","answer":"その設置基準については、小学校設置基準、中学校設置基準という文部科学省の規則がありまして。その法制度化について動き始めている、そういう状況にあるです。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりあらぬそういう追及を受けたり、品川区というのは今までしっかりしてやってきたところですから、私はやってほしいと求めました。それは何かできるような話も昨年言っておりましたが、一つお聞きしたいんですが、ここでちょっと確認の意味です。","respondent":"河野指導課長","answer":"「中学校教諭が小学校の兼務発令を受け、校長が校務分掌権に基づき小学校の学級担任の分掌をさせることは妨げることができない」ということで、明確に回答をいただいております。","id":"exchange-113"},{"speaker":"須貝委員","kind":"確認","question":"それは本当ですか。それだけちょっと確認したいと求めました。","respondent":"河野指導課長","answer":"双方の免許、教員免許を持っていなくても、兼務発令はできます。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"どうなんですか、考え方がおかしいんじゃないかと思うんですが、私立はちゃんと一貫教育というのは前もってやっているわけですね。その辺についてご見解を説明するよう求めました。","respondent":"富田学務課長","answer":"学校の就学に当たっては、通学区域というものが小学校、中学校それぞれありますので、それがすべてのベースになるというところについてはちょっと変えられないです。","id":"exchange-115"},{"speaker":"堺委員","kind":"確認","question":"そのようなことについて確認の意味も含めまして、３２７ページの教職員の健康管理、これについても教えていただければと考えています。この主幹制度の改めて導入をしたいきさつというんでしょうかね、その辺のところにつきまして、まず教えてほしいと求めました。","respondent":"河野指導課長","answer":"学校の組織的な対応の重要性というものが非常に叫ばれていた中で。責任を持ってその組織を取りまとめ、学校の組織的な対応をさらに進めていこうということで主幹制度が導入されたというふうに理解しております。","id":"exchange-116"},{"speaker":"堺委員","kind":"確認","question":"今年の４月から東京都の教育委員会においても、これもちょっと確認をしておきたいんですが、補完する意味でつくった。その人数も主幹と同じように各学校１名とか２名とか、その辺の配置の人数、またそれに対する品川区としての考え方をちょっと教えていただけますか。","respondent":"河野指導課長","answer":"教諭の場合には、どんな主任でも対応できるという非常に経験豊かなベテラン教諭まで、一つの職層の中でくくられているのが現状です。そういう主幹の受験資格を得た教員に対しては、積極的に受験をするようにということで、私どもも進めているところです。","id":"exchange-117"},{"speaker":"堺委員","kind":"確認","question":"今教えていただいた新たな主任教諭は、従来こういう肩書き的にはと言っていいんでしょうかね、主任という名前がついた教諭の方もおられましたけども。そういう役割も担っていくという面と、それからベテラン教諭としての処遇と、ちょっとその辺をもう一回確認したいと求めました。","respondent":"河野指導課長","answer":"いわゆるベテランの先生という力もあるし、指導力もあるし、とても信頼される、そういう教員、どこの学校にも大変大勢おるわけですけれども、そういう教員に対して処遇面でも明確に位置づけたというのがこの主任教諭です。","id":"exchange-118"},{"speaker":"堺委員","kind":"質問","question":"今度生徒の側、子どもたちの側から見て、そういう改革は子どもにとってどういうプラスの影響が出てくるのかということをお尋ねしたいんです。それを教えていただけますか。","respondent":"河野指導課長","answer":"ベテラン教員の大量退職に伴って、主任教諭になった方にとっては、そういう意味では若手の育成も今まで以上に進んでいくだろう。ひいては、子どもにとってよりよい学校教育を推進するためには大変いい制度であるというふうに認識しております。","id":"exchange-119"},{"speaker":"堺委員","kind":"質問","question":"それに関連して、この４月１日から教員の免許更新制というのが始まっていくということが言われておりますね。これは２００７年６月にそういう改正教育職員免許法ですか、それ以前の教員の人とどういうふうになってくるのか、ご説明ほしいと求めました。","respondent":"河野指導課長","answer":"が、現場で教員として勤務するためには１０年に１回の免許更新講習の受講義務が課せられております。内容としては、例えば新しい教育技術に関する内容であるとか、あるいは教育課題に関する内容、これを３０時間程度受講というのが義務です。","id":"exchange-120"},{"speaker":"須藤委員","kind":"質問","question":"３２８ページの教育指導費に関連しまして質問します。最初に３３３ページの市民科・各教科充実経費、ここで平成２１年度の児童数はどのくらいの数、この辺の違いはどうなっているのか説明を求めました。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"平成２１年度の新入学予定者数ですが、小学校については２,１５０人程度ということで、７０人程度減少の見込みでありまして、中学校につきましては、１,６００人強ということで、１５０人程度増の予定です。 それから、副読本の購入費というのは、「わたしたちの品川」、３年生につくっているものですね。これも３年生、これは７年生、体育実技副読本の７年生用という形で分かれてあります。","id":"exchange-121"},{"speaker":"須藤委員","kind":"質問","question":"印刷費は区でつくったものということなんだけども、これだけうちの区ですばらしい副読本ができているんだよというものがあれば教えてもらいたい。日本人の心、規範意識とかそういったものはそんなに変わるものではないと思っていますので、そのあたりはなぜ改訂ということで考えられるのか。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"失礼いたしました。小学校全児童数の予測が１万２,５００人強、中学校につきましては４,５００人強です。 ３年、５年、８年でそれぞれ学年進行で新しいものをお渡しするということで印刷をしているものです。それから、「のびゆく品川」等についても基本はできておりますので、その一部を改訂して購入するという形になってあります。","id":"exchange-122"},{"speaker":"須藤委員","kind":"質問","question":"前に我々がプラン２１でいろいろ学校側に要請をしたりしているので、先ほど来いろいろこのことについてあるけども、そういう考え方で理解をしていいのかどうかということを説明するよう求めました。","respondent":"和氣小中一貫教育担当課長","answer":"プラン２１が始まったときから、さらにそれを進化させるということで、それを援助するためにつくったものです。","id":"exchange-123"},{"speaker":"須藤委員","kind":"質問・要望","question":"教育長に、これからさらにプラン２１を発展していくために、独自教員を採用したいというようなステップもまた出てきました。そういったところで、教育長がさらにこういったものがあるんだということが考えられれば教えてほしいと求めました。","respondent":"若月教育長","answer":"プラン２１のさまざまな実践についてご評価をいただきまして、本当にありがとうあります。それが私の大きな今の願いでもありますし、区の願いでもあろうと、こう思っておるところです。","id":"exchange-124"},{"speaker":"須藤委員","kind":"質問","question":"今の国の制度から変えていかなきゃいけない、こんなふうに思っていますので、よろしくお願いします。一つだけ、生徒数も１００人ぐらい多いというふうな数字が出ているんだけど、このあたりはわざとここに多く出すんか尋ねました。","respondent":"富田学務課長","answer":"スポーツ振興センターのこの予算上の計上というのは、平成２０年度をベースにしておりまして、まだ新年度の数が確定しない段階ですので、申しわけございません。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問・要望","question":"経験はどうでしょうか、今現在、逆に有資格者として区内には何人ほどいらっしゃるのかなというところをお聞かせいただきたい。それをベースにまたこの後質問します。","respondent":"河野指導課長","answer":"主幹教諭がさらに経験年数に応じて副校長の選考受験資格、副校長実務経験３年以上で校長の選考受験可能という運びになります。有資格者数ですけれども、現在小学校、中学校、あわせて約３０名がおります。","id":"exchange-126"},{"speaker":"土井委員","kind":"質問・要望","question":"そこでもう一つ伺います。どういう資格要件で、どういうコンセプトで選ばれてくるのかということをちょっとお聞かせをいただきたいと思うんですよ。","respondent":"河野指導課長","answer":"学校外からの校長の任用ですが、学校教育法の中で、校長の資格というのがあります。それに合わせて、各都道府県教育委員会が選考の上任用することができるという規定がございまして、今回もその規定に基づく校長任用です。","id":"exchange-127"},{"speaker":"土井委員","kind":"質問","question":"これから品川区にいらっしゃるとするならば、東京都教育委員会が認めたら、どこかにやれるのかどうなのかと。その場における、それら校長の任命等も含めた中に、区の教育委員会教育長はどういう役割をされているんでしょうかね。","respondent":"河野指導課長","answer":"その同等という解釈なんですが、そして人格、そういうようなものを総合的に東京都教育委員会のほうで面接等の選考を通して判断をするという経緯です。","id":"exchange-128"},{"speaker":"土井委員","kind":"質問・要望","question":"私の気に入った人がいるから、あなたのところで頼みますよと言われたら、はいそうですかと受けることになっちゃいますよね。その辺の、初めからそういう発想なのかどうかを含めてお聞かせをいただきたいということです。","respondent":"河野指導課長","answer":"それから、管理職候補者が自分の着任する学校を選べるのかというお尋ねですが、管理職は一切そういう意味で学校を選ぶということはできません。","id":"exchange-129"},{"speaker":"土井委員","kind":"質問・要望","question":"というのは、一つポストがなくなっちゃうんですから。ここら辺はちょっともう一回、別な意味でこういう思いだということをお聞かせいただきたいなというふうに思っております。","respondent":"若月教育長、河野指導課長","answer":"現場で経験を積んだ人が最終的に学校経営の任につくと、これが最もオーソドックスなスタイルであると、この考え方に基本的に何の変わりもありません。うちにいる有資格者… 午前中の答弁で私が申し上げたのは、とかくそういうふうに批判をされますがということで申し上げさせていただいたところです。","id":"exchange-130"},{"speaker":"土井委員","kind":"意見","question":"まさしくそのとおりなんですけれども、あまりそれを何回も言いますと、世間では教育委員会も言っているんだからななんて軽くやっちゃう可能性がありますので、こういう場所は、「株をやっているやつは」云々みたいなことになりますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"宮崎委員","kind":"質問","question":"私は３３１ページ、プラン２１推進事業に関連して伺いたいと思います。教育委員会としてはどういうふうに位置づけているのか、この位置づけといいますか、それを聞きたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"この本ですが、これはこの間私どもが文部科学省の新教育システムという開発プログラムの委託を受けながら、さまざまな検証をしてまいりました。その中に、私どもも参加をしていますが、そういう中で、自主的に出版された本です。","id":"exchange-132"},{"speaker":"宮崎委員","kind":"質問","question":"ところが、第１章で論点整理をされているんですけども、この教授は、この論点にまともに答えていないんですね。こういう人がこういうことを言っているということについて、当然読んでいると思うんですけども、ぜひ感想を伺いたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"あくまでもこれはいろんなデータに基づいて私どもがやってきたものについて、学者という立場からいろいろ分析をしていただいているものです。","id":"exchange-133"},{"speaker":"宮崎委員","kind":"質問","question":"ぎりぎりまで残してほしいということを主張しているんですね、この教授は。私は学者として変質したんじゃないかというふうに思うんですけども、ここら辺は教育委員会としてはどういうふうにお考えか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"同じ扱いができるはずがありません。ということで、ご理解いただきたいと思います。","id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"何のために出しているんだというふうに思うんですけど、そこの見解も一つ伺いたいというふうに思います。どうか尋ねました。","respondent":"市川教育次長","answer":"１点目の将来の予測ということに関連してのことですが、０歳をはじめ、その子たちが学齢に差しかかるときのことは一定の予測が立つんです。","id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、今の統廃合計画というのは非常に乱暴なやり方だというふうに思います。その点で、改めて統廃合計画に対する見解を伺いたいと思います。","respondent":"富田学務課長","answer":"現時点で統廃合計画ということを申し上げているわけではございません。学校の校舎の改築等と合わせた学校配置のあり方について検討をしてまいりますと申し上げているところです。","id":"exchange-136"},{"speaker":"宮崎委員","kind":"意見","question":"だから、これに対して区の教育委員会がどう対応するのかというのが今問われているわけですね。〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-137"},{"speaker":"三上委員","kind":"提案","question":"私は前に提案させていただきましたけども、教員にすべて配置されていないじゃないかということで、全教員に配置するべきだと言いました。第２グラウンドの、やはりきちっと擁壁をつくって、それとも全くそれはまだ検討していませんということなのかお伺いしたいと思いますとの意見を述べました。","respondent":"河野指導課長、富田学務課長、宍戸施設担当課長","answer":"残りの２名は中学校と高等学校の免許のみです。大学院での修学が終わった後、必ずもとに戻るというような条件を含めてですが… 教員の仕事の自宅への持ち帰りですが、パソコン関連のことというので私から答えします。学校長の許可を得て… 実は３０年ほど前に教育センターの工事をやったときにも、周辺の方々からの情報で防空壕を一度処理したという経緯があるというふうに聞いております。","id":"exchange-138"},{"speaker":"三上委員","kind":"質問・要望","question":"もともとがなくなってしまうわけですから、やはりどういうふうに教員が自覚して、事故というのは起きてくると思います。それから、防空壕に関しては、やはり近所の方、古くからいる方ですから、何人もいないと思うんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"教育委員会としてどうこれをとらえるんですかという質問をした記憶があるんですけど、あまりはっきりした答えがもらえなかったような気がしています。ですから、この保幼小連携について、教育委員会側としてはどうとらえているかということをちょっとお答えほしいと求めました。","respondent":"田村庶務課長、和氣小中一貫教育担当課長","answer":"私のほうから城南小学校の土地の購入についてお答えいたします。今回平成２１年度の予算計上しますので、平成２１年度中には契約に至るかなと、そのように考えております。教員、それから学識経験者に一部入っていただいて検討するということが軸ですので、そこで具体的に使えるカリキュラムをつくっていくです。","id":"exchange-140"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私もですから、買った後も正門から入ったわきですから、その中でうまく校庭を使っていただきたいなと。保育園のお子さんをどう、小学校に入ってくれば自分の生徒ですけど、その前の段階でどうとらえているかなというのを教えてもらえればと思います。","respondent":"河野指導課長","answer":"小学校入学後の１学期間ぐらい、これを進めていくためにはどうしたらいいのかというところに焦点を当てての取り組みというふうに考えてあります。","id":"exchange-141"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この私立幼稚園との関係というのをどういうふうにとらえるのかなというのが非常に疑問があります。どういう感じでとらえているのかなと、保育課のほうもあると思うんですけど、その辺のお考えを教えていただきたい。","respondent":"和氣小中一貫教育担当課長","answer":"委員指摘のとおり、公立以外に私立から上がってくる子もいらっしゃいますし、幼稚園も保育園も行かない子もいらっしゃいます。幅広く私どもこの委員会に入っていただきたいということで、私立幼稚園、保育園の代表にもお入りいただくという予定にしています。","id":"exchange-142"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あのとき質問したのが、教育振興基本計画をちょっと確認したときに、そういうのはおかしいんだというお話もありました。そこら辺のお考え、最終決断をした理由、その辺を教えてほしいと求めました。","respondent":"濱野区長","answer":"ただ、今都区のあり方検討委員会幹事会をやっている中で、大きな焦点になっているのが児童相談所の移管とこの教育の人事権の移管です。私はこれは教育委員会にしっかりやっていただくべきことだというふうに考えておりまして、二、三十分話をさせていただきました。","id":"exchange-143"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川が教育改革のあくまでも先頭で行っていただくようお願いしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":121988,"voices":334}},{"id":"h21-20090326-3","meetingId":"h21-c-budget","date":"2009年3月26日","dateIso":"2009-03-26","committee":"予算特別委員会","time":"午前１０時０２分～午後７時１３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"現在、品川区の失業率はどうなっているんでしょうか。何もわからないで、どうやって対策を立てられるのでしょうか、と、私はおしかりを受けました。","respondent":"福田企画部長、宮地区民生活事業部長","answer":"したがいまして、まずは、こうした区の総合的な施策を着実に推進していく、これが一番に肝要な点だと考えております。… 分析し、検討した上で、適格な施策を実施に移しています。２カ年にわたる１３０事業、２８億円の緊急総合経済対策を着実に実施することが… 区長が施政方針で申し上げたとおり、時々刻々と発生する行政課題に適格に対応するための再編でございまして、これを組織改正の本旨とするものです。","id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"文化や芸術等、総括的に品格を有する地域活性化の施策、政策は、今後どのように変化していくのでしょうか。その期間や方法を、どうとらえておられるのか尋ねました。","respondent":"宮地区民生活事業部長","answer":"区長も施政方針で申し上げておりましたとおり、スポーツ、活力を生み出していくといった施策にもつながっていこうかと考えております。さらに、地域を活性化していくことで息の長い、不況を乗り越える力を持たせることができるのではないかと考えております。","id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"では、最後に緊急医療対策と、その関連についてお伺いしたいと思います。","respondent":"市川教育次長","answer":"いわゆる管理内のものとして９件、いわゆる交通事故ですけれども、これが６件となっています。内訳といたしましては、骨折、打撲、裂傷、これらの外傷が大半を占めている状況です。","id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"品川区は、区立病院、特に高度医療等を有している病院と、直接、間接を問わずに運営するお考えはおありでしょうか。７００万人が高齢化社会に突入した今、いかがお考えでしょうか、説明を求めました。","respondent":"古川児童保健事業部長","answer":"そういう面から総合的に考えますと、この問題については、極めて現実的には難しいと考えざるを得ないと考えています。近隣の病院との連携をさらに充実、そして、地域医療の充実にこれからも邁進していきたいと考えております。","id":"exchange-004"},{"speaker":"原委員","kind":"質問・要望","question":"今の答弁の中で、もう少し思いをお聞かせいただきたいのは、今やはり、産婦人科医、それから小児科医等がかなり不足しておられるという状況下におきまして、医師会、また関係する機関等との連携、この辺をもう少しお聞かせほしいと求めました。","respondent":"中村品川区保健所長","answer":"地元のかかりつけの産科医のところに行っていただきますが、直ちに病院で予約をとっていただくというようなことで対応が十分にできているところです。","id":"exchange-005"},{"speaker":"原委員","kind":"意見","question":"どうか、国民の期待を全面的に受けとめまして、成果を出してくれたＷＢＣのイチロー選手のように、区民の信頼のもとに、今までにも増しましてよき品川区政を継続されますよう切望いたしまして、バトンを石田秀男委員に渡しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この基準額は、２３区の中でも高いのか、ということをまず伺います。それから、４期の保険料の決定に当たり、さまざま工夫をされたということもあると思いますので、そのことも教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"特に厚生年金とか企業年金を受給されている方々についてかなりきめ細かく対応させていただいておりまして、８段階、または引き下げになっているです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど４,１００円というお話の中で伺っていくと、１期から４期まで合わせても、品川区が平均を若干下回る金額に、この介護保険料自体もなってきた。先ほど言った責務もあるわけですから、いろいろお考えになったわけで、そこら辺も踏み込んで答弁をお願いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そのような中で、私は、給付総額の１割程度を基金として持つことは必要ではないかという考え方になっております。もう一つは、適切なケアマネジメントがされて、健全な介護保険制度の運営がされているということの結果だと考えているところです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"２３区でしっかり足並みをそろえて、都市加算をしっかりと訴えていく、勝ち取っていくべきだろうと。ここら辺の点を踏まえて、やっぱり２３区が足並みをそろえるということも含めて、どう考えていらっしゃるかお聞きしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"一つの考え方とは思いますけれども、２３区の部長会で、保険料が高い自治体は多分慎重になるだろうと思います。まだ余力はあると思いますが、そのような見地も含めまして、今後の運営状況をよく見ていくということが肝要かと考えているところです。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この部分の最後にお聞きしたいのは、ここら辺の意識の問題をしっかり持っていないと、崩壊をしてしまうんだと。保険とは何か、なおかつ、区民に対する責務とは何か、ここら辺の点の最終的なお考えを、もう一度お聞きしたい。","respondent":"木下福祉高齢事業部長","answer":"せっかく築き上げてまいりましたこの介護基盤が崩壊しては何にもならないわけでありますので、いいサービスを適切に運営できるようなものを目指していくべきだと考えておりまして、やはりそういう視点を持って意見を上げていくべきだと考えております。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今後３年間で、伺ったところによると、部長級が１２名定年退職される。ここら辺も教えてほしいと求めました。","respondent":"市岡総務部長","answer":"品川区の技術会議というものの設置をもうすぐ行いますけれども、職員育成の中に、再任用の方の知恵を借りるということも考えております。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"非常に大きいわけでありますから、そこら辺の影響をどのように解消されているのか、ここら辺の点も教えていただきたい。これはどこでもかけられなくて、どこもないんですけれども、具体的になぜだめなのかということを、再度改めて聞きたいと思います。","respondent":"市岡総務部長","answer":"最後に、ほんとうに常態的に人が足りないということであれば、もちろん人事異動での定数の変更も行います。区民サービスのために、品川区の組織、あるいは職員が全力を挙げて取り組んでいるという姿勢をお示ししたいと考えております。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１００人いれば、どういうチームでも、必ずあるわけですよ。まずやってみて体験をするということが必要だと考えておりますけれども、こういうところに対する手当て、考え方をお聞かせ願いたいと思います。","respondent":"市岡総務部長","answer":"平成１３年度から事業部制をとって久しく経つわけですが、くくった視野で考えていくということが、職員の中にしっかり定着をしてきていると思います。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"後でもう１回、それを伺うときもあると思うので、それは最後にもう一度聞きたいと思います。前回のときは、ローリングが毎年行われていましたけれども、今回は、どのように考えていらっしゃるかということも、あわせて伺いたいと思います。","respondent":"福田企画部長","answer":"実施計画をこれまで３年としてきた根拠ですが、ご案内のとおり、実施計画は１０年をスパンとする長期基本計画の下位計画という位置づけにあります。今回、この考え方は継続してまいりたいと考えておりますので、今回の実施計画も３年間をスパンとするものとしています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その感覚が、２年と３年の違いというところを、何か思いがあって３年にしているんだということであれば、改めてそこはお伺いしたい。内部的には２年間のスパンで物事を考えて、２年分の予算を組んでいくということが、お考えを教えていただきたい。","respondent":"福田企画部長","answer":"確かに、何らかのメルクマールとして実施計画が役割を果たすとすれば、やはりどうしても３年間ぐらいのスパンは必要ではないかと考えております。ただ、基礎自治体が予算のレベルまでの精度を持った２年間の計画を持つことを考えますと、２年目の財源の措置を見込むことが。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"提案","question":"それから、先ほど、人材育成のことがあったんですけれども、モデル事業も、若手の職員などの提案をどんどん取り入れていくべきだろうと考えています。２年をめどにしっかりけりをつけると、人材育成にもつながると考えていますので、そこら辺の考え方も教えてほしいと求めました。","respondent":"福田企画部長","answer":"実施計画に載っていない事務事業でありますけれども、例えば、５％のマイナスシーリングですとかいうようなことを行いまして。施政方針で区長が申し上げましたように、これが区の基本方針、モデル事業のあり方を検討しています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やめるべきはすぱっといくというのは、何となく続いている部分についての見直しの考え方を、再度聞きたい。気合の部分でも教えていただきたいのは、この実施計画をしっかりとしたものにできると期待して質問を終わりますので、最後にそこだけ、答えるよう求めました。","respondent":"福田企画部長","answer":"毎日、あるいは予算編成のプロセスという中で常時行っている、そういうふうに考えております。今回の実施計画を策定するというものですので、区民の皆さんに、品川区政を実感してもらえると自信を持っているところです。","id":"exchange-017"},{"speaker":"金野副委員長","kind":"確認","question":"１点目の就学前教育について、質問いたします。そこで、まずはじめに確認をいたします。","respondent":"古川児童保健事業部長","answer":"開始の時期につきましては、この間、さまざまな角度から検討してまいりまして、昨年、「就学前乳幼児教育のための手引き」を作成しました。したがいまして、自治体としては、平成２０年度からすべての公私幼保で、このプログラムに基づいた保育教育を実施しています。","id":"exchange-018"},{"speaker":"金野副委員長","kind":"質問","question":"そこで、今、あえて就学前教育と掲げて取り組み出している内容と、これまでの乳幼児教育と、どのような違いがあるのでしょうか。これが品川区の推進する就学前教育ですという熱意と、具体的な取り組みを、いま一度説明を求めました。","respondent":"古川児童保健事業部長","answer":"したがいまして、品川区が今後進めていくであろう就学前教育は、当然に小学校、中学校につながってまいります。規範意識を身につけるといったことにおいては、幼保小中というのは一貫したものがあるだろうと考えて、そういう取り組みをしています。","id":"exchange-019"},{"speaker":"金野副委員長","kind":"質問・要望","question":"次に、このことを踏まえて、具体的な取り組みとして、平成２１年度に実施をされる就学前教育の事業の内容について質問いたします。事業を進めて今年で３年目となるようですが、事業の目的と、事業内容をお聞かせほしいと求めました。","respondent":"古川児童保健事業部長、市川教育次長","answer":"園児が小学校にスムーズに進学するというこの１点におきまして、小学校の教員、さらには保護者も一体となった交流を進めてまいりました。さらには学校の校長先生による保育園の保護者に対するさまざまな学校についての説明の場… 私からは、平成２１年度の具体的な事業の進め方ということで、説明をします。平成２１年度につきましては、これまでの取り組みを踏まえて、小学校への接続ということで、具体的な道筋をつけるべき年と認識をしています。","id":"exchange-020"},{"speaker":"金野副委員長","kind":"意見","question":"今、この報道に対して、もう少し詳しくお知らせいただけるかなと思っていたんですが、今一度、この方針、接続期の中味を、プレスで発表したことも含めて、もう少しお答えほしいと求めました。","respondent":"市川教育次長","answer":"取材のコアといたしましては、先ほど申し上げたように、推進組織を立ち上げた上でさまざまな課題を検討していくということが中心部分です。あそこに書いてあることも含めて、今後のことについては、推進組織の中で検討してまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"金野副委員長","kind":"提案","question":"わかりました、今後の検討の中で、協議会というのでしょうか、その中で進めていくということであると。いろいろなところでご提案ができればしていきたいと考えていますので、どうか接続期がうまくいきますよう、ご尽力ほしいと求めました。","respondent":"古川児童保健事業部長","answer":"全体の中での今後の検討を待つ部分がありますけれども、１００名から百四、五十名の間になるのかなと考えています。幼稚園が全体で９園ありますけれども、需用動向といったものを考えながら、幼保一体施設については計画化していきたいと考えております。","id":"exchange-022"},{"speaker":"金野副委員長","kind":"質問・要望","question":"本区が就学前教育を推進する上で、幼保一体施設とそうでない単独の施設、いわゆる幼稚園や保育園との進め方の違いがあれば、教えていただきたい。どの園に通っても、同じ品川区の就学前教育が受けられる環境整備と機会の確保が必要だと思いますが、ご所見を説明するよう求めました。","respondent":"古川児童保健事業部長","answer":"加えて、さまざまな教材の整備でありますとか、さらには、一番中心となるのは保育者の資質です。教育課程をしっかりととらえた環境づくりをしていくことが大事でありますので、そういう点につきましても、今は研修体制を整えているという状況です。","id":"exchange-023"},{"speaker":"金野副委員長","kind":"提案","question":"昨年の第１回定例会の代表質問の中で取り上げた際、引き続き国に要望してまいりますとの答弁がありましたが、お伺いしたいと思います。就学前教育が受けられない子どもたちをなくしていくためにも、経済的な支援も含めたきめ細やかな対策を先駆的に実施すべきと強く要望しますとの意見を述べました。","respondent":"市川教育次長、古川児童保健事業部長","answer":"昨年７月ですが、今後１０年間を通じて目指すべき教育の姿ということで、幼児教育の無償化ということが検討課題であるという位置づけをしています。かつ計画的に取り組むべき施策ということで、幼児教育の無償化の検討を含む… 最後に１点ございました、幼稚園、保育園に通っていない子どもへの取り組みということなんですが、なかなか実態を把握するのは難しいと考えています。","id":"exchange-024"},{"speaker":"金野副委員長","kind":"質問・要望","question":"国も検討課題で、またそれを実施していく方向性でいるということがわかりましたので、どうか引き続き要望を上げてほしいと求めました。次に、大きなテーマの２点目ですが、待機児童対策についてお伺いいたします。","respondent":"古川児童保健事業部長","answer":"なかなか難しい部分があると考えています。あるいは自営の方々における、自営でもフルタイムであれば同等ですけれども、そういう中での待機児の傾向が全体として強いだろうと考えています。","id":"exchange-025"},{"speaker":"金野副委員長","kind":"確認","question":"そこで、確認をいたします。さて、平成２１年度には、南大井保育園にも拡張されることは承知しておりますが、なぜ、同じ大井地域に１園増やすのか、設置理由を説明するよう求めました。","respondent":"古川児童保健事業部長","answer":"平成２０年度からモデル的に行いました、短時間対応の方でも入りやすいような特別枠を設けたのが伊藤保育園、児童センターで実施している内容です。今後の対応としましては、地域バランスを考慮した計画的な実施を、次年度以降も進めていきたいと考えています。","id":"exchange-026"},{"speaker":"金野副委員長","kind":"提案","question":"その枠だったので仕方ないのですが、今のご答弁の中にもありましたが、私もバランスよく短時間保育を設置していただきたいと要望いたします。認証保育所のように無認可園にも、所得に応じた保育料助成制度を実施すべきと考えております、提案したいと思いますとの意見を述べました。","respondent":"古川児童保健事業部長","answer":"保育の実施責任は、市町村にございまして、児童福祉法第２４条に基づく保育に欠ける子どもを入所させる。認証保育所の設置基準は、認可保育園の設置基準にほぼ準じているということから、保育料の負担を少しでも軽減したいということで実施しています。","id":"exchange-027"},{"speaker":"金野副委員長","kind":"質問・要望","question":"無認可園も、待機児童の解消の一翼を担っていくことは否めないと思いますので、今後も引き続き要望してまいりたいと考えています。次に、待機児童対策の２点目ですが、保育ママについてお伺いいたします。","respondent":"古川児童保健事業部長","answer":"区としての取り組みということですが、なかなかやっていただける方が少なくて、この数年間は対応ができておりません。今後、その検討の結果につきまして、広く区民の方々に公募できる機会があればと考えているところです。","id":"exchange-028"},{"speaker":"金野副委員長","kind":"質問","question":"本区は、そのことについてどのようにお考えでしょうか。既に何か対策はお考えでしょうか、説明を求めました。","respondent":"古川児童保健事業部長","answer":"まだこれから実施基準でありますとか、さまざまなガイドラインを国のほうで検討し、そして示されていくという状況にあります。今後、それらの推移を見ながら、研修体制についても十分に固めていきたいと考えております。","id":"exchange-029"},{"speaker":"金野副委員長","kind":"提案","question":"例えば、その方々に核となっていただいて、ファミリー・サポートの提供会員から保育ママ制度の流れをつくっていくことを提案をいたします。同時に、そうした支援スタッフで構成した、現在の空き店舗を活用した品川宿おばちゃんちのような子育て支援拠点の設置を提案いたしますとの意見を述べました。","respondent":"古川児童保健事業部長","answer":"さまざまなところで、私どもと一緒に子育てにかかわっていただくような、そういう環境をつくっていきたいと思ってあります。ぜひそういう方々には、品川区が始めます保育ママ制度に参加をしていただければと、このように考えております。","id":"exchange-030"},{"speaker":"金野副委員長","kind":"質問","question":"今後のこの品川区の一人の子どもの成長ために、トータル的な支援がなされますよう、就学前教育に一層のご尽力をいただきますようお願いして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"生活必需品の代表的なものといたしまして、肉、魚、野菜の生鮮三品の店舗数の、近年の推移も伺いたいと思います。なぜ商店街のシャッターが閉まってしまうのか、区民の購買行動の変化や商店街の現状について、区の認識をお聞かせほしいと求めました。","respondent":"宮地区民生活事業部長","answer":"そういう意味では、区としては、地域で存続していけるようなさまざまな施策を、これまでも実施してきておりました。価格の問題、いろいろ支援はしているんですが、そうした中でも少しずつ減ってきているというような循環を重ねているという認識でおります。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問・要望","question":"認識を伺いました。これまでのさまざまな商店街支援策との違いを明確に述べてほしいと求めました。","respondent":"宮地区民生活事業部長","answer":"支援するにしましても、さまざまな事業を実施できないところが、これまでの現状と考えています。効果が見込めるような層がある、５０店舗以上ありますと、実際に取りかかっているです。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう配慮をしたリース事業にしてほしいという質問をいたしましたところ、都のほうからも、温暖化対策促進の観点から。品川区としても、区独自の環境配慮型の設備投資促進についてご尽力をほしいと求めましたけれども、お考えを説明するよう求めました。","respondent":"久保田環境清掃事業部長","answer":"平成２１年度に、品川区の地球温暖化対策地域推進計画を策定予定ですので、大きな課題の一つであるという認識を持っております。これまでの事業との連携とか、区として具体的にどういうものができていくか、十分に検討してまいりたいと考えております。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"最初に、在宅支援、特に同居家族がいる方への訪問介護サービスについて伺います。要するに、その基準や給付決定の仕組みについて、わかりやすく教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"というような形で、障害とか、疾病等の特殊な事情がある場合については、ケース・バイ・ケースで具体的に対応しています。なお、このような考え方については、一応、厚生労働省の告示と通知で基本的な考え方が示されているです。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区のほうで適用していると理解をしていいのか、どうか、一つ確認をさせてほしいと求めました。こういうふうに満足できるサービスに向けた仕組みをとってほしいと求めましたが、ご所見を伺いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"区の適切なケアマネジメントの中で対応ができている、もちろん０ではありませんけれども、対応ができていると考えております。したがいまして、今、具体的に新システムでの認定というお話がございましたけれども、そのことについては、予定をしておりません。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"アンケートで０.６％という数字ですけれども、現場の実態をしっかりまた見聞きをしながら進めていただきたいと、これは要望します。それから、次に施設サービス、特別養護老人ホームについて伺いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"つまり、施設を収容の場から生活の場に変更すると、こういうような説明がされているかと思います。多床室の場合ですと、比較的集団的な対応もできますので、２.５対１ぐらいでも回していくことができる等々の特色があると考えています。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"国や都とねばり強く交渉しながら、特別養護老人ホームの施設整備を図ってほしいと求めましたけれども、ご所見を伺います。区とまた民間の協働等も踏まえ、こういう施設の拡充について、お考えを伺いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"今後の高齢者施策を進めていこうということが明確に出てきておりますので、私どもとしても、第１号の事業になるのではないかと考えているところです。例えば民間の中でも対応できるような可能性があるとすれば、今後、検討していく余地はあるのではないかと考えています。","id":"exchange-038"},{"speaker":"若林委員","kind":"質問・要望","question":"介護予防の観点も踏まえ、どのようなものになるのかお聞かせほしいと求めました。健康づくりにいそしめるという環境づくりもあると思いますので、そのような観点からのまちづくりについても、お聞かせほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"とりあえずロイヤルサニーと鈴ケ森公園の２カ所の事業成果を見ながら、今後の拡充という部分については判断をしていきたいと考えております。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問","question":"実行していく上での課題なども含めて質問いたします。あえて、改めてなぜ目黒川が汚れてしまうのかについても、説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"しかし、向こう３０年間かかりますので、事後対策としての浄化対策もきちっとやっていかなければいけない。実験を行いました東京湾のきれいな水を導入するというのは、今後、検討しています。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、目黒川に生活汚水、生活排水や雨水が流れてしまう地域、世帯数がわかれば教えてください。これからどのように図っていくのか、行政と住民が一体となった目黒川の浄化対策について、お聞かせほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"港区の５区と、最上流の三鷹市の５区１市で、約４５.８km2になっております。品川区でも、そういう対策に対しての助成措置という制度を設けておりますので、今後も広くＰＲしてご協力をしていただくように努力をしてまいります。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"間もなくできると伺っておりますので、これの活用の仕方について、地域との協働の観点からお聞かせください。地域の方の声を、今、どのように受けとめられておりますか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"広く地域の方々や団体、ＮＰＯが活動できるような、自由に使えるような空間として仕組みづくりを検討してまいりたいと思います。こういった空間づくりを行いますので、水質も、目黒川に向けたまちづくりに住民とともに進んでいきたいと考えております。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"区民の満足度がまた格段に上がるように長期基本計画でしっかり頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"初めに、認可保育園増設で、待機児解消を求める質問です。子育て支援の品川区とは言えない状況ではないか尋ねました。","respondent":"古川児童保健事業部長","answer":"実は出てまいりますので、需用がどこまで継続していくか、なかなか難しいだろうととらえています。それぞれの要求に対してこたえていくということを、今、それぞれ一人ひとりのケースに合わせて対応しています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"細かい中味をおっしゃっていただいたので、数字的にはなかなか難しいのですが、事前にお伺いをした数字です。この点、直球を投げますが、質問にお答えをほしいと求めました。","respondent":"古川児童保健事業部長","answer":"認可保育園がなかなか対応し切れていない長時間、あるいは低年齢児に対する保育を認証保育所が担っているのは事実です。私どもは、それに加えまして、既存の保育園の定員の増でありますとか、弾力化、さまざまな手法をもって対応しております。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、認可保育園をつくらないのはなぜかと、なぜ認可保育園をつくらないのかという点をお伺いしました。１,６９２名が認可保育園を希望しているところに、自治体としてはぜひ誇りを持って、親の願いにこたえるべきであると思いますが、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"この６月には、一番待機児の多い五反田地区に１カ所、認証保育所が間もなく誕生する予定です。私どもは、そういう意味におきましては、認証保育所も認可保育園と同じような気持ちで、これからも接していきたいと考えております。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点、ちょっとお伺いしたいんですが、保育園は子どもたちがあふれている状況であるという話を聞いています。この点に対しては、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"単に保育所等での対応ができない場合というただし書きがありますけれども、区は、東京都が認定をしている認証保育所もその一つととらえています。飯沼委員が異論をお持ちであるということについては、認識をさせていただきました。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、２点目です、困難地域である大崎駅周辺ですけれども、この辺のことでお伺いをします。それに対応した保育園施設をどうするのか、再開発計画に義務づけるべきではないかと思いますが、この点はいかがか尋ねました。","respondent":"古川児童保健事業部長、岩田まちづくり事業部長","answer":"同じ認識ですし、大崎地区、さまざまなところでの一定のボリュームについても承知をしております。そういったことも、私どもは、大いに誘致等も含めて対応していきたいと考えております。発生する子どもの保育施設については、きちっと再開発事業を行う事業主のほうで、そういった子育て支援施設は設けていただく。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"再開発計画に義務づけをするべきではないかという質問をいたしましたので、ちょっとその辺を答えてほしいと求めました。そのデータに基づいてきちんとした計画を立てなければいけないと思って、その辺もお伺いしたいんですが、いかがか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"少し説明が足りなかったようですが、子育て支援をしている各部署に対して事業内容を説明し、その地域にある子育て支援施設のキャパと比較をして。したがって、法定再開発で入居された方の子どもたちが、この地域で子育て支援施設に入れないということはないと申し上げたわけです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それから、もう１点ですが、待機児童、約１３０名の受け皿として、緊急対策を求めたいと思います。ぜひとも努力をしてほしいと求めましたが、いかがか尋ねました。","respondent":"岩田まちづくり事業部長、古川児童保健事業部長","answer":"再開発の分野のことだけ、私のほうから、再度お答え申し上げます。大崎で行っている法的再開発事業で、住宅系を持っている再開発事業で、現実にそういったことはないというふうにご説明をさせていただいたものです。 待機児に対する施策もそうでありますし、子育ての中での働きやすい環境づくりも、当然つくっていくべきだと考えています。そう意味では、保育園の中で最大限受けいれられるような策を、今考えていると、先ほども申し上げました。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安心して働ける支援を、ぜひ拡大をしていただけることを強く要望して、次の質問に移ります。共産党は、自立支援法は廃止をし、当事者参加でつくり直すことを求めていますが、改めて、この点に対して見解をお伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"加えて、品川区のほうは、通所系の部分については、９割以上参加で３,０００円の助成等を行って、一定の支援をしているところであります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害者自立支援法のことですけれども、自立をどう解釈をされているのか、お伺いをしたいと思います。自立とは、経済的な自立を言い、お金を払って福祉を買う人になりなさいということなのか、どうか、この自立について、お伺いをしたい。","respondent":"木下福祉高齢事業部長","answer":"そういう考え方ではありませんで、必要な支援を受けながら生活をしていく、これが現在における障害者の自立という考え方だと思います。そういう意味で、自己選択、自己決定できる主体という意味で記述していると考えております。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区内においてどのように変わっていくのか、３点、お伺いします。３点目は、安定した生活のための就労支援について、どう変わるのか説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"一人でも地域の中で暮らせるような支援をしていこうということでありまして、区としては、そのようなことを進めていきたいと考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特にグループホーム、ケアホームについては、具体的な、早急に設置生活を立ててほしいのでよろしく、そこのところのご答弁をお願いしたいと思います。身近なところで目に触れるところに置いていただきたいとか、職員の方々にも研修にぜひ取り組んでいただきたいのですが、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"そのような形で暮らしている方が多くいるということも十分に認識しておりますけれども、今後、必要な対応を考えていきたいと考えています。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何回も質問させていただいていますが、この点はもう１回、お願いしたいと思います。経験を広めていただきたいということと、雇用の場の拡大に取り組んでいただきたいのですが、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"例えば特例子会社がとっているような形を考えていく必要があるだろうと思っておりまして、私どもとしては研究していく予定にしております。条件が整ったところで、機会があれば、そのようなことについて検討をしていきたいと考えています。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"チャレンジして、大変で疲れてきたら、もう１回戻ってまた出て行けるというようなフォローを十分にしていただきたいと思っています。第三者として、ビル風の事前と事後の測定をして科学的に立証するのが区の役割であると思っていますが、いかがか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"委員のおっしゃるようなことは、区は考えておりません。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、考えてほしいと求めました。ご答弁をお願いいたします。","respondent":"岩田まちづくり事業部長","answer":"先ほども申しましたように、区の責務として、第三者的な立場で住民と事業主の間に立って何かしなければいけないという認識はございません。前にも款別でもお答えしましたように、きちっと説明責任を果たすように、今後も指導してまいります。","id":"exchange-057"},{"speaker":"川西委員","kind":"提案","question":"そうすると１５万円を切るわけですから、７万円の家賃が払えるのがやっとかと思います。ですから、二つの質問要件について、お答えいただきたいとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"１点目が、大井林町に予定しております新しいタイプの高齢者住宅というのは、こうほうえんで行っているものとは違います。いずれにしましても、これから設計と経営シミュレーションを行ってまいりますので、そのような中で判断をさせていただきたいと考えています。","id":"exchange-058"},{"speaker":"川西委員","kind":"質問","question":"今のご説明で大方わかりましたけれども、現在の入居要件、老朽化、立退き、著しく危険、これに加えて、もう少し応募できる人を増やすというのは、どういうふうにお考えか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"年金が年間２００万円といいますと、七万円ぐらいの方、家賃が５万円から７万円ぐらいの水準ではないかというお話だったと思います。今、ご指摘の部分は、そういう形の中で実現するということになるのではないかということを申し上げたところです。","id":"exchange-059"},{"speaker":"川西委員","kind":"質問・要望","question":"５番目に一時預かり事業の拡大、ですから、５番目は小規模住宅型児童養育事業。２歳未満児の待機児が非常に多いと、区において始めるということは、大変前向きな姿勢として要望をするものです。","respondent":"古川児童保健事業部長","answer":"研修について一定のプログラムを用意しつつありますけれども、そこでも全体１２１時間の研修を、国のほうも基準をこれから示していくという段階です。人の確保の点とあわせまして、資質の向上策については十分に検討をし、早期にこの事業を立ち上げていきたいと考えております。","id":"exchange-060"},{"speaker":"川西委員","kind":"提案","question":"野球場、その一画に、食の原材料である野菜づくりの菜園を取り入れていただけないでしょうかということを提案します。バスに乗っていけば八潮団地に着くんですから、これから具体化されるので、ぜひお答えをほしいと求めました。","respondent":"福田企画部長","answer":"あそこのまちづくり検討委員会の皆さんに、私どもの考え方をお示しをして、意見交換の場を持ちたいと考えております。ご提案の趣旨を生かすことができるかどうか、八潮の皆さんのご意見も伺いながら、検討してまいりたいと考えております。","id":"exchange-061"},{"speaker":"川西委員","kind":"質問・要望","question":"こういうものが将来どういう製品に再生されるのか、いろいろな方法があると思いますけれども、それもやはりわかりやすく出す。すぐに改善できなくても、いかがなものかなとお願いしたいと思います。","respondent":"久保田環境清掃事業部長","answer":"あまりにもひどい場合については、そういうような指導、啓発も検討していきたいと考えているところです。例えば昨年１０月からの分別変更に伴って、地域での説明会においては、汚れぐあいはこの程度ならいいですとかいうような説明をしてきたわけです。","id":"exchange-062"},{"speaker":"川西委員","kind":"質問・要望","question":"それから、最後にお願いしておきたいことは、きゅりあんでやる人権集会というんですか、あれに企業の人が随分きていらっしゃるように思います。それからもう一つは遮熱性塗装も含めて研究、促進計画について、伺います。","respondent":"市岡総務部長","answer":"これが基本的な認識です。遮熱性塗装については、技術開発もどんどん進んでおりまして、これらの研究動向等も注意しながら計画的に進めてまいりたいと考えております。","id":"exchange-063"},{"speaker":"川西委員","kind":"質問","question":"気持ちというか、必要性はわかっていても、なかなか今おっしゃった１４カ所しか進んでこなかった。それから、計画でおっしゃった量しか進まないのは、そのため、予算の関係と理解しておいてよろしいんか尋ねました。","respondent":"市岡総務部長","answer":"特にグリーン・ニューディールではありませんけれども、この辺の産業分野での革新というのは飛躍的に進むだろうと考えておりますので、いろいろ私どもとして検討を進めて導入をしていきたいという考えです。","id":"exchange-064"},{"speaker":"川西委員","kind":"質問・要望","question":"ですからやるかやらないかの意欲だけにとどまっています。もっとさまざまな芸術交流もしていただきたいけれども、私の意見でありますので、ご答弁をお願いいたします。","respondent":"市岡総務部長","answer":"大使館に限るということは全く考えておりませんけれども、人のつながりということを重視しまして、このような計画から始めてみたいです。これらを友好協会が持っているいろいろな人脈とも連携しながら、いろいろな角度で研究をしていきたいと考えております。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"質問いたしますが、風害や積雪による雪害等について、区ではどのような対策をなされていますでしょうか。それ以降、何か対策がなされるようになったのか、お伺いいたします。","respondent":"宮地区民生活事業部長","answer":"事前対策はなかなか難しいんですが、事後、速やかに対応するという対策が一番効果的だと考えております。スピーディに対応するということで、また防災計画を見直す中で、新たに改善できるところなどはつけ加えするという対応をとることとしております。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"次に、教育について伺います。どこから聞いたんですか」と話したら、ここの部分で教えていただきたいんですが、お願いします。","respondent":"市川教育次長","answer":"身近な２３区の中でも、そういったことが原因となっていわゆるうわさが流れたかもしれません。それから通学距離、通学時間、うわさ以上の何ものでもないということでご理解いただければと思います。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"質問するんですが、昨年１１月ごろでしょうか、さまざまな相談がありました。あえて小学校入学時におけるブロックの分け方について伺いたいんですが、やはり一本化するべきではないかと思うんですが、いかがか尋ねました。","respondent":"市川教育次長","answer":"こうした配慮の面で、現行の４ブロックに分けたということは理にかなって、また実情に則していると考えております。もう１点、さまざまなタイプの学校を選択することができるという視点からも、現在のブロック別に分けていることの意義があると考えております。","id":"exchange-068"},{"speaker":"渡部委員","kind":"確認","question":"いわゆるブロックの境界上にある方たちへの何らかの配慮というのが、どうも頭にひっかかっていたもので、この質問をさせていただいた経緯があります。いわゆるブロック内の小中一貫校に対して入学希望が出せるという考えでよろしいのか、もう１回、そこだけ確認したいと求めました。","respondent":"市川教育次長","answer":"そのとおりです。","id":"exchange-069"},{"speaker":"渡部委員","kind":"質問・要望","question":"教育改革プラン２１の中でも、これからもしっかり運用していっていただきたいと思って、次の質問に移ります。次に、教育の中の家庭教育について伺います。","respondent":"市川教育次長","answer":"委員から今ご紹介のございました文部科学省が作成しております家庭教育手帳も、同じような役割を担っているものと認識しております。子どもの発達に応じて３段階に分けてあらわされておりますけれども、これから私どもの啓発活動の中でお知らせをしてまいりたいと考えています。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろ近隣の方から伺いました。区としてはどこまで把握して、例えばこれが中学生等だった場合、学校とどのような連携をとられているのか尋ねました。","respondent":"市川教育次長","answer":"それから、早期対応、これが一つ要点だと考えています。３番目の、こうした取り組みのほかに地域連携の取り組みがあるかですけれども、ケースに応じた対応をしているというのが実情です。","id":"exchange-071"},{"speaker":"渡部委員","kind":"意見","question":"今、どういうことが起こっているというような形でいいと思うので、この件を聞かせていただきました。そういう部分で、中学生の健全育成の活動の場の提供に最適と考えておりますが、ご見解を説明するよう求めました。","respondent":"古川児童保健事業部長","answer":"２５館、さまざま情報交換をさせていただき、そして児童センター職員の持っているマンパワーと施設を有効に活用していきたい。そういった意味では、人的な問題についてご懸念のご意見がございましたけれども、現状で十分に対応できていると考えております。","id":"exchange-072"},{"speaker":"渡部委員","kind":"質問","question":"こちらも、決算特別委員会で質問しました、在宅介護の件について、もう一度、お伺いをします。国の施策の問題もありましょうが、在宅での介護をしている家族の方々に、もっと手厚く何か援助することはできないか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"在宅で介護をしている方への支援ということですけれども、現在、区のほうの施策の中では、介護者の激励の集いとか、介護者の研修制度、それから介護をしている方々の家族会を支援する、このような事業を行っているところです。","id":"exchange-073"},{"speaker":"渡部委員","kind":"意見","question":"介護保険を、何とか在宅の方にいろいろ使えないのかなと考えた中で、介護保険の横出しサービスの中の市町村特別給付がありますが、これは家族に対しては有効に使えるのかと思ったのですが、区はどのように考えていらっしゃいますか、お願いいたしますとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"家族支援というご指摘ですけれども、これは１号保険料を財源に、あるいは家族等へのサービスに使えるという制度があります。検討したことはあるんですけれども、現在まで、ここの制度を使った具体的なサービスの実績はございません。","id":"exchange-074"},{"speaker":"渡部委員","kind":"提案","question":"販売数を増やしてほしいという提案もあったんですが、これとあわせて、使用できる商店について伺ってまいります。商品券を求めるために早く並んだんだけれども、売り切れちゃったなんてことのないように、対策をしておかないといけないとの意見を述べました。","respondent":"宮地区民生活事業部長","answer":"区内約４３カ所の郵便局の実績に基づいて販売していく予定ですので、それで対応できるかと思いますが、それで対応をしていきたいと考えております。今後の経済状況、社会状況等を勘案しまして、検討してまいります。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"もう既に９年から１０年ぐらいになるでしょうか、１０時園の利用状況、その例でお聞きしたいと思います。利用動向、どのような変化があったか尋ねました。","respondent":"古川児童保健事業部長","answer":"平成１７年度に開始いたしまして、３カ年ですが、５６０件ぐらいの利用であります。そういう就労環境に対する、行政としての最終的に、こういう保育形態を取らざるを得ない状況にあると考えています。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"１０時保育園については、長時間保育をした子どもたちの影響がどうなったのかということは、その傾向があれば教えていただきたいと思っています。その点に関して、親の利用者側の気持ちがどうなっているのか、お聞きしたいと考えています。","respondent":"古川児童保健事業部長","answer":"もうかれこれ１０年近く実施してきました。これを使うこともないと考えていますけれども、そういう中ではぎりぎりの中で、多くの親たちは病児保育を利用していただいていると考えております。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"私は、冒頭にも申しましたけれども、熱のある子どもをだれが面倒みるんでしょうかというところです。ですから、どうしても休めないという方はいらっしゃいますから、その方は利用せざるを得ないだろうということはわかりました。","respondent":"古川児童保健事業部長","answer":"９園は必要ないだろうと考えています。１０時までの夜間の実態を見た上で、縮小し、そして拠点的な中での運営を図っていきたいと考えております。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"まさか、品川区はそういうことは考えてはいないでしょうね、ということを、ここで確認をさせてほしいと求めました。きずなというのをどう考えているのか、何をどうすることで、そのきずなを、子ども、親の中でつくっていくのかということをお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"保護者の支援を通しまして、私ども積極的にかかわっていく、そのことが子育ちの環境を整備していくことにつながるだろうと考えています。今、このきずなをいかに高めていくのかという課題だろうと考えていますし、私どもの子育ても大きな役割を担っているだろうと考えています。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"延長をどういうふうに考えているのか。就労に向けてどういうことをされているのか、どういうアドバイスを、お聞きしたいと思います。","respondent":"市川教育次長、古川児童保健事業部長","answer":"すまいるスクールの利用時間については、延長の考えは持ってございません。放課後は明るいうちに家に帰って、親の帰りを待つといった生活習慣を、家庭の中で子どもに身につけさせることが基本であると考えています。 １０時までの保育というのは、子どもの成長をいかに支えていくかというところで、私どもやっている内容です。十分に私どもの保育園、実施園の園長、職員を含めて対応していきたいと考えております。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"これは、どういう目的で、どのような構想のもとで事業を展開すると考えているのか、子育て支援の地域のあり方について、お聞きします。幼稚園の垣根を、これからどんどん下げていっていただくようなことができないだろうかということで、今後の政策を含めてお答えをお願いいたします。","respondent":"古川児童保健事業部長","answer":"３人の課長がおりますので、地域とより密着した施設展開、施設経営はできないだろうかという中から考えた一つのやり方だと考えています。幾つかの考え方を持ちまして、地域を主体にした施設を経営していきたいと考え、４月からそれを実施していきたいと考えています。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"４月から、地域に根ざしたという形で、ブロックに分けて見ていきましょうという、非常に期待したいと考えています。先ほどもちょっと質問しましたが、地域で子育てするということを広げてほしいと求めましたが、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"さまざまな事業展開をする中で、当然に、親御さん、ＰＴＡの方々も一緒にかかわっていただきたいと考えています。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"では、区長には、これからの品川区、どういう子どもたちになってほしいのか。そのビジョンみたいなことを、ちょっとお聞きしたいと思います。","respondent":"濱野区長","answer":"そういう子どもを産み、育てていく、そういう生活に前向きに取り組めるような環境をつくっていくことが自治体の役割ではないかと考えています。若干足りないかもしれませんが、以上です。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"この一連の経過、そしてその成果、また今回の事業のあり方について、お聞きしたいと思います。それにあわせまして、平成２１年度の事業がありますが、協働事業についての選定方法、それから選定理由についても、お聞きしたいと思います。","respondent":"福田企画部長","answer":"事業の計画はどうなっているかというようなところにも着目をするような事業のあり方を検討して、今回、一定の助成をするというところまできたです。","id":"exchange-084"},{"speaker":"西本委員","kind":"提案","question":"これは平成１８年度以前からいろいろ考えて検討されての経緯なのかなと考えていますが、区民提案事業というのがあります。そういう新規の方たちをどういうふうに発掘していくのか、発展させていくのかというところをお聞きしたいと思いますとの意見を述べました。","respondent":"福田企画部長","answer":"かえってそれが損なわれてしまことがないように、そうしたことに注意をすることも、区の役割だろうと考えております。ああいうことをやっているんだという輪を広めていただく、そんなことも、私ども期待しています。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"お金を出して、例えば広報紙に宣伝を載せる、そういうことをしているんでしょうか。そもそも協働ということをテーマに掲げるのであれば、協働のあり方、それから考え方を、もう少しお聞きしたいと思います。","respondent":"福田企画部長","answer":"あるいはいろいろな事業に実際に取り組んだり、ひいてはある一定の地域、これが現段階における区の協働のあり方ではないかと考えております。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"それから、やはり後払いになるんでしょうか。前払いでないと、運動資金がないとなかなか活動できないということがありますので、支払い方法は何か、お考えがあるのかお聞きしたいと思います。","respondent":"福田企画部長","answer":"それから、寄付が集まらない場合ですけれども、平成２１年度は、この基金を１,０００万円でスタートさせたいと考えています。区には、後で精算していただきます概算払いという制度がありますので、その活用が検討できるのではないかと思います。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"この寄付で、皆さんに支えられて活動していますというところを、ぜひ広報活動してほしいと求めました。団体の自由な発想でそれを運営していただくお考えがあるのか、どうか、お聞きしたいと思います。","respondent":"福田企画部長","answer":"活動拠点は、私どもも必要だろうと考えています。何とか具体的に検討できないか、現在、そういう場所を含めて、検討しています。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"いい関係づくりを、これからも求めて頑張ってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"２００９年度の予算編成についてお伺いいたします。再度、伺いますが、この地域コミュニティ活性化事業の創設の目的と、何を成果と考えているのか説明を求めました。","respondent":"日下部企画財政課長、宮地区民生活事業部長","answer":"私のほうから、まず、平成２１年度の予算編成に関してのご質問にお答えします。障害者団体による外出サポート事業の立ち上げ支援、介護給付ということで、大変きめ細かく充実を図ってきているです。 そういった意味もありまして、今回、新たな助成金の仕組みをつくったものです。効果というふうに考えてもよろしいかと思いますけれども、新たな町会の担い手の育成とか、そういったものが主なものになってくるかと考えております。","id":"exchange-090"},{"speaker":"井上委員","kind":"提案","question":"議論の過程の中で、どのような案があったのか、そして、最終的な判断の根拠を伺います。名称は違っても、内容は市民活動を推進する基金と理解しておりますが、その理解でよいのかということも、あわせてお伺いいたしますとの意見を述べました。","respondent":"福田企画部長","answer":"覚えていただくということが大切だろうと考えまして、シンプルに、地域振興基金としたものです。市民活動という概念が、いろいろな活動を通してまちを活性化していこうという意味にとらえれば、同じだと考えております。","id":"exchange-091"},{"speaker":"井上委員","kind":"提案","question":"それとも一本化をされるのか、今後の組織的にはどうなるのかということを１点、お伺いいたします。それから、運用に当たってですが、区民にとっては、区民活動支援事業も協働事業提案制度も、同じような事業に思われますとの意見を述べました。","respondent":"福田企画部長","answer":"区とだれかだけではなくて、そういう区民同士の連携というような役割を持っている、そこが大きな相違点です。それから、窓口でありますけれども、これは既に創設が終わっておりますので、基本的には新しい事業部の中で対応してまいりたいと考えております。","id":"exchange-092"},{"speaker":"井上委員","kind":"提案","question":"協働事業提案制度のほうですが、もう一度伺いますけれども、この中で選考方法がよくわかりませんでした。助成する判断基準を何にするのか、３点ほど、お伺いいたしますとの意見を述べました。","respondent":"福田企画部長","answer":"それから、助成の上限額でありますけれども、１件当たり大体５０万円ぐらいを考えておりまして、６団体、予算額３００万円という計算になるものです。","id":"exchange-093"},{"speaker":"井上委員","kind":"提案","question":"協働事業提案制度と地域振興基金の活用は別の事業だと考えていますので、今、お答えいただいたのは協働提案のほうかなと考えています。今後、どのように考えていらっしゃるのか、お伺いしたいと思いますとの意見を述べました。","respondent":"福田企画部長","answer":"ちょっと説明が不足したかもしれませんが、ただいま申し上げました５０万円掛ける６団体で３００万円は、地域振興基金です。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"１３年間で、アジアで活動する１００の市民団体に、既に３,５１１万円の助成が行われています。運用には、ぜひこだわってほしいと求めましたけれども、この選考に対する見解を伺います。","respondent":"福田企画部長","answer":"私見ていますと、非常に雄弁な方もおられます、資料づくりのうまい方もおられます。こつこつとやっておられる方もおられまして、やはり、公開の場というわけにはいかないだろうと考えております。","id":"exchange-095"},{"speaker":"井上委員","kind":"質問・要望","question":"寄付の文化を育てるためにも、ぜひこれから先の課題にもなりますけれども、検討をしていただきたいと要望しておきます。そして指定管理者の品川総合福祉センターは、この工事に幾ら支出するのか、財源がどこから出てくるのか伺います。","respondent":"木下福祉高齢事業部長","answer":"前倒しで実施したいということでありますので、その中でまず対応していこうという形で整理をさせていただいたということが、この経過です。平成２１年度予算で、２,５００万円近くの数字になりましょうか、この工事費の部分の助成として予定しています。","id":"exchange-096"},{"speaker":"井上委員","kind":"確認","question":"事業計画書を確認したときに、この工事と２００９年度の工事とは全然場所が違うというふうに、確認をお願いいたします。","respondent":"木下福祉高齢事業部長","answer":"１階の作業室とか、２階の浴室等の整備でありますので、同じです。それを、平成２０年度分の支出については品川総合福祉センターのほうの、心身障害者福祉会館のほうの収支差額の中で事前対応をするという考え方です。","id":"exchange-097"},{"speaker":"井上委員","kind":"確認","question":"今、確認のところで、品川総合福祉センターの収支差額で、工事費は幾らぐらい支出するのかという金額はわかりますか。","respondent":"木下福祉高齢事業部長","answer":"法人のほうとしては、この工事全体として４３０万円余の負担が出てまいります。自立支援給付でやっているところについては、介護報酬等に、一定の収支差額の部分は指定管理者が負担をするというのは当然の考え方だと考えています。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問","question":"大分、法が変わった福祉施設というところで、利用料金が増えたとか、いろいろな状況にあるかと思うんです。この中で第１８条には疑義の決定ということで、どうなのか、そういったところはきちんと手続がされているのか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"今、ご指摘がありました部分については、いわゆる身体障害者デイサービスというのが、平成１８年１０月から廃止になりました。収入が減っているように見えますけれども、全体としては、その部分については確保されているです。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"確実にそういうものがそろえられているのか、どうなのかということを、後でお答えほしいと求めました。指定管理者なんですけれども、現在、品川区が行っている指定管理の事業数と、指定管理者の数をお伺いしたいと思います。","respondent":"木下福祉高齢事業部長、福田企画部長","answer":"所定のいわゆる書類上の手続ですけれども、これは当然、されております。 事業数と申しますか、公の施設の数は平成２１年４月の予定といたしまして８６施設、事業者数１３です。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"今回は心身障害者福祉会館５年の継続で、こういったときに、いろいろな課題が見えてくるような仕組みが必要かと思うんです。今後、モニタリングの制度について、もう少し精度を上げていくとか、工夫が必要かと思うんですが、いかがか尋ねました。","respondent":"福田企画部長","answer":"私ども、いろいろな事業を運営していく中で、いつもこれでいいのかという問題意識は全般的に持っているものです。特にモニタリング制度というわけではございませんけれども、そういう問題意識を持ちながら事業を進めているところです。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問","question":"改めてお伺いをいたしますが、第３期計画が終了年度を迎え、どのように評価しているのか伺います。２点目は、２００５年の法改正で、どのような評価をされているのか伺います。","respondent":"木下福祉高齢事業部長","answer":"いわゆる保険制度というのは保険事故に対応するという考え方からすると、第４期を含めまして、判断すべき課題と考えています。なお、特別給付につきましては、平成１２年の法創設時から、制度としてはございましたので、今回、設けられたものではありません。","id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"つまり６５歳以上の方の保険料だけを使うというもので、６５歳以上の方が、理解度がどのぐらいと認識しているのか。介護保険料を払っている第１号被保険者に市町村特別給付のサービスについて、３点、お伺いいたします。","respondent":"木下福祉高齢事業部長","answer":"日々の相談の中でケアマネージャーが一番困っていることについて、昨年５月、全員から意見を出してもらいました。そのような現場の声を踏まえて取り上げたということでありますから、これは当然、被保険者が期待している内容のものであると思っているところです。","id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"課税世帯を６段階に分けているんですが、どういう調査をして、意見聴取をしてきたのかということが大変気になっているんです。そのことについて、説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"そのねらいは、基準額を下げるためというよりは、むしろ、段階間の差を丁寧に見直しをしていく、その結果として９段階になったということであります。９段階にすることによって、私どもとしては、かなり工夫をした保険料設定と考えています。","id":"exchange-104"},{"speaker":"井上委員","kind":"質問","question":"払うほうから言えば、３００万円でも１,０００万円でも同じというのでは、区民の理解が得られないと思うんです。最終９段階を３００万円以上とした理由をお伺いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"月当たりで言うと３５万円という収入で、かなり大きい数字、つまり厚生年金プラスその他不動産収入があるぐらいの方々ということです。その方々については、３００万円と区切ることよって、９段階にさせていただいたということであります。","id":"exchange-105"},{"speaker":"井上委員","kind":"意見","question":"生活者ネットワークでも、５００万円以上という１０段階の設定を新たに見直すようにという意見を添えて、パブリックコメントを提出したところです。パブリックコメントを実施した目的と、どういうスケジュールで実施したのか、時系列でお示しくださいとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"最終的な締めをし、今年１月２０日、厚生委員会で事業計画の骨子案を説明させていただきました。３月２日の厚生委員会で条例審議をいただいたということでありまして、一定の、この期間の中ですることができたと考えております。","id":"exchange-106"},{"speaker":"井上委員","kind":"質問・要望","question":"２００５年の第２回定例会で、市民に周知して活用していくよう求めたときに、それだけに即応性と柔軟性において利点がある。３カ年が過ぎまして、募集期間が１４日では短すぎること、伺います。","respondent":"福田企画部長","answer":"平成１９、２０年度と２年が過ぎまして、委員が今おっしゃったような課題があるという認識は持っておりません。ただ、これからどのような工夫ができるのか、これは引き続き検討してまいりたいと考えております。","id":"exchange-107"},{"speaker":"井上委員","kind":"意見","question":"お互いにパブリックコメントの意義を見出せないでいるというのが、多くの自治体の様子であり、品川区の様子だと思います。公聴会、審議会などさまざまな事前の市民参加手続を行った上で、パブリックコメントを最終過程に置くと考えたほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"}]},{"id":"topic-02","title":"休憩前に引き続き、会議を開きます。 第８号議案、平成２１年度品川区一般会計予算に対する修正案","agenda":"休憩前に引き続き、会議を開きます。 第８号議案、平成２１年度品川区一般会計予算に対する修正案","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１８５項目にわたり、区長に政策要望いたしました町会支援策の充実、数多くの提言が取り入れられたことを評価いたします。行財政改革の推進が図られることを強く要望し、意見表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"堺委員","kind":"提案","question":"区議会公明党が提案をしてきた第４期介護保険料について、数多くの予算が計上されており、評価するものであります。款別審査や総括質疑の中で求めた意見や提案については、真摯に受けとめて、今後の施策に反映されるよう強く要請いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"南委員","kind":"提案","question":"資材高騰している時期に、区民が切実に求めている公共住宅や特別養護老人ホーム、保育園建設は後回しして、開発に巨額な税金投入はやめるべきです。最後に、我が党提案の高齢者医療入院時負担軽減支援金条例に対応する予算修正に賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"土井委員","kind":"意見","question":"緊急総合経済対策の一環とも言える０９年度予算の審査を終え、および介護保険特別会計の各会計予算原案すべてに賛成、修正案には反対します。長期基本計画の着実な実現と、区民ニーズにこたえるさらなる前進に、我が会派議員の提起が今後とも反映されるよう望みますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問・要望","question":"１００年に一度と言われる大不況に突入し、失業が増えるなどして、区民の所得も減少しています。大変厳しい状況にありますので、区内商品券などを使った消費拡大策の実行や、増え続ける生活弱者へのさらなる支援を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"西本委員","kind":"提案","question":"区がすべきこと、区民がすべきことを十分に把握し、両者が高め合い、良好な関係であって初めて真の品川区が求める姿と思います。我が会派委員の提案、要望した項目について積極的に受けとめていただき、無所属の会の意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"市川委員","kind":"質問・要望","question":"市民に最も身近な自治体の果たすべき役割、責任ととらえ、力を尽くされるよう要望します。以上、当会派からの要望として、今後のご検討に生かしていただくことを願いまして、生活者ネットワークの意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":129229,"voices":258}}]);
